-- Nauka: kurs „Analiza matematyczna” (19 lekcji). Uruchom PO nauka.sql.
-- Wklej całość w Supabase → SQL Editor → New query → Run. Ponowne uruchomienie nadpisuje lekcje nową wersją.

insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-01-functions', $lekcja${"tldr":"A function is a rule that gives exactly one output \\(y\\) for every allowed input \\(x\\). In this lesson you learn how to find the domain (allowed inputs) and the range (possible outputs). You meet the basic \"building blocks\": linear, quadratic, power and root, exponential and logarithmic functions, and their key graphs. You practise reading the domain of a formula with fractions, roots and logarithms, which is a classic first exam task. In economics, linear functions describe cost and revenue, and exponential functions describe compound growth of money.","notes":[{"point":"A function gives exactly one output for each input in its domain.","slide":null},{"point":"Domain conditions: denominator \\(\\neq 0\\), expression under an even root \\(\\ge 0\\), logarithm argument \\(> 0\\). Combine them by intersection.","slide":null},{"point":"In \\(f(x) = ax + b\\) the slope \\(a\\) tells how much \\(f\\) changes when \\(x\\) grows by 1; in a cost function it is the cost of one more unit.","slide":null},{"point":"A parabola opens up if \\(a > 0\\) and down if \\(a < 0\\); its extreme value is at the vertex \\(p = -b/(2a)\\).","slide":null},{"point":"\\(a^x\\) (with \\(a > 0, a \\neq 1\\)) is always positive, passes through \\((0,1)\\), and grows if \\(a > 1\\).","slide":null},{"point":"\\(\\log_a x\\) is defined only for \\(x > 0\\), passes through \\((1,0)\\), and is the inverse of \\(a^x\\).","slide":null},{"point":"Compound interest \\(K_n = K_0(1+r)^n\\) is exponential growth in \\(n\\).","slide":null},{"point":"Break-even quantity solves \\(R(x) = C(x)\\); profit is \\(R(x) - C(x)\\).","slide":null}],"concepts":[{"term":"Function","definition":"A rule that assigns exactly one value \\(f(x)\\) to each \\(x\\) in the domain.","pl":"funkcja","slide":null},{"term":"Domain","definition":"The set of all inputs \\(x\\) for which the function is defined.","pl":"dziedzina","slide":null},{"term":"Range (set of values)","definition":"The set of all outputs \\(f(x)\\) the function takes.","pl":"zbiór wartości","slide":null},{"term":"Zero of a function","definition":"An \\(x\\) with \\(f(x) = 0\\); where the graph meets the \\(x\\)-axis.","pl":"miejsce zerowe","slide":null},{"term":"Slope","definition":"The coefficient \\(a\\) in \\(ax + b\\); change of \\(f\\) per unit increase of \\(x\\).","pl":"współczynnik kierunkowy","slide":null},{"term":"Vertex of a parabola","definition":"The highest or lowest point of a parabola, \\((p, q)\\).","pl":"wierzchołek paraboli","slide":null},{"term":"Exponential function","definition":"A function \\(a^x\\) with \\(a > 0\\), \\(a \\neq 1\\); the variable is in the exponent.","pl":"funkcja wykładnicza","slide":null},{"term":"Logarithmic function","definition":"A function \\(\\log_a x\\), the inverse of \\(a^x\\), defined for \\(x > 0\\).","pl":"funkcja logarytmiczna","slide":null},{"term":"Break-even point","definition":"The quantity where revenue equals cost, so profit is zero.","pl":"próg rentowności","slide":null}],"flashcards":[{"q":"Domain condition for \\(\\sqrt{A}\\)?","a":"\\(A \\ge 0\\)","slide":null},{"q":"Domain condition for \\(\\ln A\\)?","a":"\\(A > 0\\)","slide":null},{"q":"Domain condition for \\(\\dfrac{A}{B}\\)?","a":"\\(B \\neq 0\\)","slide":null},{"q":"Formula for the \\(x\\)-coordinate of a parabola's vertex?","a":"\\(p = -\\dfrac{b}{2a}\\)","slide":null},{"q":"When does \\(ax^2 + bx + c\\) have two real roots?","a":"When \\(\\Delta = b^2 - 4ac > 0\\)","slide":null},{"q":"Range of \\(e^x\\)?","a":"\\((0, \\infty)\\)","slide":null},{"q":"Which point does every \\(\\log_a x\\) pass through?","a":"\\((1, 0)\\)","slide":null},{"q":"Compound interest formula (annual compounding)?","a":"\\(K_n = K_0(1 + r)^n\\)","slide":null},{"q":"\\(\\log_2 32 = ?\\)","a":"\\(5\\)","slide":null},{"q":"What does the slope of a linear cost function mean?","a":"The cost of producing one more unit (variable cost per unit).","slide":null}],"quiz":[{"q":"What is the domain of \\(f(x) = \\dfrac{1}{x - 2}\\)?","options":["\\(\\mathbb{R} \\setminus \\{2\\}\\)","\\((2, \\infty)\\)","\\(\\mathbb{R} \\setminus \\{-2\\}\\)","\\(\\mathbb{R}\\)"],"correct":0,"explanation":"Only the denominator matters: \\(x - 2 \\neq 0\\), so \\(x \\neq 2\\). All other numbers are allowed.","slide":null},{"q":"What is the vertex of \\(f(x) = x^2 - 2x - 3\\)?","options":["\\((-1, 0)\\)","\\((2, -3)\\)","\\((1, -4)\\)","\\((-1, -4)\\)"],"correct":2,"explanation":"\\(p = -\\frac{-2}{2} = 1\\) and \\(f(1) = 1 - 2 - 3 = -4\\).","slide":null},{"q":"What is the domain of \\(f(x) = \\ln(x + 3)\\)?","options":["\\([-3, \\infty)\\)","\\((-3, \\infty)\\)","\\((3, \\infty)\\)","\\(\\mathbb{R} \\setminus \\{-3\\}\\)"],"correct":1,"explanation":"The log argument must be strictly positive: \\(x + 3 > 0\\), so \\(x > -3\\); the endpoint is not included.","slide":null},{"q":"Which function is decreasing on all of \\(\\mathbb{R}\\)?","options":["\\(f(x) = 2^x\\)","\\(f(x) = e^x\\)","\\(f(x) = x^2\\)","\\(f(x) = 0.5^x\\)"],"correct":3,"explanation":"An exponential \\(a^x\\) decreases when \\(0 < a < 1\\). \\(x^2\\) decreases only for \\(x < 0\\).","slide":null},{"q":"\\(\\log_2 16 = ?\\)","options":["\\(8\\)","\\(4\\)","\\(2\\)","\\(32\\)"],"correct":1,"explanation":"\\(2^4 = 16\\), so the logarithm is 4.","slide":null},{"q":"The cost function is \\(C(x) = 500 + 12x\\). What does the number 12 mean?","options":["Fixed cost","Price of one unit","Cost of producing one more unit","Break-even quantity"],"correct":2,"explanation":"12 is the slope: each extra unit adds 12 to total cost. 500 is the fixed cost.","slide":null},{"q":"What is the range of \\(f(x) = e^x\\)?","options":["\\(\\mathbb{R}\\)","\\([0, \\infty)\\)","\\([1, \\infty)\\)","\\((0, \\infty)\\)"],"correct":3,"explanation":"\\(e^x\\) is always positive but gets arbitrarily close to 0 and never reaches it.","slide":null},{"q":"You deposit 1000 PLN at 10% per year, compounded annually. Value after 2 years?","options":["1200 PLN","1210 PLN","1100 PLN","1221 PLN"],"correct":1,"explanation":"\\(1000 \\cdot 1.1^2 = 1210\\). 1200 is simple interest (no interest on interest).","slide":null}],"lang":"en","lesson":{"intro":"Almost everything in economics is a function: cost depends on the number of units, savings depend on time, demand depends on price. Before we can do limits and derivatives, we need to be comfortable with the basic functions and their graphs.","sections":[{"h":"What is a function? Domain and range","body":"A function \\(f\\) assigns to every \\(x\\) from a set \\(D\\) exactly one value \\(y = f(x)\\).\n\n- The **domain** \\(D_f\\) is the set of all allowed inputs \\(x\\).\n- The **range** (set of values) is the set of all outputs \\(f(x)\\).\n- The **zero** (root) of a function is an \\(x\\) with \\(f(x) = 0\\). On the graph, it is where the curve meets the \\(x\\)-axis.\n\nIf the domain is not given, we take the largest set of real numbers for which the formula makes sense. Three rules cover almost every exam task:\n\n\\[ \\frac{A}{B}:\\ B \\neq 0 \\qquad \\sqrt{A}:\\ A \\ge 0 \\qquad \\log_a A:\\ A > 0 \\]\n\nIf a formula has several \"dangerous\" parts, write all the conditions and take the common part (intersection).","example":{"task":"Find the domain of \\(f(x) = \\dfrac{\\sqrt{x+2}}{x-1}\\).","steps":["Root: \\(x + 2 \\ge 0\\), so \\(x \\ge -2\\).","Fraction: \\(x - 1 \\neq 0\\), so \\(x \\neq 1\\).","Take both conditions together: \\(x \\ge -2\\) and \\(x \\neq 1\\)."],"answer":"\\(D_f = [-2, 1) \\cup (1, \\infty)\\)"},"tip":"Do not forget the square brackets: for a root the endpoint is included (\\(\\ge\\)), for a logarithm it is excluded (\\(>\\))."},{"h":"Linear functions: cost, revenue, break-even","body":"A linear function has the form\n\n\\[ f(x) = ax + b \\]\n\n- \\(a\\) is the **slope**: when \\(x\\) grows by 1, \\(f(x)\\) changes by \\(a\\). If \\(a > 0\\) the function is increasing, if \\(a < 0\\) it is decreasing, if \\(a = 0\\) it is constant.\n- \\(b\\) is the **intercept**: the value at \\(x = 0\\) (where the line crosses the \\(y\\)-axis).\n- The graph is a straight line. Domain: all real numbers \\(\\mathbb{R}\\).\n\nIn economics: total cost \\(C(x) = FC + v\\cdot x\\), where \\(FC\\) is fixed cost and \\(v\\) is the variable cost per unit. Revenue at a fixed price \\(p\\) is \\(R(x) = p\\cdot x\\). Profit is \\(P(x) = R(x) - C(x)\\). The **break-even point** is where \\(R(x) = C(x)\\).","example":{"task":"A firm has fixed costs of 200 and a variable cost of 5 per unit. It sells each unit for 9. Find the break-even quantity.","steps":["\\(C(x) = 200 + 5x\\), \\(R(x) = 9x\\).","Break-even: \\(9x = 200 + 5x\\).","\\(4x = 200\\), so \\(x = 50\\)."],"answer":"The firm breaks even at \\(x = 50\\) units. Above 50 units it makes a profit."},"tip":"The slope of a cost function is the cost of one extra unit. Later you will call this marginal cost."},{"h":"Quadratic functions: vertex and roots","body":"A quadratic function has the form\n\n\\[ f(x) = ax^2 + bx + c, \\quad a \\neq 0 \\]\n\nIts graph is a **parabola**. If \\(a > 0\\) the arms go up (minimum at the vertex). If \\(a < 0\\) the arms go down (maximum at the vertex).\n\n- Discriminant: \\(\\Delta = b^2 - 4ac\\).\n- If \\(\\Delta > 0\\): two roots \\(x_{1,2} = \\dfrac{-b \\mp \\sqrt{\\Delta}}{2a}\\). If \\(\\Delta = 0\\): one root \\(x_0 = -\\dfrac{b}{2a}\\). If \\(\\Delta < 0\\): no real roots.\n- Vertex \\(W = (p, q)\\) with \\(p = -\\dfrac{b}{2a}\\), \\(q = f(p) = -\\dfrac{\\Delta}{4a}\\).\n- Range: \\([q, \\infty)\\) if \\(a > 0\\), \\((-\\infty, q]\\) if \\(a < 0\\).","example":{"task":"For \\(f(x) = x^2 - 6x + 5\\) find the roots, the vertex and the range.","steps":["\\(\\Delta = 36 - 20 = 16\\), \\(\\sqrt{\\Delta} = 4\\).","\\(x_1 = \\dfrac{6 - 4}{2} = 1\\), \\(x_2 = \\dfrac{6 + 4}{2} = 5\\).","\\(p = \\dfrac{6}{2} = 3\\), \\(q = f(3) = 9 - 18 + 5 = -4\\).","\\(a = 1 > 0\\), so the parabola opens up and the range starts at \\(q\\)."],"answer":"Roots \\(1\\) and \\(5\\); vertex \\((3, -4)\\); range \\([-4, \\infty)\\)."},"tip":"Quick check: the vertex lies exactly halfway between the two roots, here \\((1+5)/2 = 3\\). A profit function \\(P(x) = -x^2 + 20x - 64\\) has its maximum at the vertex \\(x = 10\\), \\(P(10) = 36\\)."},{"h":"Power and root functions","body":"A power function has the form \\(f(x) = x^a\\).\n\n- \\(a = n\\) natural (\\(x^2, x^3, \\dots\\)): domain \\(\\mathbb{R}\\). Even powers look like a parabola, odd powers look like \\(x^3\\).\n- \\(a = -1\\): \\(f(x) = \\dfrac{1}{x}\\), a hyperbola. Domain \\(x \\neq 0\\).\n- \\(a = \\tfrac{1}{2}\\): \\(f(x) = \\sqrt{x}\\). Domain \\(x \\ge 0\\), range \\([0, \\infty)\\).\n\nUseful rules for powers (you will use them all the time):\n\n\\[ x^{-a} = \\frac{1}{x^a}, \\qquad x^{\\frac{m}{n}} = \\sqrt[n]{x^m}, \\qquad x^a \\cdot x^b = x^{a+b}, \\qquad (x^a)^b = x^{ab} \\]","example":{"task":"Write \\(f(x) = \\dfrac{3}{\\sqrt{x}}\\) as a power of \\(x\\) and give its domain.","steps":["\\(\\sqrt{x} = x^{1/2}\\), so \\(\\dfrac{3}{\\sqrt{x}} = 3x^{-1/2}\\).","Root needs \\(x \\ge 0\\); the denominator needs \\(\\sqrt{x} \\neq 0\\), so \\(x \\neq 0\\)."],"answer":"\\(f(x) = 3x^{-1/2}\\), domain \\((0, \\infty)\\)."}},{"h":"Exponential functions and compound growth","body":"An exponential function has the form\n\n\\[ f(x) = a^x, \\quad a > 0,\\ a \\neq 1 \\]\n\n- Domain \\(\\mathbb{R}\\), range \\((0, \\infty)\\): the graph is always above the \\(x\\)-axis.\n- It always passes through \\((0, 1)\\).\n- If \\(a > 1\\) it is increasing (e.g. \\(2^x\\)); if \\(0 < a < 1\\) it is decreasing (e.g. \\(0.5^x\\)).\n- The most important base is \\(e \\approx 2.718\\), giving \\(e^x\\).\n\n**Compound interest.** If capital \\(K_0\\) earns interest rate \\(r\\) per year, compounded once a year, after \\(n\\) years we have\n\n\\[ K_n = K_0 (1 + r)^n \\]\n\nThis is an exponential function of \\(n\\).","example":{"task":"You deposit 1000 PLN at 5% per year, compounded annually. How much do you have after 3 years?","steps":["\\(K_3 = 1000 \\cdot (1.05)^3\\).","\\(1.05^3 = 1.157625\\)."],"answer":"\\(K_3 = 1157.63\\) PLN (rounded)."},"tip":"Write the rate as a decimal: 5% is \\(0.05\\), so the growth factor is \\(1.05\\), not \\(1.5\\)."},{"h":"Logarithmic functions","body":"The logarithm answers the question \"to which power?\":\n\n\\[ \\log_a b = c \\iff a^c = b \\qquad (a > 0,\\ a \\neq 1,\\ b > 0) \\]\n\nSo \\(\\log_2 32 = 5\\) because \\(2^5 = 32\\). \\(\\ln x = \\log_e x\\) is the natural logarithm.\n\nThe function \\(f(x) = \\log_a x\\) is the inverse of \\(a^x\\):\n- Domain \\((0, \\infty)\\), range \\(\\mathbb{R}\\).\n- It passes through \\((1, 0)\\).\n- Increasing if \\(a > 1\\), decreasing if \\(0 < a < 1\\).\n\nRules: \\(\\log_a(xy) = \\log_a x + \\log_a y\\), \\(\\log_a \\dfrac{x}{y} = \\log_a x - \\log_a y\\), \\(\\log_a x^k = k \\log_a x\\).\n\nLogarithms let us solve for time in growth problems: from \\(a^n = b\\) we get \\(n = \\dfrac{\\ln b}{\\ln a}\\).","example":{"task":"Find the domain of \\(f(x) = \\ln(x - 5)\\) and solve \\(f(x) = 0\\).","steps":["Log argument must be positive: \\(x - 5 > 0\\), so \\(x > 5\\).","\\(\\ln(x-5) = 0 \\iff x - 5 = e^0 = 1\\), so \\(x = 6\\)."],"answer":"\\(D_f = (5, \\infty)\\); the zero is \\(x = 6\\)."},"tip":"\\(\\ln 1 = 0\\) and \\(\\ln e = 1\\). These two facts solve many short exam questions."}],"formulas":["Domain rules: \\(\\frac{A}{B}: B \\neq 0\\); \\(\\sqrt{A}: A \\ge 0\\); \\(\\log_a A: A > 0\\)","Linear: \\(f(x) = ax + b\\), slope \\(a\\), intercept \\(b\\)","\\(\\Delta = b^2 - 4ac\\), \\(x_{1,2} = \\dfrac{-b \\mp \\sqrt{\\Delta}}{2a}\\)","Vertex: \\(p = -\\dfrac{b}{2a}\\), \\(q = -\\dfrac{\\Delta}{4a}\\)","\\(x^{-a} = \\dfrac{1}{x^a}\\), \\(x^{m/n} = \\sqrt[n]{x^m}\\)","\\(\\log_a b = c \\iff a^c = b\\)","Compound interest: \\(K_n = K_0(1 + r)^n\\)","Break-even: \\(R(x) = C(x)\\); profit \\(P(x) = R(x) - C(x)\\)"],"exercises":[{"task":"For \\(f(x) = 3x - 2\\) compute \\(f(4)\\) and find the zero of the function.","hint":"Substitute \\(x = 4\\); for the zero solve \\(3x - 2 = 0\\).","answer":"\\(f(4) = 10\\); zero at \\(x = \\tfrac{2}{3}\\)."},{"task":"Find the domain of \\(f(x) = \\dfrac{1}{x^2 - 4}\\).","hint":"The denominator cannot be 0.","answer":"\\(x^2 \\neq 4\\), so \\(D_f = \\mathbb{R} \\setminus \\{-2, 2\\}\\)."},{"task":"Find the domain of \\(f(x) = \\sqrt{x - 1} + \\ln(5 - x)\\).","hint":"Two conditions: root \\(\\ge 0\\), log argument \\(> 0\\).","answer":"\\(x \\ge 1\\) and \\(x < 5\\): \\(D_f = [1, 5)\\)."},{"task":"Find the roots and the vertex of \\(f(x) = x^2 - 4x - 5\\).","hint":"\\(\\Delta = 16 + 20\\).","answer":"\\(\\Delta = 36\\); roots \\(-1\\) and \\(5\\); vertex \\((2, -9)\\)."},{"task":"A bakery has fixed costs of 300 PLN per day and each cake costs 4 PLN to make. A cake sells for 10 PLN. Find the break-even number of cakes.","hint":"Solve \\(10x = 300 + 4x\\).","answer":"\\(6x = 300\\), so \\(x = 50\\) cakes."},{"task":"You invest 2000 PLN at 4% per year, compounded annually. What is the value after 2 years?","hint":"\\(K_2 = K_0 (1.04)^2\\).","answer":"\\(2000 \\cdot 1.0816 = 2163.20\\) PLN."},{"task":"Find the range of \\(f(x) = -2x^2 + 8x - 3\\).","hint":"\\(a < 0\\), so the vertex is a maximum. Compute \\(p\\) and \\(f(p)\\).","answer":"\\(p = 2\\), \\(q = f(2) = 5\\); range \\((-\\infty, 5]\\)."},{"task":"At 10% per year (compounded annually), after how many full years does an investment at least double?","hint":"Solve \\(1.1^n = 2\\) with logarithms: \\(n = \\dfrac{\\ln 2}{\\ln 1.1}\\).","answer":"\\(n \\approx 7.27\\), so after 8 full years."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-02-sequences', $lekcja${"tldr":"A sequence is an ordered list of numbers \\(a_1, a_2, a_3, \\dots\\) given by a formula for \\(a_n\\). You learn to check if a sequence is monotonic (always going up or down) and bounded. The main skill is computing the limit of \\(a_n\\) as \\(n \\to \\infty\\), using simple rules and a few standard tricks (divide by the highest power, multiply by the conjugate). The number \\(e\\) appears as the limit of \\((1 + 1/n)^n\\), and limits of this type are an exam favourite. In economics, \\(e\\) gives continuous compounding: \\(K = K_0 e^{rt}\\).","notes":[{"point":"A sequence is a function of \\(n = 1, 2, 3, \\dots\\); to get \\(a_{n+1}\\) replace \\(n\\) by \\((n+1)\\).","slide":null},{"point":"Check monotonicity by the sign of \\(a_{n+1} - a_n\\).","slide":null},{"point":"Every monotonic and bounded sequence is convergent; a bounded sequence alone need not be (e.g. \\((-1)^n\\)).","slide":null},{"point":"\\(\\frac{\\infty}{\\infty},\\ \\infty - \\infty,\\ 0\\cdot\\infty,\\ 1^\\infty\\) are indeterminate forms and need transformation.","slide":null},{"point":"For polynomial ratios divide by the highest power; equal degrees give the ratio of leading coefficients.","slide":null},{"point":"For \\(\\sqrt{\\ } - \\sqrt{\\ }\\) or \\(\\sqrt{\\ } - n\\) multiply by the conjugate.","slide":null},{"point":"\\(\\left(1 + \\frac an\\right)^n \\to e^a\\); the form \\(1^\\infty\\) does not give 1.","slide":null},{"point":"Continuous compounding gives \\(K_0 e^{rt}\\), the upper limit for compounding more and more often.","slide":null}],"concepts":[{"term":"Sequence","definition":"A function defined on the natural numbers, written \\(a_n\\).","pl":"ciąg liczbowy","slide":null},{"term":"Monotonic sequence","definition":"A sequence that is always increasing or always decreasing (or non-increasing / non-decreasing).","pl":"ciąg monotoniczny","slide":null},{"term":"Bounded sequence","definition":"A sequence with \\(m \\le a_n \\le M\\) for all \\(n\\).","pl":"ciąg ograniczony","slide":null},{"term":"Limit of a sequence","definition":"The number \\(g\\) that the terms \\(a_n\\) approach as \\(n \\to \\infty\\).","pl":"granica ciągu","slide":null},{"term":"Convergent / divergent sequence","definition":"Convergent: has a finite limit. Divergent: does not (goes to infinity or has no limit).","pl":"ciąg zbieżny / rozbieżny","slide":null},{"term":"Indeterminate form","definition":"An expression like \\(\\frac{\\infty}{\\infty}\\) or \\(1^\\infty\\) whose limit cannot be read off directly.","pl":"symbol nieoznaczony","slide":null},{"term":"Number e","definition":"\\(e = \\lim (1 + 1/n)^n \\approx 2.718\\), the base of natural logarithms.","pl":"liczba e (liczba Eulera)","slide":null},{"term":"Continuous compounding","definition":"Interest added continuously; capital grows as \\(K_0 e^{rt}\\).","pl":"kapitalizacja ciągła","slide":null}],"flashcards":[{"q":"How do you check if \\(a_n\\) is increasing?","a":"Show \\(a_{n+1} - a_n > 0\\) for all \\(n\\).","slide":null},{"q":"Monotonic + bounded sequence: what follows?","a":"It is convergent.","slide":null},{"q":"\\(\\lim\\limits_{n\\to\\infty} \\frac{1}{n} = ?\\)","a":"\\(0\\)","slide":null},{"q":"List four indeterminate forms.","a":"\\(\\frac{\\infty}{\\infty},\\ \\infty - \\infty,\\ 0\\cdot\\infty,\\ 1^\\infty\\)","slide":null},{"q":"\\(\\lim \\dfrac{a n^k + \\dots}{b n^k + \\dots}\\) (same degree)?","a":"\\(\\dfrac{a}{b}\\)","slide":null},{"q":"Trick for \\(\\sqrt{n^2 + bn} - n\\)?","a":"Multiply by the conjugate; the limit is \\(\\frac b2\\).","slide":null},{"q":"\\(\\lim\\limits_{n\\to\\infty}\\left(1 + \\frac1n\\right)^n = ?\\)","a":"\\(e \\approx 2.718\\)","slide":null},{"q":"\\(\\lim\\limits_{n\\to\\infty}\\left(1 + \\frac an\\right)^n = ?\\)","a":"\\(e^a\\)","slide":null},{"q":"Continuous compounding formula?","a":"\\(K_t = K_0 e^{rt}\\)","slide":null},{"q":"Is \\((-1)^n\\) convergent?","a":"No. It is bounded but jumps between \\(-1\\) and \\(1\\).","slide":null}],"quiz":[{"q":"\\(\\lim\\limits_{n\\to\\infty} \\dfrac{2n + 3}{5n - 1} = ?\\)","options":["\\(-3\\)","\\(\\frac{2}{5}\\)","\\(\\infty\\)","\\(\\frac{3}{5}\\)"],"correct":1,"explanation":"Same degree: ratio of leading coefficients \\(\\frac25\\).","slide":null},{"q":"The sequence \\(a_n = \\dfrac{1}{n^2}\\) is:","options":["increasing and bounded","decreasing and unbounded","decreasing and bounded","not monotonic"],"correct":2,"explanation":"Terms shrink: \\(1, \\frac14, \\frac19, \\dots\\), always between 0 and 1.","slide":null},{"q":"\\(\\lim\\limits_{n\\to\\infty}\\left(1 + \\frac{1}{n}\\right)^n = ?\\)","options":["\\(1\\)","\\(\\infty\\)","\\(0\\)","\\(e\\)"],"correct":3,"explanation":"It is a \\(1^\\infty\\) form, not 1. Its limit defines \\(e\\).","slide":null},{"q":"\\(\\lim\\limits_{n\\to\\infty} \\dfrac{n^2 + 1}{n + 1} = ?\\)","options":["\\(\\infty\\)","\\(1\\)","\\(0\\)","\\(2\\)"],"correct":0,"explanation":"The numerator has higher degree (2 > 1) and positive coefficients, so the limit is \\(+\\infty\\).","slide":null},{"q":"\\(\\lim\\limits_{n\\to\\infty}\\left(1 + \\frac{5}{n}\\right)^n = ?\\)","options":["\\(5e\\)","\\(e^{1/5}\\)","\\(e^5\\)","\\(1\\)"],"correct":2,"explanation":"Rule \\(\\left(1 + \\frac an\\right)^n \\to e^a\\) with \\(a = 5\\).","slide":null},{"q":"\\(\\lim\\limits_{n\\to\\infty}\\left(\\sqrt{n^2 + 2n} - n\\right) = ?\\)","options":["\\(0\\)","\\(2\\)","\\(\\infty\\)","\\(1\\)"],"correct":3,"explanation":"Conjugate: \\(\\dfrac{2n}{\\sqrt{n^2+2n}+n} \\to \\dfrac{2}{2} = 1\\). It is \\(\\infty - \\infty\\), not 0.","slide":null},{"q":"Which formula gives capital after \\(t\\) years with continuous compounding at rate \\(r\\)?","options":["\\(K_0(1 + r)^t\\)","\\(K_0 e^{rt}\\)","\\(K_0(1 + rt)\\)","\\(K_0 e^{r/t}\\)"],"correct":1,"explanation":"Letting the number of compounding periods go to infinity turns \\(\\left(1 + \\frac rm\\right)^{mt}\\) into \\(e^{rt}\\).","slide":null},{"q":"True or false: every bounded sequence is convergent.","options":["True","False"],"correct":1,"explanation":"False. \\((-1)^n\\) is bounded but has no limit. You need monotonic AND bounded.","slide":null}],"lang":"en","lesson":{"intro":"Imagine a bank that adds interest more and more often: yearly, monthly, daily, every second. Does your money grow without end? Sequences and their limits answer this question, and the answer is the famous number \\(e\\).","sections":[{"h":"What is a sequence?","body":"A (number) **sequence** is a function defined on natural numbers \\(n = 1, 2, 3, \\dots\\). We write its terms as \\(a_n\\) instead of \\(f(n)\\).\n\nFor example \\(a_n = \\dfrac{n-1}{n}\\) gives \\(a_1 = 0,\\ a_2 = \\tfrac12,\\ a_3 = \\tfrac23,\\ a_4 = \\tfrac34, \\dots\\)\n\nTo get the next term \\(a_{n+1}\\), replace every \\(n\\) in the formula by \\(n + 1\\).","example":{"task":"For \\(a_n = 2n + 1\\), write \\(a_1, a_2, a_3\\) and \\(a_{n+1}\\).","steps":["\\(a_1 = 3,\\ a_2 = 5,\\ a_3 = 7\\).","\\(a_{n+1} = 2(n + 1) + 1 = 2n + 3\\)."],"answer":"\\(3, 5, 7\\) and \\(a_{n+1} = 2n + 3\\)."},"tip":"Use brackets when you substitute \\(n + 1\\): \\(2(n+1)\\), not \\(2n + 1\\)."},{"h":"Monotonic and bounded sequences","body":"A sequence is:\n- **increasing** if \\(a_{n+1} > a_n\\) for all \\(n\\), i.e. \\(a_{n+1} - a_n > 0\\);\n- **decreasing** if \\(a_{n+1} - a_n < 0\\) for all \\(n\\);\n- **monotonic** if it is increasing or decreasing (or non-increasing / non-decreasing).\n\nMethod: compute the difference \\(a_{n+1} - a_n\\), simplify it, and check its sign for all \\(n \\ge 1\\).\n\nA sequence is **bounded** if there are numbers \\(m\\) and \\(M\\) with \\(m \\le a_n \\le M\\) for all \\(n\\). Example: \\(a_n = (-1)^n\\) jumps between \\(-1\\) and \\(1\\): bounded, but not monotonic.\n\nImportant theorem: **a monotonic and bounded sequence is convergent** (it has a finite limit).","example":{"task":"Show that \\(a_n = \\dfrac{n}{n+1}\\) is increasing and bounded.","steps":["\\(a_{n+1} = \\dfrac{n+1}{n+2}\\).","\\(a_{n+1} - a_n = \\dfrac{(n+1)^2 - n(n+2)}{(n+1)(n+2)} = \\dfrac{1}{(n+1)(n+2)} > 0\\), so it is increasing.","\\(0 < \\dfrac{n}{n+1} < 1\\) for all \\(n\\), so it is bounded."],"answer":"Increasing and bounded, so it converges (its limit is 1)."},"tip":"Bounded alone is not enough for a limit: \\((-1)^n\\) is bounded but has no limit."},{"h":"Limit of a sequence and the basic rules","body":"We say \\(\\lim\\limits_{n \\to \\infty} a_n = g\\) if the terms get as close to \\(g\\) as we want for large enough \\(n\\). A sequence with a finite limit is **convergent**; otherwise it is **divergent** (for example it goes to \\(\\pm\\infty\\) or jumps around).\n\nBasic facts:\n\\[ \\lim_{n\\to\\infty} \\frac{1}{n} = 0, \\qquad \\lim_{n\\to\\infty} \\frac{c}{n^k} = 0\\ (k > 0), \\qquad \\lim_{n\\to\\infty} c = c \\]\n\nRules (when both limits \\(a\\), \\(b\\) are finite):\n\\[ \\lim(a_n \\pm b_n) = a \\pm b, \\quad \\lim(a_n b_n) = ab, \\quad \\lim\\frac{a_n}{b_n} = \\frac{a}{b}\\ (b \\neq 0) \\]\n\n\"Infinity arithmetic\" that is safe: \\(\\infty + \\infty = \\infty\\), \\(c \\cdot \\infty = \\infty\\) for \\(c > 0\\), \\(\\dfrac{c}{\\infty} = 0\\).\n\n**Indeterminate forms** (need extra work): \\(\\dfrac{\\infty}{\\infty},\\ \\infty - \\infty,\\ 0 \\cdot \\infty,\\ 1^\\infty\\).","tip":"Never write \\(\\infty - \\infty = 0\\) or \\(\\frac{\\infty}{\\infty} = 1\\). These are indeterminate; you must transform the expression first."},{"h":"Typical forms: ratios of polynomials","body":"For \\(\\dfrac{\\text{polynomial}}{\\text{polynomial}}\\) (form \\(\\frac{\\infty}{\\infty}\\)): **divide the numerator and the denominator by the highest power of \\(n\\) in the denominator**. Then use \\(\\frac{c}{n^k} \\to 0\\).\n\nShortcut, compare the highest powers:\n- same degree: limit = ratio of leading coefficients;\n- numerator degree smaller: limit \\(= 0\\);\n- numerator degree bigger: limit \\(= \\pm\\infty\\) (sign of the leading coefficients' ratio).","example":{"task":"Compute \\(\\lim\\limits_{n\\to\\infty} \\dfrac{3n^2 + n}{n^2 + 5}\\).","steps":["Divide by \\(n^2\\): \\(\\dfrac{3 + \\frac{1}{n}}{1 + \\frac{5}{n^2}}\\).","\\(\\frac{1}{n} \\to 0\\) and \\(\\frac{5}{n^2} \\to 0\\).","Limit \\(= \\dfrac{3 + 0}{1 + 0}\\)."],"answer":"\\(3\\)"},"tip":"Compare: \\(\\dfrac{2n+1}{n^2+1} \\to 0\\) (lower degree on top) and \\(\\dfrac{n^3}{n^2+1} \\to \\infty\\) (higher degree on top)."},{"h":"Typical forms: differences of square roots","body":"For \\(\\sqrt{A} - B\\) of type \\(\\infty - \\infty\\), multiply and divide by the **conjugate** \\(\\sqrt{A} + B\\) and use \\((x - y)(x + y) = x^2 - y^2\\):\n\n\\[ \\sqrt{A} - B = \\frac{A - B^2}{\\sqrt{A} + B} \\]\n\nThe root disappears from the numerator. Then divide by the highest power of \\(n\\).","example":{"task":"Compute \\(\\lim\\limits_{n\\to\\infty} \\left(\\sqrt{n^2 + 4n} - n\\right)\\).","steps":["Multiply by the conjugate: \\(\\dfrac{(n^2 + 4n) - n^2}{\\sqrt{n^2+4n} + n} = \\dfrac{4n}{\\sqrt{n^2 + 4n} + n}\\).","Divide by \\(n\\) (note \\(\\frac{\\sqrt{n^2+4n}}{n} = \\sqrt{1 + \\frac{4}{n}}\\)): \\(\\dfrac{4}{\\sqrt{1 + \\frac4n} + 1}\\).","\\(\\to \\dfrac{4}{1 + 1}\\)."],"answer":"\\(2\\)"},"tip":"Fast check: \\(\\sqrt{n^2 + bn} - n \\to \\dfrac{b}{2}\\). Also \\(\\sqrt{n+1} - \\sqrt{n} = \\dfrac{1}{\\sqrt{n+1}+\\sqrt{n}} \\to 0\\)."},{"h":"The number e and continuous compounding","body":"The sequence \\(\\left(1 + \\frac1n\\right)^n\\) is increasing and bounded, so it has a limit. This limit is the number \\(e \\approx 2.71828\\):\n\n\\[ \\lim_{n\\to\\infty}\\left(1 + \\frac{1}{n}\\right)^n = e \\]\n\nIt is a \\(1^\\infty\\) form, so the answer is not 1. The general rule:\n\n\\[ \\lim_{n\\to\\infty}\\left(1 + \\frac{a}{n}\\right)^n = e^a, \\qquad \\lim_{n\\to\\infty}\\left(1 + \\frac{1}{n}\\right)^{kn} = e^k \\]\n\nIf the base is a fraction like \\(\\frac{n+2}{n}\\), first write it as \\(1 + \\frac{2}{n}\\).\n\n**Economics.** Capital \\(K_0\\) at yearly rate \\(r\\), compounded \\(m\\) times per year for \\(t\\) years: \\(K_0\\left(1 + \\frac{r}{m}\\right)^{mt}\\). As \\(m \\to \\infty\\) we get **continuous compounding**:\n\n\\[ K_t = K_0 e^{rt} \\]","example":{"task":"Compare 1000 PLN at 5% for 2 years: compounded yearly, monthly and continuously.","steps":["Yearly: \\(1000 \\cdot 1.05^2 = 1102.50\\).","Monthly: \\(1000\\left(1 + \\frac{0.05}{12}\\right)^{24} \\approx 1104.94\\).","Continuously: \\(1000 e^{0.05 \\cdot 2} = 1000 e^{0.1} \\approx 1105.17\\)."],"answer":"1102.50, 1104.94, 1105.17 PLN: more frequent compounding helps, but the growth has a ceiling, \\(K_0 e^{rt}\\)."},"tip":"\\(\\left(1 - \\frac1n\\right)^n \\to e^{-1}\\), and \\(\\left(\\frac{n+1}{n-1}\\right)^n \\to e^2\\). Always rewrite the base as \\(1 + \\frac{\\text{something}}{\\dots}\\)."}],"formulas":["Increasing: \\(a_{n+1} - a_n > 0\\); decreasing: \\(a_{n+1} - a_n < 0\\)","\\(\\lim\\limits_{n\\to\\infty} \\dfrac{c}{n^k} = 0\\) for \\(k > 0\\)","Polynomial ratio: divide by the highest power of \\(n\\) in the denominator","\\(\\sqrt{A} - B = \\dfrac{A - B^2}{\\sqrt{A} + B}\\)","\\(\\lim\\limits_{n\\to\\infty}\\left(1 + \\frac{1}{n}\\right)^n = e \\approx 2.718\\)","\\(\\lim\\limits_{n\\to\\infty}\\left(1 + \\frac{a}{n}\\right)^n = e^a\\)","Compounding \\(m\\) times a year: \\(K_0\\left(1 + \\frac{r}{m}\\right)^{mt}\\)","Continuous compounding: \\(K_t = K_0 e^{rt}\\)"],"exercises":[{"task":"Write the first four terms of \\(a_n = \\dfrac{n-1}{n}\\).","hint":"Substitute \\(n = 1, 2, 3, 4\\).","answer":"\\(0, \\tfrac12, \\tfrac23, \\tfrac34\\)."},{"task":"Is \\(a_n = 5 - 2n\\) monotonic? If yes, which type?","hint":"Compute \\(a_{n+1} - a_n\\).","answer":"\\(a_{n+1} - a_n = -2 < 0\\): decreasing."},{"task":"Compute \\(\\lim\\limits_{n\\to\\infty} \\dfrac{4n^2 - 3}{2n^2 + n}\\).","hint":"Same degree on top and bottom.","answer":"\\(\\dfrac{4}{2} = 2\\)."},{"task":"Compute \\(\\lim\\limits_{n\\to\\infty} \\dfrac{5n + 2}{n^2 - 1}\\).","hint":"Divide by \\(n^2\\).","answer":"\\(0\\) (lower degree in the numerator)."},{"task":"Compute \\(\\lim\\limits_{n\\to\\infty} \\left(\\sqrt{n^2 + 6n} - n\\right)\\).","hint":"Multiply by the conjugate \\(\\sqrt{n^2+6n} + n\\).","answer":"\\(\\dfrac{6n}{\\sqrt{n^2+6n}+n} \\to \\dfrac{6}{2} = 3\\)."},{"task":"Compute \\(\\lim\\limits_{n\\to\\infty} \\left(1 + \\dfrac{2}{n}\\right)^n\\).","hint":"Use \\(\\left(1 + \\frac an\\right)^n \\to e^a\\).","answer":"\\(e^2\\)."},{"task":"Compute \\(\\lim\\limits_{n\\to\\infty} \\left(\\dfrac{n+3}{n+1}\\right)^n\\).","hint":"\\(\\dfrac{n+3}{n+1} = 1 + \\dfrac{2}{n+1}\\).","answer":"\\(\\left(1 + \\frac{2}{n+1}\\right)^{n} \\to e^2\\)."},{"task":"2000 PLN is invested at 4% per year with continuous compounding. What is its value after 5 years?","hint":"\\(K_t = K_0 e^{rt}\\) with \\(rt = 0.2\\).","answer":"\\(2000 e^{0.2} \\approx 2442.81\\) PLN."}]}}$lekcja$::jsonb)
