insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-03-limits-continuity', $lekcja${"tldr":"The limit of a function tells you what value \\(f(x)\\) approaches when \\(x\\) gets close to a point \\(x_0\\) or goes to infinity. You learn one-sided limits, and how to solve the indeterminate forms \\(\\frac00\\) (factor and cancel) and \\(\\frac{\\infty}{\\infty}\\) (divide by the highest power). Two standard limits, \\(\\frac{\\sin x}{x} \\to 1\\) and \\(\\left(1 + \\frac1x\\right)^x \\to e\\), solve many exam tasks. Finally, a function is continuous at a point when its limit equals its value there; otherwise we classify the discontinuity (removable, jump, infinite). In economics, limits describe saturation (sales that level off) and continuity explains price jumps such as quantity discounts.","notes":[{"point":"The limit at \\(x_0\\) depends only on values near \\(x_0\\), not on \\(f(x_0)\\).","slide":null},{"point":"The two-sided limit exists only if the left and right limits exist and are equal.","slide":null},{"point":"\\(\\frac00\\) at \\(x_0\\) means a common factor \\((x - x_0)\\): factor and cancel.","slide":null},{"point":"For \\(\\frac{\\infty}{\\infty}\\) with rational functions, divide by the highest power of \\(x\\).","slide":null},{"point":"\\(\\lim\\limits_{x\\to0}\\frac{\\sin x}{x} = 1\\) and \\(\\lim\\limits_{x\\to\\infty}\\left(1+\\frac1x\\right)^x = e\\) are standard limits.","slide":null},{"point":"\\(\\frac{c}{0^+} = +\\infty\\) and \\(\\frac{c}{0^-} = -\\infty\\) for \\(c > 0\\); check the sign on each side.","slide":null},{"point":"Continuous at \\(x_0\\): \\(f(x_0)\\) exists and equals the limit.","slide":null},{"point":"Discontinuity types: removable (finite limit, wrong/missing value), jump (different finite one-sided limits), infinite (a one-sided limit is infinite).","slide":null}],"concepts":[{"term":"Limit of a function","definition":"The value \\(f(x)\\) approaches as \\(x\\) approaches \\(x_0\\) (or infinity).","pl":"granica funkcji","slide":null},{"term":"One-sided limit","definition":"Limit as \\(x\\) approaches \\(x_0\\) only from the left (\\(x_0^-\\)) or only from the right (\\(x_0^+\\)).","pl":"granica jednostronna (lewostronna / prawostronna)","slide":null},{"term":"Indeterminate form","definition":"A form like \\(\\frac00\\) or \\(\\frac{\\infty}{\\infty}\\) that needs algebra before the limit can be found.","pl":"symbol nieoznaczony","slide":null},{"term":"Continuous function","definition":"A function whose limit at each point of its domain equals its value there.","pl":"funkcja ciągła","slide":null},{"term":"Removable discontinuity","definition":"The limit exists and is finite, but the value is missing or different.","pl":"nieciągłość usuwalna","slide":null},{"term":"Jump discontinuity","definition":"Both one-sided limits are finite but different.","pl":"nieciągłość typu skok","slide":null},{"term":"Infinite discontinuity","definition":"At least one one-sided limit is \\(\\pm\\infty\\).","pl":"nieciągłość nieskończona (drugiego rodzaju)","slide":null}],"flashcards":[{"q":"When does the two-sided limit exist?","a":"When both one-sided limits exist and are equal.","slide":null},{"q":"What to do with \\(\\frac00\\) for a rational function?","a":"Factor, cancel \\((x - x_0)\\), substitute again.","slide":null},{"q":"What to do with \\(\\frac{\\infty}{\\infty}\\)?","a":"Divide by the highest power of \\(x\\) in the denominator.","slide":null},{"q":"\\(\\lim\\limits_{x\\to0}\\dfrac{\\sin x}{x} = ?\\)","a":"\\(1\\)","slide":null},{"q":"\\(\\lim\\limits_{x\\to\\infty}\\left(1 + \\frac ax\\right)^x = ?\\)","a":"\\(e^a\\)","slide":null},{"q":"\\(\\lim\\limits_{x\\to0^+}\\dfrac1x = ?\\)","a":"\\(+\\infty\\)","slide":null},{"q":"Definition of continuity at \\(x_0\\)?","a":"\\(\\lim\\limits_{x\\to x_0} f(x) = f(x_0)\\)","slide":null},{"q":"Type of discontinuity of \\(\\frac{|x|}{x}\\) at 0?","a":"Jump (left limit \\(-1\\), right limit \\(1\\)).","slide":null},{"q":"Type of discontinuity of \\(\\frac{x^2-1}{x-1}\\) at 1?","a":"Removable (limit 2 exists, value missing).","slide":null},{"q":"\\(\\lim\\limits_{x\\to0}\\dfrac{\\sin 3x}{x} = ?\\)","a":"\\(3\\)","slide":null}],"quiz":[{"q":"\\(\\lim\\limits_{x\\to3}\\dfrac{x^2 - 9}{x - 3} = ?\\)","options":["\\(0\\)","\\(3\\)","\\(6\\)","does not exist"],"correct":2,"explanation":"\\(\\frac{(x-3)(x+3)}{x-3} = x + 3 \\to 6\\). The \\(\\frac00\\) form does not mean the limit is 0 or missing.","slide":null},{"q":"\\(\\lim\\limits_{x\\to\\infty}\\dfrac{4x^2 + x}{2x^2 - 5} = ?\\)","options":["\\(2\\)","\\(\\infty\\)","\\(4\\)","\\(-\\frac15\\)"],"correct":0,"explanation":"Same degree: \\(\\frac42 = 2\\).","slide":null},{"q":"\\(\\lim\\limits_{x\\to0}\\dfrac{\\sin x}{x} = ?\\)","options":["\\(0\\)","\\(1\\)","\\(\\infty\\)","does not exist"],"correct":1,"explanation":"It is a standard limit equal to 1.","slide":null},{"q":"\\(\\lim\\limits_{x\\to0^-}\\dfrac1x = ?\\)","options":["\\(+\\infty\\)","\\(0\\)","\\(1\\)","\\(-\\infty\\)"],"correct":3,"explanation":"From the left \\(x\\) is a small negative number, so \\(\\frac1x\\) is a large negative number.","slide":null},{"q":"What type of discontinuity does \\(f(x) = \\dfrac{x^2 - 1}{x - 1}\\) have at \\(x = 1\\)?","options":["jump","infinite","removable","none, it is continuous"],"correct":2,"explanation":"The limit is 2 (finite), but \\(f(1)\\) is not defined, so the gap can be \"filled in\".","slide":null},{"q":"\\(\\lim\\limits_{x\\to\\infty}\\dfrac{5x + 1}{x^2 + 3} = ?\\)","options":["\\(5\\)","\\(0\\)","\\(\\infty\\)","\\(\\frac13\\)"],"correct":1,"explanation":"Lower degree in the numerator, so the fraction goes to 0.","slide":null},{"q":"The left limit at \\(x_0\\) is 4 and the right limit is 7. What can you say?","options":["The limit at \\(x_0\\) is 5.5","The limit at \\(x_0\\) is 7","\\(f\\) has a removable discontinuity","The limit at \\(x_0\\) does not exist"],"correct":3,"explanation":"The one-sided limits differ, so there is no two-sided limit (it is a jump).","slide":null},{"q":"\\(\\lim\\limits_{x\\to\\infty}\\left(1 + \\dfrac1x\\right)^{2x} = ?\\)","options":["\\(1\\)","\\(2e\\)","\\(e^2\\)","\\(\\infty\\)"],"correct":2,"explanation":"\\(\\left[\\left(1 + \\frac1x\\right)^x\\right]^2 \\to e^2\\). The \\(1^\\infty\\) form is not 1.","slide":null}],"lang":"en","lesson":{"intro":"Sometimes we cannot just plug in a number: \\(\\frac{x^2-4}{x-2}\\) at \\(x = 2\\) gives \\(\\frac00\\). The limit asks a smarter question: what happens to \\(f(x)\\) when \\(x\\) gets very close to 2?","sections":[{"h":"Limit at a point and one-sided limits","body":"\\(\\lim\\limits_{x\\to x_0} f(x) = g\\) means: when \\(x\\) is close to \\(x_0\\) (but \\(x \\neq x_0\\)), \\(f(x)\\) is close to \\(g\\). The value \\(f(x_0)\\) itself does not matter, and it may not even exist.\n\n**One-sided limits:**\n- left-hand limit \\(\\lim\\limits_{x\\to x_0^-} f(x)\\): \\(x\\) approaches from smaller values;\n- right-hand limit \\(\\lim\\limits_{x\\to x_0^+} f(x)\\): \\(x\\) approaches from bigger values.\n\nThe (two-sided) limit exists **if and only if** both one-sided limits exist and are equal.\n\nFor \"nice\" formulas (polynomials, roots, exp, log inside their domain) you can just substitute: \\(\\lim\\limits_{x\\to 2}(3x^2 - x) = 12 - 2 = 10\\).","example":{"task":"Find the one-sided limits of \\(f(x) = \\dfrac{1}{x-1}\\) at \\(x_0 = 1\\).","steps":["For \\(x \\to 1^-\\) (e.g. \\(x = 0.99\\)): \\(x - 1\\) is a small negative number, so \\(\\frac{1}{x-1} \\to -\\infty\\).","For \\(x \\to 1^+\\) (e.g. \\(x = 1.01\\)): \\(x - 1\\) is a small positive number, so \\(\\frac{1}{x-1} \\to +\\infty\\).","The one-sided limits differ."],"answer":"\\(\\lim\\limits_{x\\to1^-} = -\\infty\\), \\(\\lim\\limits_{x\\to1^+} = +\\infty\\); the limit at 1 does not exist."},"tip":"For \\(\\frac{c}{0}\\) situations, check the sign of the denominator on each side: \\(\\frac{c}{0^+}\\) and \\(\\frac{c}{0^-}\\) give opposite infinities."},{"h":"The form 0/0: factor and cancel","body":"If substitution gives \\(\\frac00\\), the numerator and the denominator share a factor \\((x - x_0)\\). Steps:\n\n- factor both (formulas like \\(a^2 - b^2 = (a-b)(a+b)\\), or roots of a quadratic: \\(ax^2 + bx + c = a(x - x_1)(x - x_2)\\));\n- cancel the common factor (allowed, because \\(x \\neq x_0\\));\n- substitute again.\n\nIf there is a square root, multiply by the conjugate first.","example":{"task":"Compute \\(\\lim\\limits_{x\\to 3} \\dfrac{x^2 - 5x + 6}{x^2 - 9}\\).","steps":["Substitution gives \\(\\frac{9 - 15 + 6}{0} = \\frac00\\).","Factor: \\(x^2 - 5x + 6 = (x-2)(x-3)\\), \\(x^2 - 9 = (x-3)(x+3)\\).","Cancel \\((x - 3)\\): \\(\\dfrac{x - 2}{x + 3}\\).","Substitute \\(x = 3\\): \\(\\dfrac{1}{6}\\)."],"answer":"\\(\\dfrac16\\)"},"tip":"With a root: \\(\\lim\\limits_{x\\to0}\\dfrac{\\sqrt{x+9} - 3}{x} = \\lim\\limits_{x\\to0}\\dfrac{x}{x(\\sqrt{x+9}+3)} = \\dfrac16\\)."},{"h":"Limits at infinity and the form ∞/∞","body":"\\(\\lim\\limits_{x\\to\\infty} f(x)\\) describes what happens for very large \\(x\\). For rational functions use the same method as for sequences: **divide by the highest power of \\(x\\) in the denominator**.\n\n\\[ \\lim_{x\\to\\pm\\infty}\\frac{c}{x^k} = 0 \\quad (k > 0) \\]\n\n- same degree: ratio of the leading coefficients;\n- lower degree on top: \\(0\\);\n- higher degree on top: \\(\\pm\\infty\\).","example":{"task":"A new product's total sales after \\(t\\) months are \\(S(t) = \\dfrac{500t}{t + 2}\\) (thousand units). What happens in the long run?","steps":["Form \\(\\frac{\\infty}{\\infty}\\). Divide by \\(t\\): \\(S(t) = \\dfrac{500}{1 + \\frac{2}{t}}\\).","\\(\\frac2t \\to 0\\) as \\(t \\to \\infty\\)."],"answer":"\\(\\lim\\limits_{t\\to\\infty} S(t) = 500\\): sales level off at about 500 thousand units (market saturation)."},"tip":"Same idea: \\(\\lim\\limits_{x\\to\\infty}\\dfrac{2x^2 + 1}{x^2 - x} = 2\\)."},{"h":"Two standard limits","body":"Memorise these two:\n\n\\[ \\lim_{x\\to 0}\\frac{\\sin x}{x} = 1 \\qquad\\qquad \\lim_{x\\to\\pm\\infty}\\left(1 + \\frac1x\\right)^x = e \\]\n\nUseful versions:\n\\[ \\lim_{x\\to0}\\frac{\\sin(ax)}{ax} = 1, \\qquad \\lim_{x\\to0}(1 + x)^{1/x} = e, \\qquad \\lim_{x\\to\\infty}\\left(1 + \\frac ax\\right)^x = e^a \\]\n\nTrick for sine: make the argument of \\(\\sin\\) appear in the denominator too.","example":{"task":"Compute \\(\\lim\\limits_{x\\to0}\\dfrac{\\sin 3x}{x}\\).","steps":["Multiply and divide by 3: \\(\\dfrac{\\sin 3x}{x} = 3\\cdot\\dfrac{\\sin 3x}{3x}\\).","As \\(x \\to 0\\), also \\(3x \\to 0\\), so \\(\\dfrac{\\sin 3x}{3x} \\to 1\\)."],"answer":"\\(3\\)"},"tip":"Exponential version: \\(\\lim\\limits_{x\\to\\infty}\\left(1 + \\frac2x\\right)^x = e^2\\), exactly like for sequences."},{"h":"Continuity and types of discontinuity","body":"A function \\(f\\) is **continuous at \\(x_0\\)** if\n\n\\[ \\lim_{x\\to x_0} f(x) = f(x_0) \\]\n\nThat means three things: \\(f(x_0)\\) exists, the limit exists, and they are equal. Informally: you can draw the graph through \\(x_0\\) without lifting the pen. Polynomials, \\(e^x\\), \\(\\ln x\\), \\(\\sqrt{x}\\), \\(\\sin x\\) are continuous in their domains.\n\nIf continuity fails at \\(x_0\\), we have a **discontinuity**:\n- **removable**: the limit exists (finite), but \\(f(x_0)\\) is missing or different. Example: \\(\\frac{x^2-1}{x-1}\\) at \\(x = 1\\).\n- **jump**: both one-sided limits are finite but different. Example: \\(\\frac{|x|}{x}\\) at 0 (left \\(-1\\), right \\(1\\)).\n- **infinite**: at least one one-sided limit is \\(\\pm\\infty\\). Example: \\(\\frac1x\\) at 0.\n\nFor a piecewise function, check the \"gluing point\": compare the left limit, the right limit and the value.","example":{"task":"A wholesaler charges \\(C(x) = 10x\\) PLN for \\(x \\le 100\\) kg and \\(C(x) = 9x + 50\\) for \\(x > 100\\) kg. Is \\(C\\) continuous at \\(x = 100\\)?","steps":["Value and left limit: \\(C(100) = 10\\cdot100 = 1000\\).","Right limit: \\(\\lim\\limits_{x\\to100^+}(9x + 50) = 950\\).","The one-sided limits are finite but different."],"answer":"Not continuous: a jump discontinuity at \\(x = 100\\). Buying just over 100 kg is 50 PLN cheaper than buying exactly 100 kg."},"tip":"Typical exam task: find the parameter that makes \\(f\\) continuous. Set the left limit = right limit = value and solve for the parameter."}],"formulas":["Limit exists \\(\\iff \\lim\\limits_{x\\to x_0^-} f = \\lim\\limits_{x\\to x_0^+} f\\)","\\(\\frac00\\): factor, cancel \\((x - x_0)\\), substitute","\\(\\frac{\\infty}{\\infty}\\): divide by the highest power of \\(x\\) in the denominator","\\(\\lim\\limits_{x\\to\\pm\\infty}\\dfrac{c}{x^k} = 0\\ (k>0)\\)","\\(\\lim\\limits_{x\\to0}\\dfrac{\\sin x}{x} = 1\\)","\\(\\lim\\limits_{x\\to\\infty}\\left(1 + \\frac ax\\right)^x = e^a\\), \\(\\lim\\limits_{x\\to0}(1+x)^{1/x} = e\\)","Continuity at \\(x_0\\): \\(\\lim\\limits_{x\\to x_0} f(x) = f(x_0)\\)"],"exercises":[{"task":"Compute \\(\\lim\\limits_{x\\to 2}(3x^2 - x)\\).","hint":"A polynomial: just substitute.","answer":"\\(12 - 2 = 10\\)."},{"task":"Compute \\(\\lim\\limits_{x\\to -1}\\dfrac{x^2 - 1}{x + 1}\\).","hint":"\\(x^2 - 1 = (x-1)(x+1)\\).","answer":"\\(\\lim (x - 1) = -2\\)."},{"task":"Compute \\(\\lim\\limits_{x\\to 4}\\dfrac{x^2 - 16}{x^2 - 3x - 4}\\).","hint":"\\(x^2 - 3x - 4 = (x-4)(x+1)\\).","answer":"\\(\\dfrac{x+4}{x+1} \\to \\dfrac85\\)."},{"task":"Compute \\(\\lim\\limits_{x\\to\\infty}\\dfrac{3x^3 - x}{6x^3 + 2}\\).","hint":"Same degree on top and bottom.","answer":"\\(\\dfrac36 = \\dfrac12\\)."},{"task":"Compute \\(\\lim\\limits_{x\\to0}\\dfrac{\\sin 5x}{2x}\\).","hint":"Write it as \\(\\dfrac52\\cdot\\dfrac{\\sin 5x}{5x}\\).","answer":"\\(\\dfrac52\\)."},{"task":"Compute \\(\\lim\\limits_{x\\to\\infty}\\left(1 + \\dfrac1x\\right)^{4x}\\).","hint":"\\(\\left(1 + \\frac1x\\right)^{4x} = \\left[\\left(1 + \\frac1x\\right)^x\\right]^4\\).","answer":"\\(e^4\\)."},{"task":"Compute \\(\\lim\\limits_{x\\to0}\\dfrac{\\sqrt{x + 9} - 3}{x}\\).","hint":"Multiply top and bottom by \\(\\sqrt{x+9} + 3\\).","answer":"\\(\\dfrac{1}{\\sqrt{x+9}+3} \\to \\dfrac16\\)."},{"task":"Find \\(a\\) so that \\(f(x) = \\dfrac{x^2 - 9}{x - 3}\\) for \\(x \\neq 3\\) and \\(f(3) = a\\) is continuous at \\(x = 3\\).","hint":"Compute the limit at 3 and set it equal to \\(a\\).","answer":"\\(\\lim\\limits_{x\\to3}(x + 3) = 6\\), so \\(a = 6\\)."}]}}$lekcja$::jsonb)
