insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-04-asymptotes', $lekcja${"tldr":"An asymptote is a line that the graph of a function gets closer and closer to. There are three types: vertical (\\(x = x_0\\)), horizontal (\\(y = b\\)) and oblique (\\(y = ax + b\\)). You find all of them with limits: vertical ones at the edges of the domain, horizontal and oblique ones at \\(\\pm\\infty\\). Asymptotes are a fixed step in every \"investigate the function\" exam task. In economics, the average cost \\(AC(x) = \\frac{C(x)}{x}\\) has a horizontal asymptote equal to the variable cost per unit: with huge production, fixed costs almost disappear per unit.","notes":[{"point":"Vertical asymptotes can only be at points outside the domain (or finite domain endpoints).","slide":null},{"point":"\\(x = x_0\\) is vertical if at least one one-sided limit at \\(x_0\\) is \\(\\pm\\infty\\).","slide":null},{"point":"If the factor \\((x - x_0)\\) cancels and the limit is finite, there is a hole, not an asymptote.","slide":null},{"point":"Horizontal asymptote \\(y = b\\): the limit at \\(+\\infty\\) or \\(-\\infty\\) is a finite number \\(b\\). Check both sides.","slide":null},{"point":"Oblique asymptote: \\(a = \\lim \\frac{f(x)}{x}\\), \\(b = \\lim (f(x) - ax)\\); both must be finite and \\(a \\neq 0\\).","slide":null},{"point":"On one side a function has either a horizontal or an oblique asymptote, never both.","slide":null},{"point":"A rational function has an oblique asymptote when the numerator degree is one higher than the denominator degree.","slide":null},{"point":"Average cost \\(\\frac{FC}{x} + v\\) has asymptotes \\(x = 0\\) and \\(y = v\\).","slide":null}],"concepts":[{"term":"Asymptote","definition":"A straight line that the graph of a function approaches more and more closely.","pl":"asymptota","slide":null},{"term":"Vertical asymptote","definition":"A line \\(x = x_0\\) near which \\(f(x) \\to \\pm\\infty\\).","pl":"asymptota pionowa","slide":null},{"term":"Horizontal asymptote","definition":"A line \\(y = b\\) with \\(f(x) \\to b\\) as \\(x \\to \\pm\\infty\\).","pl":"asymptota pozioma","slide":null},{"term":"Oblique (slant) asymptote","definition":"A line \\(y = ax + b\\), \\(a \\neq 0\\), approached by the graph as \\(x \\to \\pm\\infty\\).","pl":"asymptota ukośna","slide":null},{"term":"Rational function","definition":"A ratio of two polynomials.","pl":"funkcja wymierna","slide":null},{"term":"Average cost","definition":"Total cost divided by output, \\(AC(x) = \\frac{C(x)}{x}\\).","pl":"koszt przeciętny (średni)","slide":null},{"term":"Fixed cost","definition":"Cost that does not depend on the quantity produced.","pl":"koszt stały","slide":null}],"flashcards":[{"q":"Where can vertical asymptotes appear?","a":"Only at points excluded from the domain (or at finite domain endpoints).","slide":null},{"q":"Condition for vertical asymptote \\(x = x_0\\)?","a":"A one-sided limit at \\(x_0\\) equals \\(\\pm\\infty\\).","slide":null},{"q":"Condition for horizontal asymptote \\(y = b\\)?","a":"\\(\\lim\\limits_{x\\to\\pm\\infty} f(x) = b\\), finite.","slide":null},{"q":"Formula for \\(a\\) in the oblique asymptote?","a":"\\(a = \\lim\\limits_{x\\to\\pm\\infty} \\frac{f(x)}{x}\\)","slide":null},{"q":"Formula for \\(b\\) in the oblique asymptote?","a":"\\(b = \\lim\\limits_{x\\to\\pm\\infty}(f(x) - ax)\\)","slide":null},{"q":"Rational function, numerator degree smaller: horizontal asymptote?","a":"\\(y = 0\\)","slide":null},{"q":"Rational function, equal degrees: horizontal asymptote?","a":"\\(y = \\) ratio of the leading coefficients.","slide":null},{"q":"Is \\(x = 2\\) an asymptote of \\(\\frac{x^2 - 4}{x - 2}\\)?","a":"No. The limit is 4 (finite): it is a hole.","slide":null},{"q":"Asymptotes of \\(AC(x) = \\frac{FC}{x} + v\\)?","a":"\\(x = 0\\) and \\(y = v\\)","slide":null},{"q":"Can a graph cross its horizontal asymptote?","a":"Yes (e.g. \\(\\frac{2x}{x^2+1}\\) crosses \\(y = 0\\) at \\(x = 0\\)).","slide":null}],"quiz":[{"q":"What is the vertical asymptote of \\(f(x) = \\dfrac{x + 1}{x - 5}\\)?","options":["\\(x = -1\\)","\\(x = 5\\)","\\(y = 1\\)","\\(x = 1\\)"],"correct":1,"explanation":"The denominator is 0 at \\(x = 5\\) and the numerator is 6 there, so \\(f \\to \\pm\\infty\\). \\(x = -1\\) is a zero, not an asymptote.","slide":null},{"q":"What is the horizontal asymptote of \\(f(x) = \\dfrac{6x^2 + 1}{3x^2 - x}\\)?","options":["\\(y = 6\\)","\\(y = 0\\)","\\(y = 3\\)","\\(y = 2\\)"],"correct":3,"explanation":"Equal degrees: \\(\\frac63 = 2\\).","slide":null},{"q":"What is the horizontal asymptote of \\(f(x) = \\dfrac{x + 1}{x^2 + 1}\\)?","options":["\\(y = 0\\)","\\(y = 1\\)","\\(y = -1\\)","there is none"],"correct":0,"explanation":"The numerator has lower degree, so \\(f(x) \\to 0\\).","slide":null},{"q":"What is the oblique asymptote of \\(f(x) = \\dfrac{x^2 + 2}{x}\\)?","options":["\\(y = x + 2\\)","\\(y = 2x\\)","\\(y = x\\)","\\(y = 1\\)"],"correct":2,"explanation":"\\(f(x) = x + \\frac{2}{x}\\) and \\(\\frac2x \\to 0\\), so \\(y = x\\).","slide":null},{"q":"What happens at \\(x = 3\\) for \\(f(x) = \\dfrac{x^2 - 9}{x - 3}\\)?","options":["vertical asymptote","horizontal asymptote","a hole (removable discontinuity)","an oblique asymptote"],"correct":2,"explanation":"After cancelling, \\(f(x) = x + 3 \\to 6\\): a finite limit, so it is only a hole.","slide":null},{"q":"In the oblique asymptote \\(y = ax + b\\), how do you compute \\(a\\)?","options":["\\(a = \\lim\\limits_{x\\to\\infty} f(x)\\)","\\(a = \\lim\\limits_{x\\to\\infty}(f(x) - x)\\)","\\(a = f(0)\\)","\\(a = \\lim\\limits_{x\\to\\infty}\\frac{f(x)}{x}\\)"],"correct":3,"explanation":"\\(a\\) is the slope: \\(\\lim \\frac{f(x)}{x}\\). Then \\(b = \\lim(f(x) - ax)\\).","slide":null},{"q":"Total cost is \\(C(x) = 500 + 8x\\). The horizontal asymptote of the average cost is:","options":["\\(y = 500\\)","\\(y = 8\\)","\\(y = 508\\)","\\(y = 0\\)"],"correct":1,"explanation":"\\(AC(x) = \\frac{500}{x} + 8 \\to 8\\): the variable cost per unit.","slide":null},{"q":"True or false: the graph of a function can cross its horizontal asymptote.","options":["True","False"],"correct":0,"explanation":"True. An asymptote describes behaviour far away; e.g. \\(\\frac{2x}{x^2+1}\\) crosses \\(y = 0\\) at the origin.","slide":null}],"lang":"en","lesson":{"intro":"When you sketch a graph, asymptotes are the \"guide rails\": they show where the function shoots to infinity and how it behaves far away. Finding them is pure limit practice, so this lesson uses everything from the previous one.","sections":[{"h":"What is an asymptote?","body":"An **asymptote** is a straight line that the graph approaches more and more closely as \\(x\\) or \\(y\\) goes to infinity.\n\n- **Vertical asymptote** \\(x = x_0\\): the function goes to \\(\\pm\\infty\\) near \\(x_0\\).\n- **Horizontal asymptote** \\(y = b\\): \\(f(x) \\to b\\) as \\(x \\to +\\infty\\) or \\(x \\to -\\infty\\).\n- **Oblique (slant) asymptote** \\(y = ax + b\\) with \\(a \\neq 0\\): the graph approaches a sloped line as \\(x \\to \\pm\\infty\\).\n\nKnown examples: \\(\\frac1x\\) has \\(x = 0\\) (vertical) and \\(y = 0\\) (horizontal); \\(e^x\\) has \\(y = 0\\) as \\(x \\to -\\infty\\); \\(\\ln x\\) has \\(x = 0\\) (right-hand vertical).","tip":"A graph can never cross a vertical asymptote, but it may cross a horizontal one. For example \\(\\frac{2x}{x^2+1}\\) has the asymptote \\(y = 0\\) and still passes through \\((0, 0)\\)."},{"h":"Vertical asymptotes step by step","body":"Vertical asymptotes can appear only at **points excluded from the domain** (or at its finite endpoints). Method:\n\n- Find the domain. List the \"bad points\" \\(x_0\\) (zeros of the denominator, endpoint of a log, ...).\n- For each \\(x_0\\) compute the one-sided limits \\(\\lim\\limits_{x\\to x_0^-} f(x)\\) and \\(\\lim\\limits_{x\\to x_0^+} f(x)\\).\n- If at least one of them is \\(+\\infty\\) or \\(-\\infty\\), then \\(x = x_0\\) is a vertical asymptote (two-sided if both are infinite, one-sided otherwise).\n\n**Careful:** if the limit at \\(x_0\\) is finite, there is no asymptote, only a \"hole\". This happens when the factor cancels: \\(\\frac{x^2-4}{x-2} = x + 2\\) has a hole at \\(x = 2\\), not an asymptote.","example":{"task":"Find the vertical asymptotes of \\(f(x) = \\dfrac{x}{x^2 - 4}\\).","steps":["Domain: \\(x^2 - 4 \\neq 0\\), so \\(x \\neq -2\\) and \\(x \\neq 2\\).","At \\(x_0 = 2\\): numerator \\(\\to 2\\), denominator \\(\\to 0^-\\) from the left and \\(0^+\\) from the right. So the limits are \\(-\\infty\\) and \\(+\\infty\\).","At \\(x_0 = -2\\): numerator \\(\\to -2\\), denominator \\(\\to 0^+\\) from the left and \\(0^-\\) from the right. So the limits are \\(-\\infty\\) and \\(+\\infty\\)."],"answer":"Two vertical asymptotes: \\(x = -2\\) and \\(x = 2\\)."},"tip":"Always factor and cancel first. Only zeros of the denominator that remain after cancelling give vertical asymptotes."},{"h":"Horizontal asymptotes","body":"Compute the limits at both ends:\n\n\\[ \\lim_{x\\to+\\infty} f(x) = b_1, \\qquad \\lim_{x\\to-\\infty} f(x) = b_2 \\]\n\nIf a limit is a finite number \\(b\\), then \\(y = b\\) is a horizontal asymptote on that side. For rational functions both limits are the same, and the rule of degrees gives:\n\n- degree of numerator \\(<\\) degree of denominator: \\(y = 0\\);\n- degrees equal: \\(y = \\dfrac{\\text{leading coeff. of numerator}}{\\text{leading coeff. of denominator}}\\);\n- degree of numerator \\(>\\) degree of denominator: no horizontal asymptote (maybe an oblique one).","example":{"task":"Find all asymptotes of \\(f(x) = \\dfrac{2x + 1}{x - 3}\\).","steps":["Domain: \\(x \\neq 3\\). \\(\\lim\\limits_{x\\to3^-} f(x) = \\frac{7}{0^-} = -\\infty\\), \\(\\lim\\limits_{x\\to3^+} f(x) = \\frac{7}{0^+} = +\\infty\\). So \\(x = 3\\) is vertical.","\\(\\lim\\limits_{x\\to\\pm\\infty}\\dfrac{2x + 1}{x - 3} = \\dfrac21 = 2\\). So \\(y = 2\\) is horizontal.","A horizontal asymptote on both sides means there is no oblique one."],"answer":"Vertical \\(x = 3\\), horizontal \\(y = 2\\)."}},{"h":"Oblique asymptotes","body":"The line \\(y = ax + b\\) is an oblique asymptote at \\(+\\infty\\) (or \\(-\\infty\\)) if the two limits below are finite:\n\n\\[ a = \\lim_{x\\to\\pm\\infty}\\frac{f(x)}{x}, \\qquad b = \\lim_{x\\to\\pm\\infty}\\big(f(x) - ax\\big) \\]\n\n- If \\(a = 0\\), you get a horizontal asymptote \\(y = b\\).\n- If either limit is infinite, there is no oblique asymptote on that side.\n\nFor rational functions an oblique asymptote exists when the numerator degree is **exactly one more** than the denominator degree. A fast way is polynomial division: if \\(f(x) = ax + b + \\dfrac{r(x)}{q(x)}\\) with the remainder fraction \\(\\to 0\\), the asymptote is \\(y = ax + b\\).","example":{"task":"Find the oblique asymptote of \\(f(x) = \\dfrac{x^2 + 1}{x - 1}\\).","steps":["\\(a = \\lim\\limits_{x\\to\\infty}\\dfrac{x^2 + 1}{x(x - 1)} = \\lim\\dfrac{x^2 + 1}{x^2 - x} = 1\\).","\\(b = \\lim\\limits_{x\\to\\infty}\\left(\\dfrac{x^2 + 1}{x - 1} - x\\right) = \\lim\\dfrac{x^2 + 1 - x^2 + x}{x - 1} = \\lim\\dfrac{x + 1}{x - 1} = 1\\).","Same limits at \\(-\\infty\\). Check by division: \\(x^2 + 1 = (x - 1)(x + 1) + 2\\), so \\(f(x) = x + 1 + \\frac{2}{x-1}\\)."],"answer":"Oblique asymptote \\(y = x + 1\\) (and a vertical asymptote \\(x = 1\\))."},"tip":"Another check: \\(\\dfrac{2x^2 - x + 3}{x + 1} = 2x - 3 + \\dfrac{6}{x+1}\\), so its oblique asymptote is \\(y = 2x - 3\\)."},{"h":"Economics: average cost and its asymptotes","body":"If total cost is \\(C(x) = FC + v x\\) (fixed cost \\(FC\\), variable cost \\(v\\) per unit), the **average cost** per unit is\n\n\\[ AC(x) = \\frac{C(x)}{x} = \\frac{FC}{x} + v, \\qquad x > 0 \\]\n\n- As \\(x \\to 0^+\\): \\(\\frac{FC}{x} \\to +\\infty\\), so \\(x = 0\\) is a vertical asymptote. Producing very little is very expensive per unit.\n- As \\(x \\to \\infty\\): \\(\\frac{FC}{x} \\to 0\\), so \\(y = v\\) is a horizontal asymptote. With large production, the fixed cost is spread over many units and the average cost approaches the variable cost.\n\nThe graph of \\(AC\\) decreases towards \\(v\\) but never reaches it.","example":{"task":"\\(C(x) = 200 + 5x\\). Find the asymptotes of \\(AC(x)\\) and explain them.","steps":["\\(AC(x) = \\dfrac{200}{x} + 5\\).","\\(\\lim\\limits_{x\\to0^+} AC(x) = +\\infty\\): vertical asymptote \\(x = 0\\).","\\(\\lim\\limits_{x\\to\\infty} AC(x) = 5\\): horizontal asymptote \\(y = 5\\)."],"answer":"\\(x = 0\\) and \\(y = 5\\). The average cost per unit falls towards 5, the variable cost, as production grows."}}],"formulas":["Vertical: \\(x = x_0\\) if \\(\\lim\\limits_{x\\to x_0^-} f = \\pm\\infty\\) or \\(\\lim\\limits_{x\\to x_0^+} f = \\pm\\infty\\)","Horizontal: \\(y = b\\) if \\(\\lim\\limits_{x\\to\\pm\\infty} f(x) = b\\) (finite)","Oblique: \\(a = \\lim\\limits_{x\\to\\pm\\infty}\\dfrac{f(x)}{x}\\), \\(b = \\lim\\limits_{x\\to\\pm\\infty}(f(x) - ax)\\)","Rational: deg num < deg den \\(\\Rightarrow y = 0\\); equal \\(\\Rightarrow y = \\frac{\\text{lead. num}}{\\text{lead. den}}\\)","Rational: deg num = deg den + 1 \\(\\Rightarrow\\) oblique asymptote (use division)","\\(AC(x) = \\dfrac{C(x)}{x} = \\dfrac{FC}{x} + v \\to v\\) as \\(x \\to \\infty\\)"],"exercises":[{"task":"Find the vertical and horizontal asymptotes of \\(f(x) = \\dfrac{3x - 2}{x + 4}\\).","hint":"Denominator zero at \\(x = -4\\); equal degrees at infinity.","answer":"Vertical \\(x = -4\\), horizontal \\(y = 3\\)."},{"task":"Find the asymptotes of \\(f(x) = \\dfrac{5}{x^2 - 9}\\).","hint":"\\(x^2 - 9 = 0\\) at two points; constant on top.","answer":"Vertical \\(x = -3\\) and \\(x = 3\\); horizontal \\(y = 0\\)."},{"task":"Find the asymptotes of \\(f(x) = \\dfrac{x + 2}{x^2 - 4}\\).","hint":"Factor the denominator and cancel first.","answer":"\\(f(x) = \\frac{1}{x - 2}\\) for \\(x \\neq -2\\). Vertical \\(x = 2\\) only (at \\(x = -2\\) the limit is \\(-\\frac14\\): a hole). Horizontal \\(y = 0\\)."},{"task":"Find the oblique asymptote of \\(f(x) = \\dfrac{x^2 + 3x}{x - 1}\\).","hint":"Divide: \\(x^2 + 3x = (x - 1)(x + 4) + 4\\).","answer":"\\(y = x + 4\\) (and vertical \\(x = 1\\))."},{"task":"Find all asymptotes of \\(f(x) = \\dfrac{2x^3 + 1}{x^2}\\).","hint":"Split: \\(f(x) = 2x + \\frac{1}{x^2}\\).","answer":"Vertical \\(x = 0\\) (both sides \\(+\\infty\\)), oblique \\(y = 2x\\), no horizontal."},{"task":"A firm's total cost is \\(C(x) = 1000 + 20x\\). Find the horizontal asymptote of \\(AC(x)\\). For what output is the average cost 25?","hint":"\\(AC(x) = \\frac{1000}{x} + 20\\).","answer":"\\(y = 20\\). \\(\\frac{1000}{x} + 20 = 25 \\Rightarrow x = 200\\)."},{"task":"Find the horizontal asymptotes of \\(f(x) = 3 + e^{-x}\\).","hint":"Check \\(x \\to +\\infty\\) and \\(x \\to -\\infty\\) separately.","answer":"As \\(x \\to +\\infty\\), \\(e^{-x} \\to 0\\): \\(y = 3\\). As \\(x \\to -\\infty\\), \\(f \\to \\infty\\): no asymptote there."},{"task":"Find all asymptotes of \\(f(x) = \\dfrac{4x^2 - 1}{2x^2 + x - 1}\\).","hint":"\\(4x^2 - 1 = (2x-1)(2x+1)\\) and \\(2x^2 + x - 1 = (2x-1)(x+1)\\).","answer":"After cancelling, \\(f(x) = \\frac{2x+1}{x+1}\\). Vertical \\(x = -1\\); at \\(x = \\frac12\\) only a hole (limit \\(\\frac43\\)). Horizontal \\(y = 2\\)."}]}}$lekcja$::jsonb)
