insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-05-derivative-rules', $lekcja${"tldr":"The derivative \\(f'(x_0)\\) tells you how fast a function changes at one point. It is defined as the limit of the difference quotient, and geometrically it is the slope of the tangent line to the graph. In practice you almost never use the definition: you use a table of basic derivatives plus four rules (sum, product, quotient and chain rule). The differential \\(df = f'(x_0)\\,dx\\) lets you approximate small changes of a function. In economics the derivative of the cost function is the marginal cost: roughly the extra cost of producing one more unit.","notes":[{"point":"Definition: \\(f'(x_0)=\\lim_{h\\to0}\\frac{f(x_0+h)-f(x_0)}{h}\\); the fraction is called the difference quotient.","slide":null},{"point":"\\(f'(x_0)\\) is the slope of the tangent line; the tangent is \\(y=f(x_0)+f'(x_0)(x-x_0)\\).","slide":null},{"point":"Differentiable implies continuous, but not the other way round: |x| is continuous at 0 but has no derivative there.","slide":null},{"point":"Product rule \\((uv)'=u'v+uv'\\) and quotient rule \\(\\left(\\frac uv\\right)'=\\frac{u'v-uv'}{v^2}\\): the order in the numerator matters.","slide":null},{"point":"Chain rule: derivative of the outer function times derivative of the inner function. Forgetting the inner derivative is the top exam mistake.","slide":null},{"point":"Useful shortcuts: \\((e^{g})'=e^{g}g'\\) and \\((\\ln g)'=\\frac{g'}{g}\\).","slide":null},{"point":"Differential: \\(df=f'(x_0)\\Delta x\\); for small \\(\\Delta x\\), \\(f(x_0+\\Delta x)\\approx f(x_0)+f'(x_0)\\Delta x\\).","slide":null},{"point":"Marginal cost \\(MC=C'(q)\\) approximates the cost of one extra unit, \\(C(q+1)-C(q)\\). Same idea for marginal revenue and marginal profit.","slide":null}],"concepts":[{"term":"Difference quotient","definition":"The average rate of change \\(\\frac{f(x_0+h)-f(x_0)}{h}\\) of a function on a small interval.","pl":"iloraz różnicowy","slide":null},{"term":"Derivative","definition":"The limit of the difference quotient as the step goes to 0; the instantaneous rate of change of a function at a point.","pl":"pochodna","slide":null},{"term":"Differentiable function","definition":"A function that has a finite derivative at a point (or at every point of an interval).","pl":"funkcja różniczkowalna","slide":null},{"term":"Tangent line","definition":"The straight line that touches the graph at \\(x_0\\) and has slope \\(f'(x_0)\\).","pl":"styczna","slide":null},{"term":"Chain rule","definition":"The rule for differentiating a composite function: outer derivative times inner derivative.","pl":"pochodna funkcji złożonej (reguła łańcuchowa)","slide":null},{"term":"Differential","definition":"The linear part of the change of a function, \\(df=f'(x_0)\\,dx\\); used for approximations.","pl":"różniczka","slide":null},{"term":"Marginal cost","definition":"The derivative of the total cost function; approximately the cost of producing one more unit.","pl":"koszt krańcowy","slide":null},{"term":"Secant line","definition":"A straight line through two points of a graph; its slope is the difference quotient.","pl":"sieczna","slide":null}],"flashcards":[{"q":"Definition of the derivative at x0?","a":"\\(f'(x_0)=\\lim_{h\\to0}\\frac{f(x_0+h)-f(x_0)}{h}\\)","slide":null},{"q":"Geometric meaning of f'(x0)?","a":"The slope of the tangent line to the graph at x0.","slide":null},{"q":"Equation of the tangent line at x0?","a":"\\(y=f(x_0)+f'(x_0)(x-x_0)\\)","slide":null},{"q":"\\((x^n)'=\\)?","a":"\\(nx^{n-1}\\)","slide":null},{"q":"\\((a^x)'=\\)? and \\((\\ln x)'=\\)?","a":"\\(a^x\\ln a\\) and \\(\\frac1x\\)","slide":null},{"q":"Product rule?","a":"\\((uv)'=u'v+uv'\\)","slide":null},{"q":"Quotient rule?","a":"\\(\\left(\\frac uv\\right)'=\\frac{u'v-uv'}{v^2}\\)","slide":null},{"q":"Chain rule?","a":"\\(\\big(f(g(x))\\big)'=f'(g(x))\\cdot g'(x)\\)","slide":null},{"q":"\\(\\big(\\ln g(x)\\big)'=\\)?","a":"\\(\\frac{g'(x)}{g(x)}\\)","slide":null},{"q":"Approximation formula using the differential?","a":"\\(f(x_0+\\Delta x)\\approx f(x_0)+f'(x_0)\\Delta x\\)","slide":null},{"q":"What is marginal cost?","a":"C'(q): approximately the extra cost of producing one more unit.","slide":null}],"quiz":[{"q":"What is \\((x^4)'\\)?","options":["\\(4x^3\\)","\\(x^3\\)","\\(4x^4\\)","\\(3x^4\\)"],"correct":0,"explanation":"Power rule: bring down the exponent and reduce it by one: \\(4x^{3}\\).","slide":null},{"q":"What is \\(\\big(e^{3x}\\big)'\\)?","options":["\\(e^{3x}\\)","\\(3e^{3x}\\)","\\(3x\\,e^{3x-1}\\)","\\(\\frac13e^{3x}\\)"],"correct":1,"explanation":"Chain rule: \\(e^{3x}\\) times the inner derivative 3. The power rule does not apply to exponential functions.","slide":null},{"q":"Which formula is the product rule?","options":["\\((uv)'=u'v'\\)","\\((uv)'=u'v-uv'\\)","\\((uv)'=u'v+uv'\\)","\\((uv)'=\\frac{u'v-uv'}{v^2}\\)"],"correct":2,"explanation":"The derivative of a product is u'v + uv', not the product of the derivatives.","slide":null},{"q":"Geometrically, \\(f'(x_0)\\) is...","options":["the value of the function at x0","the area under the graph","the y-intercept of the tangent line","the slope of the tangent line at x0"],"correct":3,"explanation":"The derivative is the limit of secant slopes, which is the slope of the tangent line.","slide":null},{"q":"What is \\(\\big(\\ln(x^2+1)\\big)'\\)?","options":["\\(\\frac{1}{x^2+1}\\)","\\(\\frac{2x}{x^2+1}\\)","\\(2x\\ln(x^2+1)\\)","\\(\\frac{2}{x}\\)"],"correct":1,"explanation":"\\((\\ln g)'=\\frac{g'}{g}\\) with \\(g=x^2+1\\), \\(g'=2x\\).","slide":null},{"q":"The cost function is \\(C(q)=q^2+4q+100\\). What is the marginal cost at \\(q=10\\)?","options":["240","14","24","100"],"correct":2,"explanation":"\\(C'(q)=2q+4\\), so \\(C'(10)=24\\). 240 is C(10) without the fixed cost, which is a typical mix-up.","slide":null},{"q":"Marginal cost MC(q) can be interpreted as...","options":["the average cost per unit","the fixed cost","total cost divided by q","the approximate cost of producing one more unit"],"correct":3,"explanation":"MC = C'(q) ≈ C(q+1) − C(q), the extra cost of one more unit. Average cost is C(q)/q.","slide":null},{"q":"True or false: every continuous function is differentiable.","options":["True","False"],"correct":1,"explanation":"False. |x| is continuous at 0 but has a corner there, so it has no derivative at 0. The opposite implication is true.","slide":null}],"lang":"en","lesson":{"intro":"How fast is your cost growing when you produce one more unit? How steep is a graph at one exact point? Both questions have the same answer: the derivative. This lesson gives you the definition and, more importantly, the rules you will use in every exam task.","sections":[{"h":"1. The difference quotient and the definition","body":"Take a function \\(f\\) and a point \\(x_0\\). If \\(x\\) moves from \\(x_0\\) to \\(x_0+h\\), the function changes by \\(f(x_0+h)-f(x_0)\\). The **difference quotient** is the average rate of change on this small interval:\n\\[ \\frac{f(x_0+h)-f(x_0)}{h} \\]\nNow make the step \\(h\\) smaller and smaller. If the quotient approaches a finite number, this number is the **derivative of \\(f\\) at \\(x_0\\)**:\n\\[ f'(x_0)=\\lim_{h\\to 0}\\frac{f(x_0+h)-f(x_0)}{h} \\]\nIf this limit exists (and is finite), we say \\(f\\) is **differentiable** at \\(x_0\\). A differentiable function is always continuous there, but a continuous function does not have to be differentiable (example: \\(|x|\\) at \\(x=0\\) has a sharp corner).","example":{"task":"Use the definition to find \\(f'(3)\\) for \\(f(x)=x^2\\).","steps":["\\(f(3+h)-f(3)=(3+h)^2-9=9+6h+h^2-9=6h+h^2\\)","Difference quotient: \\(\\frac{6h+h^2}{h}=6+h\\) (for \\(h\\neq 0\\))","Limit: \\(\\lim_{h\\to 0}(6+h)=6\\)"],"answer":"\\(f'(3)=6\\)"},"tip":"In a definition task, always simplify the numerator first so that \\(h\\) cancels. Never put \\(h=0\\) into the quotient before cancelling, because you get \\(\\frac{0}{0}\\)."},{"h":"2. Geometric meaning: slope of the tangent","body":"The difference quotient is the slope of a **secant** line through the points \\((x_0,f(x_0))\\) and \\((x_0+h,f(x_0+h))\\). When \\(h\\to 0\\), the secant turns into the **tangent line** at \\(x_0\\). So:\n\n- \\(f'(x_0)\\) = slope of the tangent line at \\(x_0\\)\n- \\(f'(x_0)>0\\): the graph goes up at this point; \\(f'(x_0)<0\\): it goes down; \\(f'(x_0)=0\\): the tangent is horizontal.\n\nEquation of the tangent line at \\(x_0\\):\n\\[ y=f(x_0)+f'(x_0)\\,(x-x_0) \\]","example":{"task":"Find the tangent line to \\(f(x)=x^2\\) at \\(x_0=3\\).","steps":["\\(f(3)=9\\), and from Section 1, \\(f'(3)=6\\)","\\(y=9+6(x-3)\\)","\\(y=6x-18+9=6x-9\\)"],"answer":"\\(y=6x-9\\)"},"tip":"You need two numbers for a tangent line: the value f(x0) and the slope f'(x0). Students often forget to compute f(x0)."},{"h":"3. Table of basic derivatives","body":"Learn this table by heart. It covers almost every exam function.\n\n- \\((c)'=0\\) (a constant does not change)\n- \\((x^n)'=n\\,x^{n-1}\\) for any real \\(n\\), e.g. \\((x^5)'=5x^4\\)\n- \\((\\sqrt{x})'=\\frac{1}{2\\sqrt{x}}\\), \\(\\left(\\frac1x\\right)'=-\\frac{1}{x^2}\\) (both are special cases of the power rule)\n- \\((e^x)'=e^x\\), \\((a^x)'=a^x\\ln a\\)\n- \\((\\ln x)'=\\frac1x\\), \\((\\log_a x)'=\\frac{1}{x\\ln a}\\)\n- \\((\\sin x)'=\\cos x\\), \\((\\cos x)'=-\\sin x\\)\n\nTrick: before differentiating, rewrite roots and fractions as powers, e.g. \\(\\frac{1}{x^2}=x^{-2}\\), \\(\\sqrt[3]{x}=x^{1/3}\\).","example":{"task":"Differentiate \\(\\sqrt{x}\\) and \\(\\frac{1}{x^2}\\) using the power rule.","steps":["\\(\\sqrt{x}=x^{1/2}\\Rightarrow (x^{1/2})'=\\tfrac12 x^{-1/2}=\\frac{1}{2\\sqrt x}\\)","\\(\\frac{1}{x^2}=x^{-2}\\Rightarrow (x^{-2})'=-2x^{-3}=-\\frac{2}{x^3}\\)"],"answer":"\\(\\frac{1}{2\\sqrt x}\\) and \\(-\\frac{2}{x^3}\\)"}},{"h":"4. Sum, product and quotient rules","body":"For differentiable functions \\(u\\) and \\(v\\) and a constant \\(c\\):\n\\[ (c\\,u)'=c\\,u' \\qquad (u\\pm v)'=u'\\pm v' \\]\n\\[ (u\\cdot v)'=u'v+uv' \\]\n\\[ \\left(\\frac{u}{v}\\right)'=\\frac{u'v-uv'}{v^2} \\]\nThe derivative of a product is **not** the product of derivatives. In the quotient rule the order in the numerator matters: first \\(u'v\\), then minus \\(uv'\\).","example":{"task":"Find the derivatives of \\(f(x)=x^2e^x\\) and \\(g(x)=\\frac{x+1}{x-1}\\).","steps":["Product: \\(u=x^2,\\ v=e^x\\). \\(f'(x)=2x\\,e^x+x^2e^x=x(x+2)e^x\\)","Quotient: \\(u=x+1,\\ u'=1,\\ v=x-1,\\ v'=1\\)","\\(g'(x)=\\frac{1\\cdot(x-1)-(x+1)\\cdot 1}{(x-1)^2}=\\frac{-2}{(x-1)^2}\\)"],"answer":"\\(f'(x)=x(x+2)e^x\\), \\(g'(x)=-\\frac{2}{(x-1)^2}\\)"},"tip":"Mnemonic for the quotient rule: 'low d-high minus high d-low, over low squared' (low = denominator, high = numerator)."},{"h":"5. The chain rule (composite functions)","body":"A composite function has an 'outer' and an 'inner' part, like \\((3x^2+1)^4\\): outer = 'power 4', inner = \\(3x^2+1\\). The chain rule says: differentiate the outer function (keeping the inner part unchanged), then multiply by the derivative of the inner function.\n\\[ \\big(f(g(x))\\big)'=f'\\big(g(x)\\big)\\cdot g'(x) \\]\nVery useful special cases:\n\\[ \\big(e^{g(x)}\\big)'=e^{g(x)}\\,g'(x) \\qquad \\big(\\ln g(x)\\big)'=\\frac{g'(x)}{g(x)} \\]","example":{"task":"Differentiate \\((3x^2+1)^4\\), \\(\\ln(x^2+1)\\) and \\(e^{-2x}\\).","steps":["\\(\\big((3x^2+1)^4\\big)'=4(3x^2+1)^3\\cdot 6x=24x(3x^2+1)^3\\)","\\(\\big(\\ln(x^2+1)\\big)'=\\frac{2x}{x^2+1}\\)","\\(\\big(e^{-2x}\\big)'=e^{-2x}\\cdot(-2)=-2e^{-2x}\\)"],"answer":"\\(24x(3x^2+1)^3,\\ \\frac{2x}{x^2+1},\\ -2e^{-2x}\\)"},"tip":"The most common exam mistake is forgetting to multiply by the inner derivative. Always ask: 'is there something inside?'"},{"h":"6. Differential, approximation and marginal cost","body":"The **differential** of \\(f\\) at \\(x_0\\) is the linear part of the change:\n\\[ df=f'(x_0)\\,\\Delta x \\]\nFor a small step \\(\\Delta x\\) the real change is close to the differential, so\n\\[ f(x_0+\\Delta x)\\approx f(x_0)+f'(x_0)\\,\\Delta x \\]\nThis is the tangent line used as an approximation.\n\n**Economics: marginal cost.** If \\(C(q)\\) is the total cost of producing \\(q\\) units, then the marginal cost is \\(MC(q)=C'(q)\\). With \\(\\Delta q=1\\), the approximation gives\n\\[ C(q+1)-C(q)\\approx C'(q) \\]\nso marginal cost is (approximately) the cost of producing **one more unit**. In the same way, \\(R'(q)\\) is marginal revenue and \\(\\pi'(q)\\) is marginal profit.","example":{"task":"\\(C(q)=0.5q^2+10q+200\\). Find \\(MC(20)\\) and compare it with the exact cost of the 21st unit.","steps":["\\(C'(q)=q+10\\), so \\(MC(20)=30\\)","Exact: \\(C(21)-C(20)=0.5(441-400)+10=20.5+10=30.5\\)","The marginal cost 30 is a good approximation of the true extra cost 30.5"],"answer":"\\(MC(20)=30\\); the 21st unit really costs 30.5"},"tip":"Approximation example without economics: \\(\\sqrt{4.1}\\approx 2+\\frac{1}{2\\sqrt4}\\cdot 0.1=2.025\\) (true value 2.0248...)."}],"formulas":["\\(f'(x_0)=\\lim_{h\\to0}\\frac{f(x_0+h)-f(x_0)}{h}\\)","Tangent line: \\(y=f(x_0)+f'(x_0)(x-x_0)\\)","\\((x^n)'=nx^{n-1},\\ (e^x)'=e^x,\\ (a^x)'=a^x\\ln a,\\ (\\ln x)'=\\frac1x\\)","\\((u\\pm v)'=u'\\pm v',\\ (cu)'=cu'\\)","\\((uv)'=u'v+uv'\\)","\\(\\left(\\frac uv\\right)'=\\frac{u'v-uv'}{v^2}\\)","\\(\\big(f(g(x))\\big)'=f'(g(x))\\,g'(x)\\)","\\(f(x_0+\\Delta x)\\approx f(x_0)+f'(x_0)\\Delta x\\)","\\(MC(q)=C'(q)\\approx C(q+1)-C(q)\\)"],"exercises":[{"task":"Find \\(f'(x)\\) for \\(f(x)=4x^3-2x+7\\).","hint":"Power rule term by term; the derivative of a constant is 0.","answer":"\\(f'(x)=12x^2-2\\)"},{"task":"Use the definition of the derivative to find \\(f'(2)\\) for \\(f(x)=\\frac1x\\).","hint":"Write \\(\\frac{1}{2+h}-\\frac12\\) as one fraction first.","answer":"\\(\\frac{1}{2+h}-\\frac12=\\frac{-h}{2(2+h)}\\), quotient \\(=\\frac{-1}{2(2+h)}\\to-\\frac14\\). So \\(f'(2)=-\\frac14\\)."},{"task":"Find \\(f'(x)\\) for \\(f(x)=x\\ln x\\).","hint":"Product rule.","answer":"\\(f'(x)=1\\cdot\\ln x+x\\cdot\\frac1x=\\ln x+1\\)"},{"task":"Find \\(f'(x)\\) for \\(f(x)=\\frac{2x+1}{x+3}\\).","hint":"Quotient rule; simplify the numerator.","answer":"\\(f'(x)=\\frac{2(x+3)-(2x+1)}{(x+3)^2}=\\frac{5}{(x+3)^2}\\)"},{"task":"Find \\(f'(x)\\) for \\(f(x)=e^{x^2-3x}\\).","hint":"Chain rule with inner function \\(x^2-3x\\).","answer":"\\(f'(x)=(2x-3)e^{x^2-3x}\\)"},{"task":"Write the equation of the tangent line to \\(f(x)=x^3\\) at \\(x_0=1\\).","hint":"Compute \\(f(1)\\) and \\(f'(1)\\).","answer":"\\(f(1)=1,\\ f'(1)=3\\): \\(y=1+3(x-1)=3x-2\\)"},{"task":"Use the differential to approximate \\(\\sqrt[3]{8.12}\\).","hint":"\\(f(x)=x^{1/3}\\), \\(x_0=8\\), \\(\\Delta x=0.12\\).","answer":"\\(f'(8)=\\frac{1}{3\\cdot 8^{2/3}}=\\frac1{12}\\); \\(\\sqrt[3]{8.12}\\approx 2+\\frac{0.12}{12}=2.01\\) (true value 2.00995...)"},{"task":"A firm has cost \\(C(q)=0.02q^2+5q+1000\\). Find the marginal cost at \\(q=100\\) and use the differential to estimate the cost increase when output rises from 100 to 102 units. Compare with the exact increase.","hint":"\\(\\Delta C\\approx C'(100)\\cdot 2\\).","answer":"\\(MC(q)=0.04q+5\\), \\(MC(100)=9\\). Estimate: \\(9\\cdot2=18\\). Exact: \\(C(102)-C(100)=18.08\\)."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-06-monotonicity-extrema', $lekcja${"tldr":"The sign of the first derivative tells you where a function goes up and where it goes down. Points where \\(f'(x)=0\\) (or where \\(f'\\) does not exist) are critical points: the only candidates for local maxima and minima. You check them with the first-derivative test (does \\(f'\\) change sign?) or the second-derivative test (sign of \\(f''\\)). On a closed interval the global maximum and minimum are found by comparing values at critical points and at the endpoints. In economics this is exactly how a firm finds the output that maximises profit.","notes":[{"point":"\\(f'>0\\) on an interval means increasing, \\(f'<0\\) means decreasing. Always analyse the sign inside the domain.","slide":null},{"point":"Critical points are points of the domain where f'(x)=0 or f'(x) does not exist. Only they can be local extrema.","slide":null},{"point":"\\(f'(x_0)=0\\) is necessary but not sufficient: \\(x^3\\) has \\(f'(0)=0\\) and no extremum.","slide":null},{"point":"First-derivative test: sign change + to − gives a maximum, − to + gives a minimum, no sign change gives no extremum.","slide":null},{"point":"Second-derivative test: \\(f''(x_0)<0\\) max, \\(f''(x_0)>0\\) min, \\(f''(x_0)=0\\) no conclusion.","slide":null},{"point":"Global extrema on [a,b]: compare the values at the endpoints and at critical points inside the interval.","slide":null},{"point":"Write intervals of monotonicity separately, not as a union.","slide":null},{"point":"Profit is maximal where \\(MR=MC\\) (i.e. \\(\\pi'(q)=0\\)) and \\(\\pi''(q)<0\\).","slide":null}],"concepts":[{"term":"Increasing function","definition":"A function where a bigger \\(x\\) gives a bigger value: \\(x_1<x_2\\Rightarrow f(x_1)<f(x_2)\\).","pl":"funkcja rosnąca","slide":null},{"term":"Decreasing function","definition":"A function where a bigger \\(x\\) gives a smaller value: \\(x_1<x_2\\Rightarrow f(x_1)>f(x_2)\\).","pl":"funkcja malejąca","slide":null},{"term":"Critical (stationary) point","definition":"A point of the domain where f'(x)=0 (stationary) or f' does not exist.","pl":"punkt krytyczny (punkt stacjonarny)","slide":null},{"term":"Local maximum / minimum","definition":"A point where the function value is the largest / smallest compared with nearby points.","pl":"maksimum / minimum lokalne","slide":null},{"term":"Extremum","definition":"A common name for a maximum or a minimum.","pl":"ekstremum","slide":null},{"term":"Global (absolute) extremum","definition":"The largest or smallest value of a function on its whole domain or on a given interval.","pl":"ekstremum globalne (wartość największa / najmniejsza)","slide":null},{"term":"Necessary condition","definition":"A condition that must hold for an extremum (f'(x0)=0), but alone does not guarantee it.","pl":"warunek konieczny","slide":null},{"term":"Sufficient condition","definition":"A condition that guarantees an extremum, e.g. a sign change of f' or f''(x0)≠0.","pl":"warunek wystarczający","slide":null},{"term":"Marginal revenue","definition":"The derivative of revenue, R'(q); approximately the extra revenue from one more unit sold.","pl":"przychód krańcowy","slide":null}],"flashcards":[{"q":"What does f'(x)>0 on an interval tell you?","a":"f is increasing on that interval.","slide":null},{"q":"What is a critical point?","a":"A point of the domain where f'(x)=0 or f'(x) does not exist.","slide":null},{"q":"Necessary condition for an extremum (differentiable f)?","a":"\\(f'(x_0)=0\\)","slide":null},{"q":"Example: f'(x0)=0 but no extremum?","a":"\\(f(x)=x^3\\) at \\(x_0=0\\).","slide":null},{"q":"First-derivative test: f' changes from + to −. What is it?","a":"A local maximum.","slide":null},{"q":"Second-derivative test: f'(x0)=0 and f''(x0)>0?","a":"A local minimum.","slide":null},{"q":"What if f'(x0)=0 and f''(x0)=0?","a":"No conclusion; use the first-derivative test (sign change of f').","slide":null},{"q":"How to find global extrema on [a,b]?","a":"Compute f at the endpoints and at critical points inside; pick the largest and the smallest.","slide":null},{"q":"Profit-maximisation condition?","a":"\\(MR=MC\\), i.e. \\(\\pi'(q)=0\\), with \\(\\pi''(q)<0\\).","slide":null},{"q":"Revenue from a demand function p(q)?","a":"\\(R(q)=p(q)\\cdot q\\)","slide":null}],"quiz":[{"q":"\\(f'(x)=2x-4\\). On which interval is \\(f\\) increasing?","options":["\\((2,\\infty)\\)","\\((-\\infty,2)\\)","\\((-4,\\infty)\\)","\\((-\\infty,\\infty)\\)"],"correct":0,"explanation":"\\(2x-4>0\\iff x>2\\).","slide":null},{"q":"Which statement about \\(f(x)=x^3\\) at \\(x=0\\) is correct?","options":["It has a local minimum","It has a local maximum","f'(0)=0, but there is no extremum","f'(0) does not exist"],"correct":2,"explanation":"f'(x)=3x² is 0 at 0 but does not change sign, so x³ keeps increasing: no extremum.","slide":null},{"q":"\\(f'\\) changes sign from − to + at \\(x_0\\). Then \\(f\\) has at \\(x_0\\)...","options":["a local maximum","an inflection point only","no extremum","a local minimum"],"correct":3,"explanation":"Decreasing then increasing means the graph has a bottom point: a local minimum.","slide":null},{"q":"\\(f'(x_0)=0\\) and \\(f''(x_0)=-5\\). What is at \\(x_0\\)?","options":["local minimum","local maximum","no extremum","we cannot say anything"],"correct":1,"explanation":"f''<0 means the graph bends down (∩), so a stationary point there is a local maximum.","slide":null},{"q":"\\(f'(x_0)=0\\) and \\(f''(x_0)=0\\). What can you conclude?","options":["There is a local minimum","There is a local maximum","There is no extremum","Nothing yet: check the sign change of f'"],"correct":3,"explanation":"The second-derivative test fails when \\(f''(x_0)=0\\). E.g. \\(x^4\\) has a min at 0, \\(x^3\\) has none.","slide":null},{"q":"What is the global maximum of \\(f(x)=x^3-3x\\) on \\([0,2]\\)?","options":["0","2","−2","There is none"],"correct":1,"explanation":"Values: f(0)=0, f(1)=−2, f(2)=2. The maximum is at the endpoint x=2.","slide":null},{"q":"A firm maximises profit where...","options":["revenue is maximal","average cost is minimal","marginal revenue equals marginal cost","price equals average cost"],"correct":2,"explanation":"\\(\\pi'(q)=R'(q)-C'(q)=0\\iff MR=MC\\). Maximum revenue is a different point.","slide":null},{"q":"True or false: to find global extrema on a closed interval you must also check the endpoints.","options":["True","False"],"correct":0,"explanation":"True. The largest or smallest value is often at an endpoint, where f' need not be 0.","slide":null}],"lang":"en","lesson":{"intro":"A firm wants the output with the highest profit; a buyer wants the lowest average cost. Both are 'find the top or the bottom of a graph' problems. The derivative solves them in a few mechanical steps.","sections":[{"h":"1. Monotonicity from the sign of f'","body":"Let \\(f\\) be differentiable on an interval \\(I\\).\n\n- If \\(f'(x)>0\\) for all \\(x\\in I\\), then \\(f\\) is **increasing** on \\(I\\).\n- If \\(f'(x)<0\\) for all \\(x\\in I\\), then \\(f\\) is **decreasing** on \\(I\\).\n- If \\(f'(x)=0\\) for all \\(x\\in I\\), then \\(f\\) is constant on \\(I\\).\n\nMethod: compute \\(f'\\), find where \\(f'(x)=0\\), then check the sign of \\(f'\\) between these points (a sign chart or a quick sketch of \\(f'\\) helps). Always work inside the **domain** of \\(f\\).","example":{"task":"Find the intervals of monotonicity of \\(f(x)=x^2-4x\\).","steps":["\\(f'(x)=2x-4\\)","\\(f'(x)>0 \\iff x>2\\); \\(f'(x)<0 \\iff x<2\\)"],"answer":"decreasing on \\((-\\infty,2)\\), increasing on \\((2,\\infty)\\)"},"tip":"Write intervals of monotonicity separately. Do not join them with a union sign: a function can be decreasing on two intervals without being decreasing on their union (think of 1/x)."},{"h":"2. Critical points and the necessary condition","body":"A function has a **local maximum** at \\(x_0\\) if \\(f(x)\\le f(x_0)\\) for all \\(x\\) near \\(x_0\\), and a **local minimum** if \\(f(x)\\ge f(x_0)\\) near \\(x_0\\). Together they are called local **extrema**.\n\n**Necessary condition (Fermat's theorem):** if \\(f\\) has a local extremum at \\(x_0\\) and \\(f'(x_0)\\) exists, then\n\\[ f'(x_0)=0 \\]\nPoints of the domain where \\(f'(x)=0\\) or where \\(f'\\) does not exist are called **critical points**. They are the only candidates for extrema.\n\nWarning: \\(f'(x_0)=0\\) is **not enough**. For \\(f(x)=x^3\\) we have \\(f'(0)=0\\), but \\(x^3\\) is increasing everywhere, so there is no extremum at 0. On the other hand \\(|x|\\) has a minimum at 0 although \\(f'(0)\\) does not exist.","tip":"In the exam, write: 'necessary condition: f'(x)=0' and then 'sufficient condition: ...'. Examiners like to see both steps."},{"h":"3. First-derivative test","body":"**Sufficient condition I.** Let \\(x_0\\) be a critical point and \\(f\\) be continuous at \\(x_0\\).\n\n- \\(f'\\) changes from **+ to −** at \\(x_0\\): local **maximum** (up, then down).\n- \\(f'\\) changes from **− to +** at \\(x_0\\): local **minimum** (down, then up).\n- \\(f'\\) does not change sign: no extremum.\n\nThis test always works, also when \\(f'(x_0)\\) does not exist, and it gives you the monotonicity at the same time.","example":{"task":"Find the local extrema of \\(f(x)=x^3-3x^2-9x+5\\).","steps":["\\(f'(x)=3x^2-6x-9=3(x+1)(x-3)\\)","Critical points: \\(x=-1\\) and \\(x=3\\)","Sign of \\(f'\\): \\(+\\) on \\((-\\infty,-1)\\), \\(-\\) on \\((-1,3)\\), \\(+\\) on \\((3,\\infty)\\)","At \\(x=-1\\): + to −, maximum, \\(f(-1)=-1-3+9+5=10\\)","At \\(x=3\\): − to +, minimum, \\(f(3)=27-27-27+5=-22\\)"],"answer":"local max \\(f(-1)=10\\), local min \\(f(3)=-22\\)"}},{"h":"4. Second-derivative test","body":"**Sufficient condition II.** If \\(f'(x_0)=0\\) and \\(f''(x_0)\\) exists, then:\n\n- \\(f''(x_0)<0\\): local **maximum** (the graph bends down, like ∩)\n- \\(f''(x_0)>0\\): local **minimum** (the graph bends up, like ∪)\n- \\(f''(x_0)=0\\): the test gives **no answer**; go back to the first-derivative test.\n\nThis test is quick when \\(f''\\) is easy to compute, but it does not give you the intervals of monotonicity.","example":{"task":"Check the critical points of \\(f(x)=x^3-3x^2-9x+5\\) with the second derivative.","steps":["\\(f''(x)=6x-6\\)","\\(f''(-1)=-12<0\\): maximum at \\(x=-1\\)","\\(f''(3)=12>0\\): minimum at \\(x=3\\)"],"answer":"The same result as the first-derivative test."},"tip":"Memory trick: \\(f''<0\\) is a 'sad face' ∩ with a maximum on top; \\(f''>0\\) is a 'happy face' ∪ with a minimum at the bottom."},{"h":"5. Global extrema on a closed interval","body":"A continuous function on a closed interval \\([a,b]\\) always has a global (absolute) maximum and minimum (Weierstrass theorem). To find them:\n\n1. Find the critical points of \\(f\\) that lie **inside** \\((a,b)\\).\n2. Compute \\(f\\) at these points and at the endpoints \\(a\\) and \\(b\\).\n3. The biggest value is the global maximum, the smallest is the global minimum.\n\nYou do not need to classify the critical points here: just compare values.","example":{"task":"Find the global extrema of \\(f(x)=x^3-3x\\) on \\([0,2]\\).","steps":["\\(f'(x)=3x^2-3=0 \\iff x=\\pm1\\); only \\(x=1\\) lies in \\([0,2]\\)","\\(f(0)=0,\\ f(1)=-2,\\ f(2)=8-6=2\\)","Compare the three values"],"answer":"global min \\(-2\\) at \\(x=1\\); global max \\(2\\) at \\(x=2\\)"},"tip":"Students often forget the endpoints. Here the global maximum is at an endpoint, not at a critical point."},{"h":"6. Economics: profit maximisation","body":"Profit is revenue minus cost: \\(\\pi(q)=R(q)-C(q)\\). To maximise it:\n\\[ \\pi'(q)=0 \\iff R'(q)=C'(q) \\iff MR=MC \\]\nand then check that it is a maximum, e.g. \\(\\pi''(q)<0\\). If demand is \\(p=p(q)\\), revenue is \\(R(q)=p(q)\\cdot q\\).","example":{"task":"Demand: \\(p=100-q\\). Cost: \\(C(q)=20q+300\\). Find the output and price that maximise profit, and the maximum profit.","steps":["\\(R(q)=(100-q)q=100q-q^2\\)","\\(\\pi(q)=100q-q^2-20q-300=80q-q^2-300\\)","\\(\\pi'(q)=80-2q=0 \\Rightarrow q=40\\) (check: \\(MR=100-2q=20=MC\\))","\\(\\pi''(q)=-2<0\\), so it is a maximum","\\(\\pi(40)=3200-1600-300=1300\\), price \\(p=100-40=60\\)"],"answer":"\\(q=40\\), \\(p=60\\), maximum profit \\(1300\\)"}}],"formulas":["\\(f'>0\\) on \\(I\\Rightarrow f\\) increasing; \\(f'<0\\) on \\(I\\Rightarrow f\\) decreasing","Necessary condition: extremum at \\(x_0\\) and \\(f'(x_0)\\) exists \\(\\Rightarrow f'(x_0)=0\\)","Test I: \\(f'\\) changes + to − \\(\\Rightarrow\\) max; − to + \\(\\Rightarrow\\) min","Test II: \\(f'(x_0)=0,\\ f''(x_0)<0\\Rightarrow\\) max; \\(f''(x_0)>0\\Rightarrow\\) min","Global extrema on \\([a,b]\\): compare \\(f(a),\\ f(b)\\) and \\(f\\) at critical points in \\((a,b)\\)","\\(\\pi(q)=R(q)-C(q)\\), maximum where \\(MR=MC\\) and \\(\\pi''(q)<0\\)"],"exercises":[{"task":"Find the intervals of monotonicity of \\(f(x)=x^3-12x\\).","hint":"\\(f'(x)=3(x^2-4)\\).","answer":"increasing on \\((-\\infty,-2)\\) and \\((2,\\infty)\\); decreasing on \\((-2,2)\\)"},{"task":"Find the local extrema of \\(f(x)=x^3-12x\\).","hint":"Use the sign chart from the previous exercise.","answer":"local max \\(f(-2)=16\\), local min \\(f(2)=-16\\)"},{"task":"Find the local extrema of \\(f(x)=x^4-2x^2\\) using the second-derivative test.","hint":"\\(f'(x)=4x(x-1)(x+1)\\), \\(f''(x)=12x^2-4\\).","answer":"\\(f''(0)=-4<0\\): local max \\(f(0)=0\\); \\(f''(\\pm1)=8>0\\): local minima \\(f(-1)=f(1)=-1\\)"},{"task":"Find the monotonicity and extrema of \\(f(x)=xe^{-x}\\).","hint":"\\(f'(x)=e^{-x}(1-x)\\) and \\(e^{-x}>0\\).","answer":"increasing on \\((-\\infty,1)\\), decreasing on \\((1,\\infty)\\); local max \\(f(1)=\\frac1e\\approx0.37\\)"},{"task":"Find the local extremum of \\(f(x)=\\ln x-x\\).","hint":"Domain is \\(x>0\\). \\(f'(x)=\\frac1x-1\\).","answer":"\\(f'>0\\) on \\((0,1)\\), \\(f'<0\\) on \\((1,\\infty)\\): local (and global) max \\(f(1)=-1\\)"},{"task":"Find the global maximum and minimum of \\(f(x)=2x^3-3x^2-12x+1\\) on \\([-2,3]\\).","hint":"\\(f'(x)=6(x+1)(x-2)\\); both critical points lie in the interval.","answer":"\\(f(-2)=-3,\\ f(-1)=8,\\ f(2)=-19,\\ f(3)=-8\\). Global max 8 at \\(x=-1\\), global min \\(-19\\) at \\(x=2\\)."},{"task":"Average cost of a firm is \\(AC(q)=0.5q+\\frac{50}{q}\\) for \\(q>0\\). For which output is average cost lowest, and what is it?","hint":"\\(AC'(q)=0.5-\\frac{50}{q^2}\\).","answer":"\\(q^2=100\\Rightarrow q=10\\); \\(AC''(q)=\\frac{100}{q^3}>0\\), so minimum; \\(AC(10)=10\\)"},{"task":"Demand: \\(p=50-0.5q\\). Cost: \\(C(q)=10q+200\\). Find the profit-maximising output, price and profit.","hint":"\\(R(q)=50q-0.5q^2\\); set \\(\\pi'(q)=0\\).","answer":"\\(\\pi(q)=40q-0.5q^2-200\\), \\(\\pi'(q)=40-q=0\\Rightarrow q=40\\), \\(\\pi''=-1<0\\). Price \\(p=30\\), profit \\(\\pi(40)=600\\)."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-07-concavity-inflection', $lekcja${"tldr":"The second derivative \\(f''\\) tells you how the graph bends. Where \\(f''>0\\) the function is convex (bends up, like ∪); where \\(f''<0\\) it is concave (bends down, like ∩). A point where the bending changes is an inflection point; a candidate is a point where \\(f''=0\\) or \\(f''\\) does not exist, but you must check that \\(f''\\) really changes sign. This lesson gives a step-by-step method you can use in every exam task. In economics, a concave production function means diminishing returns: each extra worker adds less output than the previous one.","notes":[{"point":"\\(f''>0\\) on an interval: convex (∪, bends up). \\(f''<0\\): concave (∩, bends down).","slide":null},{"point":"A convex graph lies above its tangent lines; a concave graph lies below them.","slide":null},{"point":"An inflection point is where convexity changes into concavity or the other way round, and the point must belong to the domain.","slide":null},{"point":"\\(f''(x_0)=0\\) is only a candidate; you must check that \\(f''\\) changes sign. Counterexample: \\(x^4\\) at 0.","slide":null},{"point":"Write an inflection point as (x0, f(x0)) using the original function.","slide":null},{"point":"Positive factors (e.g. eˣ, (x²+1)²) do not affect the sign of f''; ignore them in the sign chart.","slide":null},{"point":"Terminology differs between books: convex = concave up, concave = concave down. In Polish: wypukła / wklęsła.","slide":null},{"point":"Diminishing returns: the production function is concave (Q''<0), so the marginal product falls. The inflection point is where MP is maximal.","slide":null}],"concepts":[{"term":"Second derivative","definition":"The derivative of the first derivative; it shows how the slope of the graph changes.","pl":"druga pochodna","slide":null},{"term":"Convex function (concave up)","definition":"A function that bends upwards (∪) on an interval; for twice differentiable f this happens when f''>0.","pl":"funkcja wypukła (dawniej: wypukła w dół)","slide":null},{"term":"Concave function (concave down)","definition":"A function that bends downwards (∩) on an interval; for twice differentiable f this happens when f''<0.","pl":"funkcja wklęsła (dawniej: wypukła w górę)","slide":null},{"term":"Inflection point","definition":"A point of the graph where the function changes from convex to concave or vice versa.","pl":"punkt przegięcia","slide":null},{"term":"Marginal product","definition":"The derivative of the production function; the extra output from one more unit of input.","pl":"produkt krańcowy (wydajność krańcowa)","slide":null},{"term":"Diminishing returns","definition":"A situation where each additional unit of input adds less output than the previous one; the production function is concave.","pl":"malejące przychody (prawo malejących przychodów)","slide":null},{"term":"Sign chart","definition":"A table or line showing where an expression is positive or negative between its zeros.","pl":"tabela (schemat) znaków","slide":null}],"flashcards":[{"q":"f''(x)>0 on an interval means?","a":"The function is convex (∪) there.","slide":null},{"q":"f''(x)<0 on an interval means?","a":"The function is concave (∩) there.","slide":null},{"q":"What is an inflection point?","a":"A point of the graph where convexity changes to concavity or vice versa.","slide":null},{"q":"Necessary condition for an inflection point?","a":"\\(f''(x_0)=0\\) (if \\(f''(x_0)\\) exists).","slide":null},{"q":"Sufficient condition for an inflection point?","a":"f'' changes sign at x0 (and x0 is in the domain).","slide":null},{"q":"Why does x⁴ have no inflection point at 0?","a":"\\(f''=12x^2\\ge0\\) on both sides; no sign change.","slide":null},{"q":"Does 1/x have an inflection point?","a":"No. The concavity changes at 0, but 0 is not in the domain.","slide":null},{"q":"Where does a convex graph lie relative to its tangents?","a":"Above its tangent lines.","slide":null},{"q":"Diminishing returns in terms of derivatives?","a":"\\(Q''(L)<0\\): marginal product \\(Q'(L)\\) is decreasing.","slide":null},{"q":"What is special about MP at the inflection point of Q?","a":"The marginal product reaches its maximum there.","slide":null}],"quiz":[{"q":"\\(f''(x)>0\\) on an interval. The graph there is...","options":["concave (∩)","convex (∪)","decreasing","increasing"],"correct":1,"explanation":"f''>0 means the slope is increasing, so the graph bends upwards. It says nothing about increasing or decreasing.","slide":null},{"q":"For \\(f(x)=x^3-6x^2+5\\), the inflection point is...","options":["\\((2,-11)\\)","\\((2,0)\\)","\\((0,5)\\)","\\((4,-27)\\)"],"correct":0,"explanation":"\\(f''(x)=6x-12\\) changes sign at \\(x=2\\); \\(f(2)=8-24+5=-11\\). (2,0) uses f''(2) instead of f(2).","slide":null},{"q":"\\(f''(x_0)=0\\). Is \\((x_0,f(x_0))\\) always an inflection point?","options":["Yes, always","Yes, if f'(x0)=0 too","Only if f(x0)=0","No, f'' must also change sign"],"correct":3,"explanation":"Counterexample: \\(x^4\\) has \\(f''(0)=0\\) but is convex on both sides.","slide":null},{"q":"Where is \\(f(x)=\\ln(x^2+1)\\) convex?","options":["\\((-\\infty,-1)\\) and \\((1,\\infty)\\)","\\((0,\\infty)\\)","\\((-1,1)\\)","everywhere"],"correct":2,"explanation":"\\(f''(x)=\\frac{2(1-x^2)}{(x^2+1)^2}>0\\iff -1<x<1\\).","slide":null},{"q":"\\(f(x)=\\frac1x\\). Which statement is true?","options":["Inflection point at (0,0)","Concave for x<0, convex for x>0, no inflection point","Convex everywhere","Concave everywhere"],"correct":1,"explanation":"\\(f''=\\frac{2}{x^3}\\) changes sign at 0, but 0 is not in the domain, so there is no inflection point.","slide":null},{"q":"A production function Q(L) shows diminishing returns when...","options":["\\(Q'(L)<0\\)","\\(Q(L)<0\\)","\\(Q''(L)>0\\)","\\(Q''(L)<0\\)"],"correct":3,"explanation":"Diminishing returns means the marginal product Q' decreases, i.e. Q''<0. Output itself may still grow.","slide":null},{"q":"\\(Q(L)=12L^2-L^3\\). At which \\(L\\) is the marginal product maximal?","options":["L = 4","L = 8","L = 12","L = 2"],"correct":0,"explanation":"\\(Q''(L)=24-6L=0\\) at \\(L=4\\), where \\(Q''\\) changes from + to −, so \\(MP=Q'\\) is maximal.","slide":null},{"q":"True or false: a convex function must be increasing.","options":["True","False"],"correct":1,"explanation":"False. x² is convex everywhere but decreasing for x<0. Convexity describes bending, not direction.","slide":null}],"lang":"en","lesson":{"intro":"Two firms can both be growing, but one grows faster and faster while the other is slowing down. The first derivative only says 'growing'; the second derivative tells you how the growth itself behaves.","sections":[{"h":"1. The second derivative","body":"The **second derivative** is the derivative of the derivative:\n\\[ f''(x)=\\big(f'(x)\\big)' \\]\nIt measures how fast the slope changes. If \\(f''>0\\), the slope \\(f'\\) is increasing; if \\(f''<0\\), the slope is decreasing.","example":{"task":"Find \\(f''(x)\\) for \\(f(x)=x^3-6x^2+5\\).","steps":["\\(f'(x)=3x^2-12x\\)","\\(f''(x)=6x-12=6(x-2)\\)"],"answer":"\\(f''(x)=6(x-2)\\)"}},{"h":"2. Convex and concave functions","body":"Let \\(f\\) be twice differentiable on an interval \\(I\\).\n\n- \\(f''(x)>0\\) on \\(I\\): \\(f\\) is **convex** on \\(I\\) (concave up, ∪). The graph lies **above** its tangent lines and slopes increase.\n- \\(f''(x)<0\\) on \\(I\\): \\(f\\) is **concave** on \\(I\\) (concave down, ∩). The graph lies **below** its tangent lines and slopes decrease.\n\nNote on names: some books say 'concave up / concave down' instead of 'convex / concave'. In Polish, convex is usually *wypukła* (older books: *wypukła w dół*) and concave is *wklęsła* (older: *wypukła w górę*). Check which convention your lecturer uses.","example":{"task":"Where is \\(f(x)=x^3-6x^2+5\\) convex and where concave?","steps":["\\(f''(x)=6(x-2)\\)","\\(f''<0\\) for \\(x<2\\), \\(f''>0\\) for \\(x>2\\)"],"answer":"concave on \\((-\\infty,2)\\), convex on \\((2,\\infty)\\)"},"tip":"Convexity is not the same as increasing. A convex function can go down (e.g. x² for x<0); it just bends upwards."},{"h":"3. Inflection points","body":"An **inflection point** is a point \\((x_0,f(x_0))\\) of the graph where the function changes from convex to concave or the other way round. The function must be defined (and continuous) at \\(x_0\\).\n\n- **Necessary condition:** if \\(f''(x_0)\\) exists and \\((x_0,f(x_0))\\) is an inflection point, then \\(f''(x_0)=0\\).\n- **Sufficient condition:** \\(f''\\) **changes sign** at \\(x_0\\).\n\nWarning: \\(f''(x_0)=0\\) alone is not enough. For \\(f(x)=x^4\\) we get \\(f''(x)=12x^2\\), so \\(f''(0)=0\\), but \\(f''\\ge 0\\) on both sides: \\(x^4\\) is convex everywhere and has no inflection point.\n\nFor \\(f(x)=x^3-6x^2+5\\): \\(f''\\) changes sign at \\(x=2\\), and \\(f(2)=8-24+5=-11\\), so the inflection point is \\((2,-11)\\).","tip":"Give an inflection point as a point (x, y), not only x. Compute f(x0) in the ORIGINAL function, not in f''."},{"h":"4. Step-by-step method","body":"Use this recipe in every exam task about concavity:\n\n1. Find the **domain** of \\(f\\).\n2. Compute \\(f'\\) and then \\(f''\\); simplify and factorise \\(f''\\).\n3. Solve \\(f''(x)=0\\) and find points where \\(f''\\) does not exist.\n4. Make a **sign chart** of \\(f''\\) on the intervals between these points (and points outside the domain).\n5. \\(f''>0\\): convex; \\(f''<0\\): concave.\n6. Where the sign changes **and** \\(x_0\\) is in the domain: inflection point \\((x_0,f(x_0))\\).","example":{"task":"Analyse the concavity of \\(f(x)=\\ln(x^2+1)\\).","steps":["Domain: all real numbers, since \\(x^2+1>0\\)","\\(f'(x)=\\frac{2x}{x^2+1}\\)","Quotient rule: \\(f''(x)=\\frac{2(x^2+1)-2x\\cdot 2x}{(x^2+1)^2}=\\frac{2(1-x^2)}{(x^2+1)^2}\\)","\\(f''(x)=0\\iff x=\\pm1\\); the denominator is always positive","Sign of \\(1-x^2\\): \\(-\\) on \\((-\\infty,-1)\\), \\(+\\) on \\((-1,1)\\), \\(-\\) on \\((1,\\infty)\\)","\\(f(\\pm1)=\\ln 2\\)"],"answer":"concave on \\((-\\infty,-1)\\) and \\((1,\\infty)\\), convex on \\((-1,1)\\); inflection points \\((-1,\\ln2)\\) and \\((1,\\ln2)\\)"},"tip":"Positive factors like (x²+1)² or eˣ never change the sign, so you can ignore them in the sign chart."},{"h":"5. Economics: diminishing returns","body":"Let \\(Q(L)\\) be output produced with \\(L\\) workers. The **marginal product** is \\(MP(L)=Q'(L)\\): the extra output from one more worker.\n\n- \\(Q''(L)>0\\) (convex): \\(MP\\) is rising, **increasing returns**: each new worker adds more than the previous one.\n- \\(Q''(L)<0\\) (concave): \\(MP\\) is falling, **diminishing returns**: each new worker adds less.\n- The inflection point is where diminishing returns start; there the marginal product is **maximal**.\n\nIn the same way, a cost function that is convex means marginal cost is rising.","example":{"task":"\\(Q(L)=12L^2-L^3\\) for \\(L\\ge0\\). Where do diminishing returns start?","steps":["\\(MP(L)=Q'(L)=24L-3L^2\\)","\\(Q''(L)=24-6L=6(4-L)\\)","\\(Q''>0\\) for \\(L<4\\), \\(Q''<0\\) for \\(L>4\\)","At \\(L=4\\): \\(MP(4)=96-48=48\\), \\(Q(4)=192-64=128\\)"],"answer":"Inflection point \\((4,128)\\): diminishing returns start after 4 workers, where the marginal product reaches its maximum 48."}}],"formulas":["\\(f''(x)=\\big(f'(x)\\big)'\\)","\\(f''>0\\) on \\(I\\Rightarrow\\) convex (∪); \\(f''<0\\) on \\(I\\Rightarrow\\) concave (∩)","Necessary condition for inflection: \\(f''(x_0)=0\\) (if \\(f''(x_0)\\) exists)","Sufficient condition: \\(f''\\) changes sign at \\(x_0\\) and \\(x_0\\in D_f\\)","Inflection point is written as \\((x_0,f(x_0))\\)","Diminishing returns: \\(Q''(L)<0\\), i.e. \\(MP=Q'\\) decreasing"],"exercises":[{"task":"Find the intervals of convexity/concavity and the inflection point of \\(f(x)=x^3-3x^2+2\\).","hint":"\\(f''(x)=6x-6\\).","answer":"concave on \\((-\\infty,1)\\), convex on \\((1,\\infty)\\); inflection point \\((1,0)\\)"},{"task":"Analyse the concavity of \\(f(x)=x^4-6x^2\\).","hint":"\\(f''(x)=12x^2-12=12(x-1)(x+1)\\).","answer":"convex on \\((-\\infty,-1)\\) and \\((1,\\infty)\\), concave on \\((-1,1)\\); inflection points \\((-1,-5)\\) and \\((1,-5)\\)"},{"task":"Does \\(f(x)=\\frac1x\\) have an inflection point?","hint":"\\(f''(x)=\\frac{2}{x^3}\\). Is 0 in the domain?","answer":"concave on \\((-\\infty,0)\\), convex on \\((0,\\infty)\\), but \\(x=0\\) is not in the domain, so there is no inflection point."},{"task":"Analyse the concavity of \\(f(x)=xe^{-x}\\).","hint":"\\(f'(x)=(1-x)e^{-x}\\), \\(f''(x)=(x-2)e^{-x}\\).","answer":"concave on \\((-\\infty,2)\\), convex on \\((2,\\infty)\\); inflection point \\((2,\\,2e^{-2})\\approx(2,\\,0.27)\\)"},{"task":"Find the inflection points of \\(f(x)=x^5-5x^4\\).","hint":"\\(f''(x)=20x^2(x-3)\\). Does the sign change at \\(x=0\\)?","answer":"\\(f''\\le0\\) on both sides of 0 (no change), so 0 is not an inflection point. Sign changes at \\(x=3\\): concave on \\((-\\infty,3)\\), convex on \\((3,\\infty)\\); inflection point \\((3,-162)\\)."},{"task":"Production: \\(Q(L)=30L^2-L^3\\), \\(L\\ge0\\). For which \\(L\\) are there diminishing returns?","hint":"Solve \\(Q''(L)<0\\).","answer":"\\(Q''(L)=60-6L<0\\iff L>10\\). Diminishing returns for \\(L>10\\); the marginal product is highest at \\(L=10\\)."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-08-lhospital', $lekcja${"tldr":"L'Hospital's rule is a fast way to compute limits of the form \\(\\frac00\\) or \\(\\frac\\infty\\infty\\): you replace the fraction by the fraction of the derivatives of the numerator and the denominator. It works only for these two forms, so you must always check the form first. Other indeterminate forms (\\(0\\cdot\\infty\\), \\(\\infty-\\infty\\), \\(1^\\infty\\), \\(0^0\\), \\(\\infty^0\\)) are first rewritten as a fraction, or with logarithms, and then the rule is used. In economics, the same idea gives the continuous-compounding formula: \\((1+\\frac rn)^n\\to e^r\\).","notes":[{"point":"L'Hospital's rule applies ONLY to the forms \\(\\frac00\\) and \\(\\frac\\infty\\infty\\). Always substitute first and check the form.","slide":null},{"point":"Differentiate the numerator and the denominator separately. Do not use the quotient rule.","slide":null},{"point":"The rule may be applied several times, as long as the form stays 0/0 or ∞/∞.","slide":null},{"point":"If \\(\\lim\\frac{f'}{g'}\\) does not exist, the rule gives no information; e.g. \\(\\frac{x+\\sin x}{x}\\to1\\) as \\(x\\to\\infty\\).","slide":null},{"point":"Growth order as \\(x\\to\\infty\\): \\(\\ln x\\ll x^n\\ll e^x\\), so \\(\\frac{\\ln x}{x}\\to0\\) and \\(\\frac{x^n}{e^x}\\to0\\).","slide":null},{"point":"\\(0\\cdot\\infty\\): rewrite as a fraction \\(\\frac{f}{1/g}\\). \\(\\infty-\\infty\\): common denominator.","slide":null},{"point":"\\(1^\\infty, 0^0, \\infty^0\\): use \\(f^g=e^{g\\ln f}\\), compute the limit of the exponent, then take \\(e\\) to that power.","slide":null},{"point":"Continuous compounding: \\((1+\\frac rn)^n\\to e^r\\); \\(1^\\infty\\) is not automatically 1.","slide":null}],"concepts":[{"term":"Indeterminate form","definition":"An expression like \\(\\frac00,\\frac\\infty\\infty,0\\cdot\\infty,\\infty-\\infty,1^\\infty,0^0,\\infty^0\\) whose limit cannot be read off directly.","pl":"symbol nieoznaczony (wyrażenie nieoznaczone)","slide":null},{"term":"L'Hospital's rule","definition":"A theorem: for forms 0/0 and ∞/∞ the limit of f/g equals the limit of f'/g' (if the latter exists).","pl":"reguła de l'Hospitala","slide":null},{"term":"One-sided limit","definition":"A limit where \\(x\\) approaches \\(a\\) only from the left (\\(a^-\\)) or only from the right (\\(a^+\\)).","pl":"granica jednostronna","slide":null},{"term":"Order of growth","definition":"A comparison of how fast functions go to infinity; exponentials beat powers, powers beat logarithms.","pl":"rząd wzrostu (szybkość wzrostu)","slide":null},{"term":"Continuous compounding","definition":"Interest added infinitely often; capital \\(K\\) grows to \\(Ke^{rt}\\) after \\(t\\) years.","pl":"kapitalizacja ciągła","slide":null},{"term":"Common denominator","definition":"Bringing fractions to the same denominator so they can be combined into one fraction.","pl":"wspólny mianownik","slide":null}],"flashcards":[{"q":"For which forms can you use L'Hospital's rule directly?","a":"\\(\\frac00\\) and \\(\\frac\\infty\\infty\\)","slide":null},{"q":"State L'Hospital's rule.","a":"\\(\\lim\\frac fg=\\lim\\frac{f'}{g'}\\), if the form is 0/0 or ∞/∞ and the right side exists.","slide":null},{"q":"Do you use the quotient rule in L'Hospital?","a":"No. Differentiate numerator and denominator separately.","slide":null},{"q":"\\(\\lim_{x\\to0}\\frac{e^x-1}{x}=\\)?","a":"1","slide":null},{"q":"\\(\\lim_{x\\to\\infty}\\frac{x^n}{e^x}=\\)?","a":"0","slide":null},{"q":"How to handle 0·∞?","a":"Rewrite as a fraction: \\(fg=\\frac{f}{1/g}\\).","slide":null},{"q":"How to handle ∞−∞?","a":"Bring to a common denominator to get 0/0 or ∞/∞.","slide":null},{"q":"How to handle \\(1^\\infty, 0^0, \\infty^0\\)?","a":"\\(f^g=e^{g\\ln f}\\); find the limit of \\(g\\ln f\\).","slide":null},{"q":"\\(\\lim_{x\\to0^+}x\\ln x=\\)?","a":"0","slide":null},{"q":"\\(\\lim_{n\\to\\infty}(1+\\frac rn)^n=\\)?","a":"\\(e^r\\)","slide":null},{"q":"Example where L'Hospital gives a wrong answer?","a":"\\(\\lim_{x\\to0}\\frac{x+1}{x+2}=\\frac12\\) is not 0/0; the rule would wrongly give 1.","slide":null}],"quiz":[{"q":"\\(\\lim_{x\\to0}\\frac{e^{3x}-1}{x}=\\)?","options":["1","0","3","\\(\\infty\\)"],"correct":2,"explanation":"Form \\(\\frac00\\); \\(\\frac{3e^{3x}}{1}\\to3\\).","slide":null},{"q":"For which limit can L'Hospital's rule be used directly?","options":["\\(\\lim_{x\\to0}\\frac{x+1}{x+2}\\)","\\(\\lim_{x\\to\\infty}\\frac{\\ln x}{x}\\)","\\(\\lim_{x\\to0^+}x\\ln x\\)","\\(\\lim_{x\\to\\infty}(1+\\frac1x)^x\\)"],"correct":1,"explanation":"Only \\(\\frac{\\ln x}{x}\\) is already \\(\\frac\\infty\\infty\\). The first is not indeterminate; the others must be rewritten first.","slide":null},{"q":"\\(\\lim_{x\\to\\infty}\\frac{x^2}{e^x}=\\)?","options":["0","1","2","\\(\\infty\\)"],"correct":0,"explanation":"Apply the rule twice: 2/eˣ → 0. Exponentials grow faster than powers.","slide":null},{"q":"In L'Hospital's rule, \\(\\frac{f}{g}\\) is replaced by...","options":["\\(\\left(\\frac fg\\right)'\\)","\\(\\frac{f'g-fg'}{g^2}\\)","\\(\\frac{f}{g'}\\)","\\(\\frac{f'}{g'}\\)"],"correct":3,"explanation":"You differentiate the numerator and the denominator separately; the quotient rule is a common mistake.","slide":null},{"q":"\\(\\lim_{x\\to0^+}x\\ln x=\\)?","options":["\\(-\\infty\\)","0","1","\\(-1\\)"],"correct":1,"explanation":"\\(\\frac{\\ln x}{1/x}\\to\\frac{1/x}{-1/x^2}=-x\\to0\\).","slide":null},{"q":"\\(\\lim_{x\\to\\infty}\\left(1+\\frac3x\\right)^x=\\)?","options":["1","3","\\(\\infty\\)","\\(e^3\\)"],"correct":3,"explanation":"\\(1^\\infty\\) form; the exponent \\(x\\ln(1+\\frac3x)\\to3\\), so the limit is \\(e^3\\). It is not 1.","slide":null},{"q":"How do you start with the form ∞ − ∞?","options":["Apply L'Hospital directly","Bring the expression to a common denominator","Take the logarithm","The answer is always 0"],"correct":1,"explanation":"A common denominator turns ∞−∞ into a single fraction, usually 0/0 or ∞/∞.","slide":null},{"q":"True or false: if \\(\\lim\\frac{f'}{g'}\\) does not exist, then \\(\\lim\\frac fg\\) does not exist either.","options":["True","False"],"correct":1,"explanation":"False. \\(\\frac{x+\\sin x}{x}\\to1\\) as \\(x\\to\\infty\\), although \\(\\frac{f'}{g'}=1+\\cos x\\) has no limit.","slide":null}],"lang":"en","lesson":{"intro":"Some limits give nonsense like \\(\\frac00\\) when you substitute. Factorising does not always help, especially with \\(e^x\\) or \\(\\ln x\\). L'Hospital's rule turns such limits into a simple derivative exercise.","sections":[{"h":"1. The rule","body":"**L'Hospital's rule.** Suppose that, as \\(x\\to a\\) (\\(a\\) can also be \\(\\pm\\infty\\) or a one-sided limit):\n\n- \\(\\frac{f(x)}{g(x)}\\) has the form \\(\\frac00\\) or \\(\\frac{\\infty}{\\infty}\\),\n- \\(f\\) and \\(g\\) are differentiable near \\(a\\) and \\(g'(x)\\neq0\\) there,\n- the limit \\(\\lim_{x\\to a}\\frac{f'(x)}{g'(x)}\\) exists (finite or \\(\\pm\\infty\\)).\n\nThen\n\\[ \\lim_{x\\to a}\\frac{f(x)}{g(x)}=\\lim_{x\\to a}\\frac{f'(x)}{g'(x)} \\]\nYou differentiate the numerator and the denominator **separately**. This is not the quotient rule!\n\nIf the new limit is again \\(\\frac00\\) or \\(\\frac\\infty\\infty\\), you may use the rule again.","tip":"In the exam, write the form above the equals sign, e.g. \\(\\overset{[0/0]}{=}\\) or \\(\\overset{H}{=}\\). It shows you checked the conditions."},{"h":"2. Form 0/0","body":"Substitute first. If you get \\(\\frac00\\), differentiate top and bottom.\n\nTwo classic results:\n\\[ \\lim_{x\\to0}\\frac{e^x-1}{x}\\overset{[0/0]}{=}\\lim_{x\\to0}\\frac{e^x}{1}=1 \\qquad \\lim_{x\\to1}\\frac{\\ln x}{x-1}\\overset{[0/0]}{=}\\lim_{x\\to1}\\frac{1/x}{1}=1 \\]","example":{"task":"Compute \\(\\lim_{x\\to0}\\frac{e^{2x}-1-2x}{x^2}\\).","steps":["Substitute: \\(\\frac{1-1-0}{0}=\\frac00\\)","Rule: \\(\\lim_{x\\to0}\\frac{2e^{2x}-2}{2x}\\), again \\(\\frac00\\)","Rule again: \\(\\lim_{x\\to0}\\frac{4e^{2x}}{2}=\\frac42=2\\)"],"answer":"2"}},{"h":"3. Form ∞/∞ and the growth order","body":"The rule works the same way for \\(\\frac\\infty\\infty\\).\n\\[ \\lim_{x\\to\\infty}\\frac{\\ln x}{x}\\overset{[\\infty/\\infty]}{=}\\lim_{x\\to\\infty}\\frac{1/x}{1}=0 \\]\n\\[ \\lim_{x\\to\\infty}\\frac{x^2}{e^x}\\overset{[\\infty/\\infty]}{=}\\lim_{x\\to\\infty}\\frac{2x}{e^x}\\overset{[\\infty/\\infty]}{=}\\lim_{x\\to\\infty}\\frac{2}{e^x}=0 \\]\nConclusion to remember (as \\(x\\to\\infty\\)): **logarithms grow slower than powers, and powers grow slower than exponentials** \\(e^x\\).\n\\[ \\ln x \\ll x^n \\ll e^x \\]","tip":"For \\(\\frac{x^n}{e^x}\\) you apply the rule \\(n\\) times; the answer is always 0."},{"h":"4. When the rule does NOT apply","body":"Typical traps:\n\n- **The form is not indeterminate.** \\(\\lim_{x\\to0}\\frac{x+1}{x+2}=\\frac12\\) by substitution. Blind use of the rule gives \\(\\frac11=1\\), which is wrong.\n- **The limit of \\(\\frac{f'}{g'}\\) does not exist.** \\(\\lim_{x\\to\\infty}\\frac{x+\\sin x}{x}=\\lim\\left(1+\\frac{\\sin x}{x}\\right)=1\\), but \\(\\frac{f'}{g'}=1+\\cos x\\) has no limit. The rule says nothing here; use another method.\n- **Using the quotient rule** instead of differentiating numerator and denominator separately.\n- Sometimes the rule makes things worse (e.g. derivatives get longer and longer); then simplify or use a known limit instead.","example":{"task":"Compute \\(\\lim_{x\\to1}\\frac{x^2+1}{x+1}\\).","steps":["Substitute: \\(\\frac{2}{2}=1\\). This is not \\(\\frac00\\), so L'Hospital is not used"],"answer":"1"}},{"h":"5. Forms 0·∞ and ∞−∞","body":"Rewrite the expression as a fraction first.\n\n- \\(0\\cdot\\infty\\): write \\(f\\cdot g=\\frac{f}{1/g}\\) (or \\(\\frac{g}{1/f}\\)) to get \\(\\frac00\\) or \\(\\frac\\infty\\infty\\).\n- \\(\\infty-\\infty\\): bring to a common denominator.","example":{"task":"Compute \\(\\lim_{x\\to0^+}x\\ln x\\) and \\(\\lim_{x\\to0}\\left(\\frac1x-\\frac{1}{e^x-1}\\right)\\).","steps":["\\(0\\cdot(-\\infty)\\): \\(x\\ln x=\\frac{\\ln x}{1/x}\\), form \\(\\frac{-\\infty}{\\infty}\\)","\\(\\lim_{x\\to0^+}\\frac{1/x}{-1/x^2}=\\lim_{x\\to0^+}(-x)=0\\)","\\(\\infty-\\infty\\): common denominator \\(\\frac{e^x-1-x}{x(e^x-1)}\\), form \\(\\frac00\\)","Rule: \\(\\frac{e^x-1}{e^x-1+xe^x}\\), still \\(\\frac00\\)","Rule again: \\(\\frac{e^x}{2e^x+xe^x}\\to\\frac{1}{2}\\)"],"answer":"\\(0\\) and \\(\\frac12\\)"}},{"h":"6. Exponential forms 1^∞, 0^0, ∞^0","body":"For \\(y=f(x)^{g(x)}\\) use the logarithm:\n\\[ f^g=e^{\\,g\\ln f} \\quad\\Rightarrow\\quad \\lim f^g=e^{\\lim g\\ln f} \\]\nThe exponent \\(g\\ln f\\) is a \\(0\\cdot\\infty\\) form, which you already know how to handle. Do not forget to put the result back into \\(e^{(\\dots)}\\) at the end.\n\n**Economics: continuous compounding.** Capital \\(K\\) with yearly rate \\(r\\), compounded \\(n\\) times a year, grows to \\(K(1+\\frac rn)^n\\) after a year. As \\(n\\to\\infty\\) this is a \\(1^\\infty\\) form and\n\\[ \\lim_{n\\to\\infty}\\left(1+\\frac rn\\right)^n=e^{r} \\]","example":{"task":"Compute \\(\\lim_{x\\to0^+}x^x\\) and \\(\\lim_{x\\to\\infty}\\left(1+\\frac3x\\right)^x\\).","steps":["\\(0^0\\): \\(x^x=e^{x\\ln x}\\), and \\(x\\ln x\\to0\\) (Section 5), so the limit is \\(e^0=1\\)","\\(1^\\infty\\): exponent \\(x\\ln\\left(1+\\frac3x\\right)=\\frac{\\ln(1+3/x)}{1/x}\\), form \\(\\frac00\\)","Rule: \\(\\frac{\\frac{1}{1+3/x}\\cdot(-3/x^2)}{-1/x^2}=\\frac{3}{1+3/x}\\to3\\)","So the limit is \\(e^3\\)"],"answer":"\\(1\\) and \\(e^3\\)"},"tip":"\\(1^\\infty\\) is NOT equal to 1. The answer can be any positive number, e.g. \\(e^3\\)."}],"formulas":["\\(\\lim\\frac fg=\\lim\\frac{f'}{g'}\\) for forms \\(\\frac00\\), \\(\\frac\\infty\\infty\\)","\\(\\lim_{x\\to0}\\frac{e^x-1}{x}=1,\\ \\lim_{x\\to1}\\frac{\\ln x}{x-1}=1\\)","\\(\\lim_{x\\to\\infty}\\frac{\\ln x}{x^n}=0,\\ \\lim_{x\\to\\infty}\\frac{x^n}{e^x}=0\\) (\\(n>0\\))","\\(0\\cdot\\infty\\): \\(fg=\\frac{f}{1/g}\\)","\\(\\infty-\\infty\\): common denominator","\\(1^\\infty,0^0,\\infty^0\\): \\(f^g=e^{g\\ln f}\\)","\\(\\lim_{n\\to\\infty}\\left(1+\\frac rn\\right)^n=e^r\\)"],"exercises":[{"task":"Compute \\(\\lim_{x\\to0}\\frac{e^{3x}-1}{x}\\).","hint":"Form \\(\\frac00\\).","answer":"\\(\\lim\\frac{3e^{3x}}{1}=3\\)"},{"task":"Compute \\(\\lim_{x\\to1}\\frac{x^3-1}{\\ln x}\\).","hint":"Form \\(\\frac00\\); \\((\\ln x)'=\\frac1x\\).","answer":"\\(\\lim\\frac{3x^2}{1/x}=\\lim 3x^3=3\\)"},{"task":"Compute \\(\\lim_{x\\to\\infty}\\frac{x^3}{e^x}\\).","hint":"Apply the rule three times.","answer":"\\(\\frac{3x^2}{e^x}\\to\\frac{6x}{e^x}\\to\\frac{6}{e^x}\\to0\\). Answer 0."},{"task":"Compute \\(\\lim_{x\\to0}\\frac{1-\\cos x}{x^2}\\).","hint":"Form \\(\\frac00\\) twice.","answer":"\\(\\frac{\\sin x}{2x}\\to\\frac{\\cos x}{2}\\to\\frac12\\)"},{"task":"Compute \\(\\lim_{x\\to0^+}x^2\\ln x\\).","hint":"Write as \\(\\frac{\\ln x}{x^{-2}}\\).","answer":"\\(\\frac{1/x}{-2x^{-3}}=-\\frac{x^2}{2}\\to0\\). Answer 0."},{"task":"Compute \\(\\lim_{x\\to\\infty}\\left(1-\\frac1x\\right)^{2x}\\).","hint":"\\(1^\\infty\\): exponent \\(2x\\ln(1-\\frac1x)\\).","answer":"Exponent \\(=\\frac{2\\ln(1-1/x)}{1/x}\\to-2\\), so the limit is \\(e^{-2}\\)."},{"task":"Compute \\(\\lim_{x\\to\\infty}(\\ln x)^{1/x}\\).","hint":"\\(\\infty^0\\): exponent \\(\\frac{\\ln(\\ln x)}{x}\\).","answer":"Rule: \\(\\frac{\\frac{1}{x\\ln x}}{1}\\to0\\), so the limit is \\(e^0=1\\)."},{"task":"A deposit of 1000 PLN earns 6% per year. Find its value after one year if interest is compounded \\(n\\) times a year and \\(n\\to\\infty\\).","hint":"\\(\\lim_{n\\to\\infty}(1+\\frac{r}{n})^n=e^r\\).","answer":"\\(1000e^{0.06}\\approx1061.84\\) PLN"}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-09-sketching-graphs', $lekcja${"tldr":"A full investigation of a function (in Polish: 'badanie przebiegu zmienności funkcji') is a classic, high-points exam task. It puts together everything from this unit: domain, intercepts, symmetry, limits and asymptotes, the first derivative (monotonicity and extrema), the second derivative (concavity and inflection points), a table of variation and finally a sketch. The secret is to follow the same fixed list of steps every time. This lesson gives the checklist and two complete worked investigations: a rational function and a function with \\(e^x\\). The same skills are used in economics to understand the shape of cost, revenue and profit curves.","notes":[{"point":"Always follow the same order: domain, intercepts, symmetry, limits and asymptotes, f', f'', table of variation, sketch.","slide":null},{"point":"Symmetry is only possible if the domain is symmetric about 0. Even: f(−x)=f(x); odd: f(−x)=−f(x).","slide":null},{"point":"Compute one-sided limits at every point excluded from the domain; an infinite limit gives a vertical asymptote.","slide":null},{"point":"Oblique asymptote \\(y=ax+b\\): \\(a=\\lim\\frac{f(x)}{x}\\), \\(b=\\lim(f(x)-ax)\\); check \\(+\\infty\\) and \\(-\\infty\\) separately.","slide":null},{"point":"A rational function has an oblique asymptote when the numerator's degree is exactly one higher than the denominator's.","slide":null},{"point":"Extrema come from sign changes of f'; inflection points from sign changes of f'' at points of the domain.","slide":null},{"point":"In the table of variation mark excluded points with ‖ and include limits at the ends of each interval.","slide":null},{"point":"For functions with \\(e^x\\), limits at \\(-\\infty\\) often need L'Hospital, e.g. \\(xe^x=\\frac{x}{e^{-x}}\\to0\\).","slide":null}],"concepts":[{"term":"Investigation of a function","definition":"A complete analysis of a function's properties (domain, limits, monotonicity, concavity, etc.) leading to a sketch of its graph.","pl":"badanie przebiegu zmienności funkcji","slide":null},{"term":"Even function","definition":"A function with f(−x)=f(x); its graph is symmetric about the y-axis.","pl":"funkcja parzysta","slide":null},{"term":"Odd function","definition":"A function with f(−x)=−f(x); its graph is symmetric about the origin.","pl":"funkcja nieparzysta","slide":null},{"term":"Vertical asymptote","definition":"A line x=a near which the function goes to ±∞.","pl":"asymptota pionowa","slide":null},{"term":"Horizontal asymptote","definition":"A line y=b which the graph approaches as x→∞ or x→−∞.","pl":"asymptota pozioma","slide":null},{"term":"Oblique asymptote","definition":"A line y=ax+b (a≠0) which the graph approaches as x→∞ or x→−∞.","pl":"asymptota ukośna","slide":null},{"term":"Table of variation","definition":"A table that collects the signs of f' and f'' and the behaviour of f on each interval.","pl":"tabela przebiegu zmienności (tabela zmienności)","slide":null},{"term":"Range","definition":"The set of all values that the function takes.","pl":"zbiór wartości (przeciwdziedzina)","slide":null}],"flashcards":[{"q":"List the steps of a full investigation of a function.","a":"Domain, intercepts, symmetry, limits and asymptotes, f' (monotonicity, extrema), f'' (concavity, inflection), table, sketch.","slide":null},{"q":"Test for an even function?","a":"\\(f(-x)=f(x)\\) for all x in a symmetric domain.","slide":null},{"q":"Test for an odd function?","a":"\\(f(-x)=-f(x)\\)","slide":null},{"q":"When is x=a a vertical asymptote?","a":"When \\(\\lim_{x\\to a^-}f\\) or \\(\\lim_{x\\to a^+}f\\) is \\(\\pm\\infty\\).","slide":null},{"q":"Formulas for the oblique asymptote y=ax+b?","a":"\\(a=\\lim\\frac{f(x)}{x}\\), \\(b=\\lim(f(x)-ax)\\)","slide":null},{"q":"Oblique asymptote of \\(\\frac{x^2}{x-1}\\)?","a":"\\(y=x+1\\)","slide":null},{"q":"Asymptote of \\(xe^x\\)?","a":"Horizontal \\(y=0\\) at \\(-\\infty\\) only.","slide":null},{"q":"Minimum of \\(xe^x\\)?","a":"\\(\\left(-1,-\\frac1e\\right)\\)","slide":null},{"q":"How do you mark an excluded point in the table of variation?","a":"With a double bar ‖ (and give the one-sided limits).","slide":null},{"q":"Where can inflection points NOT be?","a":"At points outside the domain, even if f'' changes sign there.","slide":null}],"quiz":[{"q":"Which line is a vertical asymptote of \\(f(x)=\\frac{2x+1}{x-3}\\)?","options":["\\(x=-\\frac12\\)","\\(y=2\\)","\\(x=3\\)","\\(x=2\\)"],"correct":2,"explanation":"The denominator is 0 at \\(x=3\\) and the numerator is not, so the limits there are infinite. \\(y=2\\) is the horizontal asymptote.","slide":null},{"q":"The oblique asymptote of \\(f(x)=\\frac{x^2}{x-1}\\) is...","options":["\\(y=x\\)","\\(y=x+1\\)","\\(y=x-1\\)","\\(y=1\\)"],"correct":1,"explanation":"\\(a=\\lim\\frac{x^2}{x(x-1)}=1\\), \\(b=\\lim\\frac{x}{x-1}=1\\).","slide":null},{"q":"\\(f(x)=\\frac{x}{x^2+1}\\) is...","options":["odd","even","neither even nor odd","both even and odd"],"correct":0,"explanation":"\\(f(-x)=\\frac{-x}{x^2+1}=-f(x)\\).","slide":null},{"q":"\\(\\lim_{x\\to-\\infty}xe^x=\\)?","options":["\\(-\\infty\\)","1","\\(+\\infty\\)","0"],"correct":3,"explanation":"Write \\(\\frac{x}{e^{-x}}\\) and use L'Hospital: \\(\\frac{1}{-e^{-x}}\\to0\\). Exponential decay wins over \\(x\\).","slide":null},{"q":"Where is the inflection point of \\(f(x)=xe^x\\)?","options":["\\(x=-1\\)","\\(x=-2\\)","\\(x=0\\)","There is none"],"correct":1,"explanation":"\\(f''(x)=(x+2)e^x\\) changes sign at \\(x=-2\\). \\(x=-1\\) is the minimum, a zero of \\(f'\\).","slide":null},{"q":"In a full investigation, what does a sign change of f' from + to − tell you?","options":["an inflection point","a vertical asymptote","a local minimum","a local maximum"],"correct":3,"explanation":"Increasing then decreasing means a hill: a local maximum.","slide":null},{"q":"\\(f''(x)=\\frac{2}{(x-1)^3}\\) for \\(f(x)=\\frac{x^2}{x-1}\\). How many inflection points does f have?","options":["0","1","2","3"],"correct":0,"explanation":"f'' changes sign only at x=1, which is not in the domain, so there is no inflection point.","slide":null},{"q":"True or false: a graph can never cross its horizontal asymptote.","options":["True","False"],"correct":1,"explanation":"False. An asymptote describes behaviour at the ends; e.g. \\(\\frac{x}{x^2+1}\\) crosses \\(y=0\\) at the origin.","slide":null}],"lang":"en","lesson":{"intro":"This task looks long, but it is very predictable. If you follow the checklist step by step and write clearly, you can collect most of the points even if one calculation goes wrong.","sections":[{"h":"1. The checklist","body":"Follow these steps in this order:\n\n- **Step 1. Domain** \\(D_f\\).\n- **Step 2. Intercepts:** with the y-axis \\((0,f(0))\\) if \\(0\\in D_f\\); with the x-axis: solve \\(f(x)=0\\).\n- **Step 3. Symmetry:** even (\\(f(-x)=f(x)\\), symmetric about the y-axis) or odd (\\(f(-x)=-f(x)\\), symmetric about the origin), or neither.\n- **Step 4. Limits at the ends of the domain and asymptotes** (vertical, horizontal, oblique).\n- **Step 5. First derivative:** monotonicity and local extrema.\n- **Step 6. Second derivative:** convexity/concavity and inflection points.\n- **Step 7. Table of variation:** collect everything in one table.\n- **Step 8. Sketch** the graph; you can also read off the range.","tip":"Even if your derivative is wrong, the examiner gives points for a correct method. Write every step with its heading."},{"h":"2. Domain, intercepts and symmetry","body":"**Domain:** exclude zeros of denominators, negative numbers under even roots, and non-positive arguments of logarithms.\n\n**Intercepts:** \\(f(0)\\) gives the y-intercept; solving \\(f(x)=0\\) gives the zeros.\n\n**Symmetry:** only possible when the domain is symmetric about 0. Compute \\(f(-x)\\) and compare with \\(f(x)\\). For an odd or even function you can analyse only \\(x\\ge0\\) and reflect the picture.","example":{"task":"Check symmetry of \\(f(x)=\\frac{x}{x^2+1}\\).","steps":["\\(D_f=\\mathbb R\\), symmetric about 0","\\(f(-x)=\\frac{-x}{(-x)^2+1}=-\\frac{x}{x^2+1}=-f(x)\\)"],"answer":"f is odd: its graph is symmetric about the origin."}},{"h":"3. Limits and asymptotes","body":"Compute the limits at every 'end' of the domain: at \\(\\pm\\infty\\) and one-sided at every excluded point.\n\n- **Vertical asymptote** \\(x=a\\): at least one one-sided limit at \\(a\\) is \\(\\pm\\infty\\).\n- **Horizontal asymptote** \\(y=b\\) at \\(+\\infty\\) (or \\(-\\infty\\)): \\(\\lim f(x)=b\\) (finite).\n- **Oblique asymptote** \\(y=ax+b\\) at \\(+\\infty\\) (or \\(-\\infty\\)):\n\\[ a=\\lim_{x\\to\\infty}\\frac{f(x)}{x}\\ (a\\neq0),\\qquad b=\\lim_{x\\to\\infty}\\big(f(x)-ax\\big) \\]\nBoth limits must be finite. A horizontal asymptote is the special case \\(a=0\\). Check \\(+\\infty\\) and \\(-\\infty\\) separately when needed (e.g. with \\(e^x\\)).","example":{"task":"Find the asymptotes of \\(f(x)=\\frac{x^2+3}{x+1}\\).","steps":["\\(D_f=\\mathbb R\\setminus\\{-1\\}\\); \\(\\lim_{x\\to-1^-}f(x)=-\\infty\\), \\(\\lim_{x\\to-1^+}f(x)=+\\infty\\): vertical asymptote \\(x=-1\\)","\\(a=\\lim_{x\\to\\pm\\infty}\\frac{x^2+3}{x(x+1)}=1\\)","\\(b=\\lim_{x\\to\\pm\\infty}\\left(\\frac{x^2+3}{x+1}-x\\right)=\\lim\\frac{3-x}{x+1}=-1\\)"],"answer":"vertical \\(x=-1\\), oblique \\(y=x-1\\) (at both ends)"},"tip":"A rational function has an oblique asymptote when the degree of the numerator is exactly one more than the degree of the denominator."},{"h":"4. Derivatives and the table of variation","body":"Compute \\(f'\\), factorise it and make its sign chart (Lesson 6). Then compute \\(f''\\), factorise and make its sign chart (Lesson 7). Then build the **table of variation**:\n\n- top row: the important \\(x\\) values in increasing order (zeros of \\(f'\\) and \\(f''\\), points outside the domain) and the intervals between them;\n- row \\(f'\\): signs + / − / 0;\n- row \\(f''\\): signs + / − / 0;\n- row \\(f\\): arrows (↗ increasing, ↘ decreasing), shape (∪ convex, ∩ concave), values at extrema and inflection points, and limits.\n\nExcluded points get a double bar ‖ in the table. Read the extrema and inflection points directly from the sign changes.","tip":"Factorise f' and f'' as much as possible. Factors like eˣ, (x−1)² or (x²+1)ⁿ are always positive and do not change the sign."},{"h":"5. Worked investigation 1: a rational function","body":"Full investigation of\n\\[ f(x)=\\frac{x^2}{x-1} \\]","example":{"task":"Investigate \\(f(x)=\\frac{x^2}{x-1}\\) and sketch its graph.","steps":["Step 1 (domain): \\(x-1\\neq0\\), so \\(D_f=\\mathbb R\\setminus\\{1\\}\\).","Step 2 (intercepts): \\(f(0)=0\\); \\(f(x)=0\\iff x=0\\). The only intercept is \\((0,0)\\).","Step 3 (symmetry): the domain is not symmetric about 0, so f is neither even nor odd.","Step 4 (limits): \\(\\lim_{x\\to1^-}\\frac{x^2}{x-1}=\\frac{1}{0^-}=-\\infty\\), \\(\\lim_{x\\to1^+}=\\frac{1}{0^+}=+\\infty\\): vertical asymptote \\(x=1\\). \\(\\lim_{x\\to-\\infty}f=-\\infty\\), \\(\\lim_{x\\to+\\infty}f=+\\infty\\).","Oblique asymptote: \\(a=\\lim\\frac{x^2}{x(x-1)}=1\\), \\(b=\\lim\\left(\\frac{x^2}{x-1}-x\\right)=\\lim\\frac{x}{x-1}=1\\). So \\(y=x+1\\) at both \\(\\pm\\infty\\).","Step 5 (f'): \\(f'(x)=\\frac{2x(x-1)-x^2}{(x-1)^2}=\\frac{x(x-2)}{(x-1)^2}\\). Zeros: \\(x=0,\\ x=2\\). Sign = sign of \\(x(x-2)\\): \\(+\\) on \\((-\\infty,0)\\), \\(-\\) on \\((0,1)\\) and \\((1,2)\\), \\(+\\) on \\((2,\\infty)\\).","So f is increasing on \\((-\\infty,0)\\) and \\((2,\\infty)\\), decreasing on \\((0,1)\\) and \\((1,2)\\). Local max \\(f(0)=0\\), local min \\(f(2)=\\frac{4}{1}=4\\).","Step 6 (f''): \\(f''(x)=\\frac{2}{(x-1)^3}\\). Never 0; negative for \\(x<1\\), positive for \\(x>1\\). Concave on \\((-\\infty,1)\\), convex on \\((1,\\infty)\\). No inflection point (1 is not in the domain).","Step 7 (table): \\((-\\infty,0)\\): f' +, f'' −, ↗∩ | \\(x=0\\): max 0 | \\((0,1)\\): f' −, f'' −, ↘∩ | \\(x=1\\): ‖ asymptote | \\((1,2)\\): f' −, f'' +, ↘∪ | \\(x=2\\): min 4 | \\((2,\\infty)\\): f' +, f'' +, ↗∪.","Step 8 (sketch): left branch comes from \\(-\\infty\\) along \\(y=x+1\\), rises to the hill at \\((0,0)\\), then falls to \\(-\\infty\\) at \\(x=1\\). Right branch comes down from \\(+\\infty\\) near \\(x=1\\), reaches the valley \\((2,4)\\), then rises along \\(y=x+1\\).","Range: \\((-\\infty,0]\\cup[4,\\infty)\\)."],"answer":"VA \\(x=1\\), OA \\(y=x+1\\); max \\((0,0)\\), min \\((2,4)\\); concave for \\(x<1\\), convex for \\(x>1\\); no inflection points."}},{"h":"6. Worked investigation 2: a function with e^x","body":"Full investigation of\n\\[ f(x)=xe^x \\]\nHere L'Hospital's rule (Lesson 8) is needed for one limit.","example":{"task":"Investigate \\(f(x)=xe^x\\) and sketch its graph.","steps":["Step 1 (domain): \\(D_f=\\mathbb R\\).","Step 2 (intercepts): \\(f(0)=0\\); \\(xe^x=0\\iff x=0\\) because \\(e^x>0\\). Intercept \\((0,0)\\). Also \\(f<0\\) for \\(x<0\\) and \\(f>0\\) for \\(x>0\\).","Step 3 (symmetry): \\(f(-x)=-xe^{-x}\\), which is neither \\(f(x)\\) nor \\(-f(x)\\): no symmetry.","Step 4 (limits): \\(\\lim_{x\\to+\\infty}xe^x=+\\infty\\) and \\(\\frac{f(x)}{x}=e^x\\to\\infty\\), so no asymptote at \\(+\\infty\\).","At \\(-\\infty\\): form \\(-\\infty\\cdot0\\). Write \\(xe^x=\\frac{x}{e^{-x}}\\), form \\(\\frac{-\\infty}{\\infty}\\); L'Hospital: \\(\\frac{1}{-e^{-x}}=-e^{x}\\to0\\). Horizontal asymptote \\(y=0\\) at \\(-\\infty\\) (the graph approaches it from below).","Step 5 (f'): \\(f'(x)=e^x+xe^x=(x+1)e^x\\). Zero at \\(x=-1\\); \\(-\\) for \\(x<-1\\), \\(+\\) for \\(x>-1\\). Decreasing on \\((-\\infty,-1)\\), increasing on \\((-1,\\infty)\\). Local (and global) min \\(f(-1)=-\\frac1e\\approx-0.37\\).","Step 6 (f''): \\(f''(x)=e^x+(x+1)e^x=(x+2)e^x\\). Zero at \\(x=-2\\); \\(-\\) for \\(x<-2\\), \\(+\\) for \\(x>-2\\). Concave on \\((-\\infty,-2)\\), convex on \\((-2,\\infty)\\). Inflection point \\(\\left(-2,-\\frac{2}{e^2}\\right)\\approx(-2,-0.27)\\).","Step 7 (table): \\((-\\infty,-2)\\): f' −, f'' −, ↘∩ | \\(x=-2\\): inflection \\(-0.27\\) | \\((-2,-1)\\): f' −, f'' +, ↘∪ | \\(x=-1\\): min \\(-0.37\\) | \\((-1,\\infty)\\): f' +, f'' +, ↗∪.","Step 8 (sketch): far left the graph lies just below the x-axis, bends down, changes bending at \\((-2,-0.27)\\), reaches its lowest point \\((-1,-0.37)\\), then rises through \\((0,0)\\) and grows very fast.","Range: \\(\\left[-\\frac1e,\\infty\\right)\\)."],"answer":"HA \\(y=0\\) at \\(-\\infty\\); min \\(\\left(-1,-\\frac1e\\right)\\); inflection \\(\\left(-2,-\\frac2{e^2}\\right)\\); concave on \\((-\\infty,-2)\\), convex on \\((-2,\\infty)\\)."},"tip":"With \\(e^x\\), always check \\(+\\infty\\) and \\(-\\infty\\) separately: the behaviour at the two ends is completely different."}],"formulas":["Even: \\(f(-x)=f(x)\\); odd: \\(f(-x)=-f(x)\\)","Vertical asymptote \\(x=a\\): \\(\\lim_{x\\to a^\\pm}f(x)=\\pm\\infty\\)","Horizontal asymptote \\(y=b\\): \\(\\lim_{x\\to\\pm\\infty}f(x)=b\\)","Oblique asymptote \\(y=ax+b\\): \\(a=\\lim\\frac{f(x)}{x},\\ b=\\lim\\big(f(x)-ax\\big)\\)","\\(f'>0\\) ↗, \\(f'<0\\) ↘; sign change of \\(f'\\) gives an extremum","\\(f''>0\\) ∪, \\(f''<0\\) ∩; sign change of \\(f''\\) (in \\(D_f\\)) gives an inflection point","Order: domain → intercepts → symmetry → limits/asymptotes → f' → f'' → table → sketch"],"exercises":[{"task":"Find the domain, intercepts and asymptotes of \\(f(x)=\\frac{2x+1}{x-3}\\).","hint":"Degrees of numerator and denominator are equal.","answer":"\\(D_f=\\mathbb R\\setminus\\{3\\}\\); intercepts \\((0,-\\frac13)\\), \\((-\\frac12,0)\\); VA \\(x=3\\) (\\(-\\infty\\) from the left, \\(+\\infty\\) from the right); HA \\(y=2\\)."},{"task":"Is \\(f(x)=\\frac{x^2}{x^2+4}\\) even, odd or neither? And \\(g(x)=x^3-3x\\)?","hint":"Compute \\(f(-x)\\) and \\(g(-x)\\).","answer":"\\(f(-x)=f(x)\\): f is even. \\(g(-x)=-x^3+3x=-g(x)\\): g is odd."},{"task":"Investigate \\(f(x)=x^3-3x\\).","hint":"\\(f'=3(x-1)(x+1)\\), \\(f''=6x\\).","answer":"\\(D=\\mathbb R\\), odd; zeros \\(0,\\pm\\sqrt3\\); no asymptotes, limits \\(\\mp\\infty\\) at \\(\\mp\\infty\\). Increasing on \\((-\\infty,-1)\\) and \\((1,\\infty)\\), decreasing on \\((-1,1)\\); max \\((-1,2)\\), min \\((1,-2)\\). Concave on \\((-\\infty,0)\\), convex on \\((0,\\infty)\\); inflection \\((0,0)\\)."},{"task":"Investigate \\(f(x)=\\frac{x}{x^2+1}\\).","hint":"\\(f'=\\frac{1-x^2}{(x^2+1)^2}\\), \\(f''=\\frac{2x(x^2-3)}{(x^2+1)^3}\\).","answer":"\\(D=\\mathbb R\\), odd, intercept \\((0,0)\\); HA \\(y=0\\) at \\(\\pm\\infty\\). Decreasing on \\((-\\infty,-1)\\) and \\((1,\\infty)\\), increasing on \\((-1,1)\\); min \\((-1,-\\frac12)\\), max \\((1,\\frac12)\\). Concave on \\((-\\infty,-\\sqrt3)\\) and \\((0,\\sqrt3)\\), convex on \\((-\\sqrt3,0)\\) and \\((\\sqrt3,\\infty)\\); inflection points \\((-\\sqrt3,-\\frac{\\sqrt3}4)\\), \\((0,0)\\), \\((\\sqrt3,\\frac{\\sqrt3}4)\\)."},{"task":"Investigate \\(f(x)=\\frac{e^x}{x}\\).","hint":"\\(f'=\\frac{(x-1)e^x}{x^2}\\), \\(f''=\\frac{(x^2-2x+2)e^x}{x^3}\\); \\(x^2-2x+2>0\\) always.","answer":"\\(D=\\mathbb R\\setminus\\{0\\}\\), no intercepts, no symmetry. VA \\(x=0\\) (\\(-\\infty\\) from the left, \\(+\\infty\\) from the right); HA \\(y=0\\) at \\(-\\infty\\); at \\(+\\infty\\) \\(f\\to\\infty\\), no oblique asymptote (\\(f/x\\to\\infty\\)). Decreasing on \\((-\\infty,0)\\) and \\((0,1)\\), increasing on \\((1,\\infty)\\); min \\((1,e)\\). Concave for \\(x<0\\), convex for \\(x>0\\); no inflection point."},{"task":"Find the oblique asymptote of \\(f(x)=\\frac{x^2}{x-1}\\) and say whether the graph lies above or below it for large \\(x\\).","hint":"\\(f(x)-(x+1)=\\frac{1}{x-1}\\).","answer":"\\(y=x+1\\). Since \\(f(x)-(x+1)=\\frac{1}{x-1}>0\\) for \\(x>1\\), the graph lies above the asymptote as \\(x\\to+\\infty\\) (and below it as \\(x\\to-\\infty\\))."}]}}$lekcja$::jsonb)
