insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-10-partial-derivatives', $lekcja${"tldr":"In economics one quantity usually depends on several others: output depends on capital and labour, profit depends on the amounts of two goods. A function of two variables \\(z = f(x,y)\\) describes this. We learn how to find its domain and draw level curves, and how to differentiate it with respect to one variable while the other stays fixed (partial derivatives). Second-order partials form the Hessian matrix, and Schwarz's theorem tells us the mixed partials are equal. The total differential lets us approximate small changes. In economics, partial derivatives of a Cobb-Douglas production function are the marginal products of capital and labour.","notes":[{"point":"A partial derivative changes one variable and keeps all others constant: for \\(f_x\\) treat \\(y\\) like a number.","slide":null},{"point":"The domain of a function of two variables is a region in the plane; use the usual rules (root ≥ 0, log argument > 0, denominator ≠ 0).","slide":null},{"point":"A level curve is \\(f(x,y) = c\\). Isoquants (constant output) and indifference curves (constant utility) are level curves.","slide":null},{"point":"Schwarz's theorem: for nice functions the mixed partials are equal, \\(f_{xy} = f_{yx}\\); the Hessian is symmetric.","slide":null},{"point":"The Hessian matrix contains the four second-order partials and is used to classify extrema.","slide":null},{"point":"Total differential \\(df = f_x\\,dx + f_y\\,dy\\) approximates the change of \\(f\\) for small changes \\(dx, dy\\).","slide":null},{"point":"For \\(Q = AK^{\\alpha}L^{\\beta}\\): \\(MP_K = \\partial Q/\\partial K\\), \\(MP_L = \\partial Q/\\partial L\\); always interpret as 'extra output from one more unit, the other input fixed'.","slide":null},{"point":"Cobb-Douglas with \\(\\alpha + \\beta = 1\\) has constant returns to scale.","slide":null}],"concepts":[{"term":"Function of two variables","definition":"A rule \\(z = f(x,y)\\) that gives one number for each pair \\((x,y)\\) in its domain.","pl":"funkcja dwóch zmiennych","slide":null},{"term":"Domain","definition":"The set of points (x, y) for which the formula of the function makes sense.","pl":"dziedzina","slide":null},{"term":"Level curve","definition":"The set of points where the function takes a fixed value: \\(f(x,y) = c\\).","pl":"poziomica (linia poziomu)","slide":null},{"term":"Partial derivative","definition":"The derivative with respect to one variable while all other variables are held constant.","pl":"pochodna cząstkowa","slide":null},{"term":"Mixed partial derivative","definition":"A second-order partial taken with respect to two different variables, e.g. \\(f_{xy}\\).","pl":"pochodna mieszana","slide":null},{"term":"Hessian matrix","definition":"The square matrix of all second-order partial derivatives of a function.","pl":"macierz Hessego (hesjan)","slide":null},{"term":"Gradient","definition":"The vector of first-order partials \\(\\nabla f = (f_x, f_y)\\).","pl":"gradient","slide":null},{"term":"Total differential","definition":"\\(df = f_x\\,dx + f_y\\,dy\\); the approximate change of \\(f\\) when all variables change slightly.","pl":"różniczka zupełna","slide":null},{"term":"Marginal product","definition":"The partial derivative of a production function with respect to one input: extra output from one more unit of that input.","pl":"produkt krańcowy (produktywność krańcowa)","slide":null},{"term":"Cobb-Douglas function","definition":"A production function of the form \\(Q = AK^{\\alpha}L^{\\beta}\\).","pl":"funkcja Cobba-Douglasa","slide":null}],"flashcards":[{"q":"How do you compute \\(f_x\\)?","a":"Differentiate with respect to \\(x\\), treating \\(y\\) as a constant.","slide":null},{"q":"What is \\(\\frac{\\partial}{\\partial x}(7y^2)\\)?","a":"0 (no x in the term, so it is a constant).","slide":null},{"q":"What is \\(\\frac{\\partial}{\\partial y}(5xy)\\)?","a":"\\(5x\\)","slide":null},{"q":"What does Schwarz's theorem say?","a":"For nice (continuous second partials) functions \\(f_{xy} = f_{yx}\\).","slide":null},{"q":"What is in the Hessian matrix?","a":"The second partials: \\(\\begin{bmatrix} f_{xx} & f_{xy} \\\\ f_{yx} & f_{yy} \\end{bmatrix}\\).","slide":null},{"q":"Formula of the total differential?","a":"\\(df = f_x\\,dx + f_y\\,dy\\)","slide":null},{"q":"What is a level curve?","a":"The set of points with \\(f(x,y) = c\\) for a fixed \\(c\\).","slide":null},{"q":"What is an isoquant?","a":"A level curve of a production function: all (K, L) giving the same output.","slide":null},{"q":"\\(MP_L\\) for \\(Q = AK^{\\alpha}L^{\\beta}\\)?","a":"\\(A\\beta K^{\\alpha}L^{\\beta-1}\\)","slide":null},{"q":"Domain condition for ln(g(x,y))?","a":"\\(g(x,y) > 0\\)","slide":null}],"quiz":[{"q":"For \\(f(x,y) = x^2y^3\\), what is \\(f_x\\)?","options":["\\(2xy^3\\)","\\(3x^2y^2\\)","\\(6xy^2\\)","\\(2xy^3 + 3x^2y^2\\)"],"correct":0,"explanation":"Treat \\(y^3\\) as a constant: \\(\\frac{\\partial}{\\partial x}x^2 = 2x\\), so \\(f_x = 2xy^3\\).","slide":null},{"q":"For \\(f(x,y) = 4x + xy - 3y^2\\), what is \\(f_y\\)?","options":["\\(4 + y\\)","\\(x - 6y\\)","\\(4 + x - 6y\\)","\\(-6y\\)"],"correct":1,"explanation":"\\(4x\\) is constant w.r.t. \\(y\\) (derivative 0), \\(xy \\to x\\), \\(-3y^2 \\to -6y\\).","slide":null},{"q":"What is the domain of \\(f(x,y) = \\sqrt{y - x^2}\\)?","options":["\\(y > x^2\\)","\\(y \\le x^2\\)","\\(y \\ge x^2\\)","all of \\(\\mathbb{R}^2\\)"],"correct":2,"explanation":"The expression under an even root must be non-negative: \\(y - x^2 \\ge 0\\), i.e. on or above the parabola.","slide":null},{"q":"For \\(f(x,y) = x^3y^2\\), what is \\(f_{xy}\\)?","options":["\\(6xy^2\\)","\\(2x^3\\)","\\(6x^2\\)","\\(6x^2y\\)"],"correct":3,"explanation":"\\(f_x = 3x^2y^2\\); differentiating w.r.t. \\(y\\) gives \\(6x^2y\\).","slide":null},{"q":"Schwarz's theorem says that (for nice functions):","options":["\\(f_{xx} = f_{yy}\\)","\\(f_{xy} = f_{yx}\\)","\\(f_x = f_y\\)","\\(f_{xy} = 0\\)"],"correct":1,"explanation":"The order of differentiation in the mixed partials does not matter, so the Hessian is symmetric.","slide":null},{"q":"\\(f(2,3) = 12\\), \\(f_x(2,3) = 12\\), \\(f_y(2,3) = 4\\). Approximate \\(f(2.1,\\,3.1)\\).","options":["\\(13.6\\)","\\(12.16\\)","\\(28\\)","\\(12.8\\)"],"correct":0,"explanation":"\\(df = 12\\cdot0.1 + 4\\cdot0.1 = 1.6\\), so \\(f \\approx 12 + 1.6 = 13.6\\).","slide":null},{"q":"For \\(Q = 10K^{0.5}L^{0.5}\\) with \\(K = 16\\), \\(L = 25\\), what is \\(MP_L\\)?","options":["\\(6.25\\)","\\(200\\)","\\(4\\)","\\(5\\)"],"correct":2,"explanation":"\\(MP_L = 5\\sqrt{K}/\\sqrt{L} = 5\\cdot4/5 = 4\\). (6.25 is \\(MP_K\\).)","slide":null},{"q":"Level curves of a utility function are called:","options":["isoquants","budget lines","gradients","indifference curves"],"correct":3,"explanation":"All bundles on one indifference curve give the same utility; isoquants are level curves of a production function.","slide":null}],"lang":"en","lesson":{"intro":"How much more will a factory produce if it hires one more worker but keeps the same machines? To answer this, we need a function of two variables and a derivative that changes only one input at a time. This lesson gives you exactly that tool.","sections":[{"h":"Functions of two variables, domain and level curves","body":"A function of two variables gives one number \\(z\\) for each pair \\((x,y)\\):\n\\[ z = f(x,y). \\]\nExample: \\(f(x,y) = x^2 + 3y\\). Then \\(f(1,2) = 1 + 6 = 7\\). With more variables we write \\(f(x_1, x_2, \\dots, x_n)\\) - the ideas are the same.\n\nThe domain is the set of all points \\((x,y)\\) in the plane for which the formula makes sense. Use the same rules as for one variable:\n- under an even root: expression \\(\\ge 0\\)\n- inside a logarithm: expression \\(> 0\\)\n- in a denominator: expression \\(\\ne 0\\)\n\nThe domain is a region in the plane, so we describe it with an inequality and often sketch it.\n\nA level curve (contour line) is the set of points where the function has a constant value \\(c\\): \\(f(x,y) = c\\). It works like the lines on a hiking map. In economics, level curves of a production function are called isoquants (same output), and level curves of a utility function are indifference curves (same satisfaction).","example":{"task":"Find the domain of \\(f(x,y) = \\ln(x + y - 2)\\) and describe the level curves of \\(g(x,y) = x^2 + y^2\\).","steps":["For the logarithm we need \\(x + y - 2 > 0\\), so \\(y > 2 - x\\).","The domain is the half-plane strictly above the line \\(y = 2 - x\\) (the line itself is not included).","Level curves of \\(g\\): \\(x^2 + y^2 = c\\). For \\(c > 0\\) this is a circle centred at \\((0,0)\\) with radius \\(\\sqrt{c}\\); for \\(c = 0\\) it is just the point \\((0,0)\\); for \\(c < 0\\) there are no points."],"answer":"Domain: \\(\\{(x,y): y > 2 - x\\}\\). Level curves of \\(g\\): circles \\(x^2 + y^2 = c\\) with radius \\(\\sqrt{c}\\)."},"tip":"When you sketch a domain, draw the boundary line dashed if it is NOT included (strict inequality) and solid if it is included."},{"h":"First-order partial derivatives","body":"The partial derivative with respect to \\(x\\) tells us how fast \\(f\\) changes when only \\(x\\) changes and \\(y\\) is kept constant:\n\\[ f_x = \\frac{\\partial f}{\\partial x}, \\qquad f_y = \\frac{\\partial f}{\\partial y}. \\]\nHow to compute it in practice:\n- for \\(f_x\\): treat \\(y\\) as a number (a constant) and differentiate with respect to \\(x\\) using the normal rules\n- for \\(f_y\\): treat \\(x\\) as a number and differentiate with respect to \\(y\\)\n\nSo \\(\\frac{\\partial}{\\partial x}(5y) = 0\\) (a constant), but \\(\\frac{\\partial}{\\partial x}(5xy) = 5y\\) (a constant times \\(x\\)).\n\nThe vector of both first partials is called the gradient: \\(\\nabla f = (f_x, f_y)\\). We will use it in the next lesson to find extrema.","example":{"task":"Find \\(f_x\\) and \\(f_y\\) for \\(f(x,y) = x^3y^2 + 4xy - 5y\\), and evaluate them at \\((1,2)\\).","steps":["\\(f_x\\): \\(y\\) is a constant. \\(f_x = 3x^2y^2 + 4y - 0 = 3x^2y^2 + 4y\\).","\\(f_y\\): \\(x\\) is a constant. \\(f_y = 2x^3y + 4x - 5\\).","At \\((1,2)\\): \\(f_x(1,2) = 3\\cdot1\\cdot4 + 8 = 20\\).","\\(f_y(1,2) = 2\\cdot1\\cdot2 + 4 - 5 = 3\\)."],"answer":"\\(f_x = 3x^2y^2 + 4y\\), \\(f_y = 2x^3y + 4x - 5\\); \\(f_x(1,2) = 20\\), \\(f_y(1,2) = 3\\)."},"tip":"Most mistakes come from forgetting that a term with no \\(x\\) has \\(f_x = 0\\), or from 'differentiating' the constant variable. Underline the variable you are differentiating with respect to."},{"h":"Second-order partial derivatives, the Hessian and Schwarz's theorem","body":"We can differentiate the first partials again. There are four second-order partials:\n\\[ f_{xx} = \\frac{\\partial^2 f}{\\partial x^2},\\quad f_{yy} = \\frac{\\partial^2 f}{\\partial y^2},\\quad f_{xy} = \\frac{\\partial^2 f}{\\partial y\\,\\partial x},\\quad f_{yx} = \\frac{\\partial^2 f}{\\partial x\\,\\partial y}. \\]\n\\(f_{xy}\\) means: first differentiate with respect to \\(x\\), then with respect to \\(y\\). These are the mixed partials.\n\nSchwarz's theorem: if the second partials are continuous (true for all 'nice' functions in this course), then\n\\[ f_{xy} = f_{yx}. \\]\nSo you only need to compute one mixed partial - and computing both is a good check.\n\nWe collect the second partials in the Hessian matrix:\n\\[ H(x,y) = \\begin{bmatrix} f_{xx} & f_{xy} \\\\ f_{yx} & f_{yy} \\end{bmatrix}. \\]\nBy Schwarz's theorem it is symmetric. The Hessian is the key tool for the extremum test in the next lesson.","example":{"task":"Find all second-order partials and the Hessian of \\(f(x,y) = x^3y + 2xy^2\\).","steps":["First partials: \\(f_x = 3x^2y + 2y^2\\), \\(f_y = x^3 + 4xy\\).","\\(f_{xx} = 6xy\\), \\(f_{yy} = 4x\\).","\\(f_{xy} = \\frac{\\partial}{\\partial y}(3x^2y + 2y^2) = 3x^2 + 4y\\).","\\(f_{yx} = \\frac{\\partial}{\\partial x}(x^3 + 4xy) = 3x^2 + 4y\\) - the same, as Schwarz's theorem says."],"answer":"\\(H = \\begin{bmatrix} 6xy & 3x^2 + 4y \\\\ 3x^2 + 4y & 4x \\end{bmatrix}\\)"},"tip":"If your two mixed partials are different, you made an arithmetic mistake. Go back and check."},{"h":"Total differential and approximation","body":"If both \\(x\\) and \\(y\\) change a little (by \\(dx\\) and \\(dy\\)), the change of the function is approximately the total differential:\n\\[ df = f_x\\,dx + f_y\\,dy. \\]\nEach part is 'rate of change' times 'size of change'. This gives a quick approximation:\n\\[ f(x_0 + dx,\\, y_0 + dy) \\approx f(x_0,y_0) + f_x(x_0,y_0)\\,dx + f_y(x_0,y_0)\\,dy. \\]\nThe smaller \\(dx\\) and \\(dy\\), the better the approximation.","example":{"task":"Let \\(f(x,y) = x^2y\\). Use the total differential to approximate \\(f(2.1,\\; 2.8)\\).","steps":["Base point \\((2,3)\\): \\(f(2,3) = 4\\cdot3 = 12\\). Changes: \\(dx = 0.1\\), \\(dy = -0.2\\).","\\(f_x = 2xy\\), so \\(f_x(2,3) = 12\\). \\(f_y = x^2\\), so \\(f_y(2,3) = 4\\).","\\(df = 12\\cdot0.1 + 4\\cdot(-0.2) = 1.2 - 0.8 = 0.4\\).","\\(f(2.1, 2.8) \\approx 12 + 0.4 = 12.4\\). (The exact value is \\(12.348\\) - very close.)"],"answer":"\\(f(2.1, 2.8) \\approx 12.4\\)"},"tip":"Watch the sign of \\(dy\\): if \\(y\\) goes down (3 to 2.8), \\(dy\\) is negative."},{"h":"Economics: Cobb-Douglas production and marginal products","body":"The Cobb-Douglas production function gives output \\(Q\\) from capital \\(K\\) and labour \\(L\\):\n\\[ Q = A\\,K^{\\alpha}L^{\\beta}, \\qquad A > 0,\\; \\alpha, \\beta > 0. \\]\nIts partial derivatives have names:\n- marginal product of capital: \\(MP_K = \\frac{\\partial Q}{\\partial K} = A\\alpha K^{\\alpha-1}L^{\\beta}\\) - extra output from one more unit of capital (labour fixed)\n- marginal product of labour: \\(MP_L = \\frac{\\partial Q}{\\partial L} = A\\beta K^{\\alpha}L^{\\beta-1}\\) - extra output from one more worker (capital fixed)\n\nIf \\(\\alpha + \\beta = 1\\) we have constant returns to scale: doubling both inputs doubles output. If \\(\\alpha, \\beta < 1\\), each marginal product falls as you add more of that input (diminishing returns) - you can see it from \\(\\frac{\\partial^2 Q}{\\partial L^2} < 0\\).","example":{"task":"A firm has \\(Q = 10K^{0.5}L^{0.5}\\), with \\(K = 16\\) and \\(L = 25\\). Find output and both marginal products.","steps":["\\(Q = 10\\cdot\\sqrt{16}\\cdot\\sqrt{25} = 10\\cdot4\\cdot5 = 200\\).","\\(MP_K = 10\\cdot0.5\\,K^{-0.5}L^{0.5} = 5\\sqrt{L}/\\sqrt{K} = 5\\cdot5/4 = 6.25\\).","\\(MP_L = 5\\,K^{0.5}L^{-0.5} = 5\\sqrt{K}/\\sqrt{L} = 5\\cdot4/5 = 4\\).","Interpretation: one more unit of capital adds about 6.25 units of output; one more worker adds about 4 units."],"answer":"\\(Q = 200\\), \\(MP_K = 6.25\\), \\(MP_L = 4\\)."},"tip":"Always add the interpretation in words on the exam: 'if L increases by 1 unit (K constant), Q increases by about ... units'."}],"formulas":["\\(f_x\\): differentiate w.r.t. \\(x\\), treat \\(y\\) as a constant; \\(f_y\\): the other way round","Gradient: \\(\\nabla f = (f_x, f_y)\\)","Schwarz: \\(f_{xy} = f_{yx}\\)","Hessian: \\(H = \\begin{bmatrix} f_{xx} & f_{xy} \\\\ f_{yx} & f_{yy} \\end{bmatrix}\\)","Total differential: \\(df = f_x\\,dx + f_y\\,dy\\)","Approximation: \\(f(x_0+dx, y_0+dy) \\approx f(x_0,y_0) + f_x\\,dx + f_y\\,dy\\)","Cobb-Douglas: \\(Q = AK^{\\alpha}L^{\\beta}\\), \\(MP_K = A\\alpha K^{\\alpha-1}L^{\\beta}\\), \\(MP_L = A\\beta K^{\\alpha}L^{\\beta-1}\\)","Level curve: \\(f(x,y) = c\\) (isoquant, indifference curve)"],"exercises":[{"task":"Find \\(f_x\\) and \\(f_y\\) for \\(f(x,y) = 3x^2 - 2xy + y^3\\) and evaluate them at \\((1,2)\\).","hint":"For \\(f_x\\) the term \\(y^3\\) is a constant.","answer":"\\(f_x = 6x - 2y\\), \\(f_y = -2x + 3y^2\\); \\(f_x(1,2) = 2\\), \\(f_y(1,2) = 10\\)."},{"task":"Find and describe the domain of \\(f(x,y) = \\sqrt{4 - x^2 - y^2}\\).","hint":"The expression under the square root must be \\(\\ge 0\\).","answer":"\\(x^2 + y^2 \\le 4\\): the closed disc with centre \\((0,0)\\) and radius 2 (boundary circle included)."},{"task":"Find \\(f_x\\) and \\(f_y\\) for \\(f(x,y) = \\ln(x^2 + y)\\).","hint":"Chain rule: \\((\\ln u)' = u'/u\\).","answer":"\\(f_x = \\dfrac{2x}{x^2 + y}\\), \\(f_y = \\dfrac{1}{x^2 + y}\\)."},{"task":"Find all second-order partials of \\(f(x,y) = x e^{y}\\) and check Schwarz's theorem.","hint":"\\(f_x = e^y\\), \\(f_y = xe^y\\).","answer":"\\(f_{xx} = 0\\), \\(f_{yy} = xe^y\\), \\(f_{xy} = f_{yx} = e^y\\)."},{"task":"Write the Hessian of \\(f(x,y) = x^2y + y^3\\) at the point \\((1,1)\\).","hint":"\\(f_{xx} = 2y\\), \\(f_{xy} = 2x\\), \\(f_{yy} = 6y\\).","answer":"\\(H(1,1) = \\begin{bmatrix} 2 & 2 \\\\ 2 & 6 \\end{bmatrix}\\)"},{"task":"For \\(f(x,y) = xy^2\\), use the total differential to approximate the change of \\(f\\) when \\((x,y)\\) moves from \\((3,1)\\) to \\((3.1,\\,1.05)\\).","hint":"\\(dx = 0.1\\), \\(dy = 0.05\\); \\(f_x = y^2\\), \\(f_y = 2xy\\).","answer":"\\(df = 1\\cdot0.1 + 6\\cdot0.05 = 0.4\\), so \\(f \\approx 3 + 0.4 = 3.4\\) (exact: about 3.418)."},{"task":"A firm produces \\(Q = 20K^{0.25}L^{0.75}\\). For \\(K = 16\\) and \\(L = 81\\), find \\(Q\\), \\(MP_K\\) and \\(MP_L\\), and interpret \\(MP_L\\).","hint":"\\(16^{0.25} = 2\\), \\(81^{0.75} = 27\\), \\(81^{0.25} = 3\\), \\(16^{0.75} = 8\\).","answer":"\\(Q = 20\\cdot2\\cdot27 = 1080\\); \\(MP_K = 5K^{-0.75}L^{0.75} = 5\\cdot27/8 = 16.875\\); \\(MP_L = 15K^{0.25}L^{-0.25} = 15\\cdot2/3 = 10\\). One more worker (capital fixed) raises output by about 10 units."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-11-extrema-two-variables', $lekcja${"tldr":"This lesson shows how to find local maxima and minima of \\(f(x,y)\\). First we find stationary points, where both first partial derivatives are zero. Then we classify each point with the second-order test, using the Hessian determinant \\(W = f_{xx}f_{yy} - f_{xy}^2\\). If \\(W > 0\\) there is an extremum (minimum if \\(f_{xx} > 0\\), maximum if \\(f_{xx} < 0\\)); if \\(W < 0\\) there is a saddle point. The classic economics use: a firm producing two goods chooses both quantities to maximise profit.","notes":[{"point":"Necessary condition for an extremum: \\(f_x = 0\\) and \\(f_y = 0\\) (stationary point).","slide":null},{"point":"A stationary point can be a maximum, a minimum or a saddle point - you must classify it.","slide":null},{"point":"Hessian determinant: \\(W = f_{xx}f_{yy} - f_{xy}^2\\), computed at each stationary point separately.","slide":null},{"point":"\\(W > 0\\): extremum; the sign of \\(f_{xx}\\) decides (positive = minimum, negative = maximum).","slide":null},{"point":"\\(W < 0\\): saddle point, no extremum.","slide":null},{"point":"\\(W = 0\\): the second-order test does not decide.","slide":null},{"point":"When an equation like x² = 1 gives two solutions, you get two stationary points - check every one.","slide":null},{"point":"Profit of a two-good firm: \\(\\Pi = p_1x + p_2y - C(x,y)\\); maximise it and give the answer in economic terms.","slide":null}],"concepts":[{"term":"Local maximum","definition":"A point where the function value is at least as large as at all nearby points.","pl":"maksimum lokalne","slide":null},{"term":"Local minimum","definition":"A point where the function value is at most as large as at all nearby points.","pl":"minimum lokalne","slide":null},{"term":"Stationary point","definition":"A point where all first-order partial derivatives are zero.","pl":"punkt stacjonarny","slide":null},{"term":"Necessary condition","definition":"A condition every extremum must satisfy (here \\(\\nabla f = 0\\)), but which alone does not guarantee an extremum.","pl":"warunek konieczny","slide":null},{"term":"Sufficient condition","definition":"A condition that guarantees an extremum (here W > 0 at a stationary point).","pl":"warunek wystarczający","slide":null},{"term":"Saddle point","definition":"A stationary point that is not an extremum: the function rises in some directions and falls in others.","pl":"punkt siodłowy","slide":null},{"term":"Hessian determinant","definition":"\\(W = f_{xx}f_{yy} - f_{xy}^2\\), the determinant of the Hessian matrix.","pl":"wyznacznik hesjanu (wyznacznik macierzy Hessego)","slide":null},{"term":"Profit function","definition":"Revenue minus cost; for two goods a function of both quantities.","pl":"funkcja zysku","slide":null}],"flashcards":[{"q":"How do you find stationary points of f(x, y)?","a":"Solve \\(f_x = 0\\) and \\(f_y = 0\\) together.","slide":null},{"q":"Formula for W?","a":"\\(W = f_{xx}f_{yy} - f_{xy}^2\\)","slide":null},{"q":"\\(W > 0\\) and \\(f_{xx} > 0\\) means?","a":"Local minimum.","slide":null},{"q":"\\(W > 0\\) and \\(f_{xx} < 0\\) means?","a":"Local maximum.","slide":null},{"q":"\\(W < 0\\) means?","a":"Saddle point - no extremum.","slide":null},{"q":"\\(W = 0\\) means?","a":"The test is inconclusive.","slide":null},{"q":"What is a saddle point?","a":"A stationary point where f goes up in one direction and down in another; not an extremum.","slide":null},{"q":"Is every stationary point an extremum?","a":"No - it can be a saddle point.","slide":null},{"q":"Profit of a firm producing two goods at prices p1, p2?","a":"\\(\\Pi = p_1x + p_2y - C(x,y)\\)","slide":null},{"q":"Economic meaning of \\(\\Pi_x = 0\\)?","a":"For good 1, marginal revenue equals marginal cost.","slide":null}],"quiz":[{"q":"What are the stationary points of \\(f(x,y) = x^2 + y^2 - 4x + 6y + 1\\)?","options":["\\((-2,3)\\)","\\((4,-6)\\)","\\((2,-3)\\)","\\((2,3)\\)"],"correct":2,"explanation":"\\(f_x = 2x - 4 = 0 \\Rightarrow x = 2\\); \\(f_y = 2y + 6 = 0 \\Rightarrow y = -3\\).","slide":null},{"q":"At a stationary point \\(f_{xx} = 2\\), \\(f_{yy} = 3\\), \\(f_{xy} = 4\\). The point is:","options":["a local minimum","a saddle point","a local maximum","impossible to classify"],"correct":1,"explanation":"\\(W = 2\\cdot3 - 16 = -10 < 0\\), so it is a saddle point even though \\(f_{xx} > 0\\).","slide":null},{"q":"At a stationary point \\(f_{xx} = -4\\), \\(f_{yy} = -2\\), \\(f_{xy} = 1\\). The point is:","options":["a local maximum","a local minimum","a saddle point","the test is inconclusive"],"correct":0,"explanation":"\\(W = 8 - 1 = 7 > 0\\) and \\(f_{xx} < 0\\), so a local maximum.","slide":null},{"q":"Which is the correct formula for the Hessian determinant \\(W\\)?","options":["\\(f_{xx}f_{yy} + f_{xy}^2\\)","\\(f_{xx} + f_{yy}\\)","\\(f_{xy}^2 - f_{xx}f_{yy}\\)","\\(f_{xx}f_{yy} - f_{xy}^2\\)"],"correct":3,"explanation":"\\(W\\) is the determinant of \\(\\begin{bmatrix} f_{xx} & f_{xy} \\\\ f_{xy} & f_{yy}\\end{bmatrix}\\), which is \\(f_{xx}f_{yy} - f_{xy}^2\\).","slide":null},{"q":"If \\(W = 0\\) at a stationary point, then:","options":["it is always a saddle point","it is always a minimum","the second-order test does not decide","the point is not stationary"],"correct":2,"explanation":"W = 0 makes the test inconclusive; the point needs another method.","slide":null},{"q":"How many stationary points does \\(f(x,y) = x^3 - 3x + y^2\\) have?","options":["1","2","3","0"],"correct":1,"explanation":"\\(3x^2 - 3 = 0\\) gives \\(x = \\pm1\\) and \\(2y = 0\\) gives \\(y = 0\\): points \\((1,0)\\) and \\((-1,0)\\).","slide":null},{"q":"True or false: every stationary point of a function of two variables is a local extremum.","options":["True","False"],"correct":1,"explanation":"False. A stationary point can be a saddle point, e.g. \\((0,0)\\) for \\(f = x^2 - y^2\\).","slide":null},{"q":"Profit is \\(\\Pi = 40x + 50y - x^2 - xy - y^2\\). What is the profit-maximising output?","options":["\\(x = 20,\\ y = 10\\)","\\(x = 20,\\ y = 25\\)","\\(x = 15,\\ y = 15\\)","\\(x = 10,\\ y = 20\\)"],"correct":3,"explanation":"Solve \\(2x + y = 40\\), \\(x + 2y = 50\\): \\(x = 10\\), \\(y = 20\\); \\(W = 3 > 0\\), \\(\\Pi_{xx} = -2 < 0\\), so it is a maximum.","slide":null}],"lang":"en","lesson":{"intro":"A firm sells two products. How much of each should it make to earn the most? Profit depends on two numbers at once, so we need the two-variable version of 'set the derivative to zero and check the second derivative'.","sections":[{"h":"Local extrema: what we are looking for","body":"A function \\(f(x,y)\\) has a local maximum at \\((x_0,y_0)\\) if \\(f(x_0,y_0) \\ge f(x,y)\\) for all points \\((x,y)\\) close to \\((x_0,y_0)\\). A local minimum is the same with \\(\\le\\).\n\nThink of the graph of \\(f\\) as a landscape: a local maximum is a hilltop, a local minimum is the bottom of a valley.\n\nThere is also a third type of 'flat' point: a saddle point. In one direction the function goes up, in another direction it goes down - like a horse saddle or a mountain pass. A saddle point is NOT an extremum.\n\nThe method has two steps:\n- Step 1 (necessary condition): find the stationary points.\n- Step 2 (sufficient condition): classify each stationary point with the Hessian.","tip":"Exam questions almost always ask for both steps. Writing only the stationary points earns only part of the points."},{"h":"Step 1: stationary points from the gradient","body":"At a local extremum (of a smooth function) the surface is flat, so both partial derivatives are zero. We solve the system\n\\[ \\begin{cases} f_x(x,y) = 0 \\\\ f_y(x,y) = 0 \\end{cases} \\]\nIn other words, the gradient is the zero vector: \\(\\nabla f = (0,0)\\). The solutions are called stationary (critical) points.\n\nBeing stationary is necessary but not enough: a stationary point can be a maximum, a minimum or a saddle point.","example":{"task":"Find the stationary points of \\(f(x,y) = x^3 - 3x + y^2 - 2y\\).","steps":["\\(f_x = 3x^2 - 3\\), \\(f_y = 2y - 2\\).","\\(3x^2 - 3 = 0 \\Rightarrow x^2 = 1 \\Rightarrow x = 1\\) or \\(x = -1\\).","\\(2y - 2 = 0 \\Rightarrow y = 1\\).","Combine every \\(x\\) with every matching \\(y\\): \\((1,1)\\) and \\((-1,1)\\)."],"answer":"Two stationary points: \\(P_1 = (1,1)\\), \\(P_2 = (-1,1)\\)."},"tip":"When an equation gives two values (like x = 1 or x = -1), you get one stationary point for each. Do not lose one!"},{"h":"Step 2: the second-order test with the Hessian determinant","body":"Compute the second partials and the Hessian determinant at each stationary point:\n\\[ W = \\det\\begin{bmatrix} f_{xx} & f_{xy} \\\\ f_{xy} & f_{yy} \\end{bmatrix} = f_{xx}f_{yy} - f_{xy}^2. \\]\nDecision rule:\n- \\(W > 0\\) and \\(f_{xx} > 0\\): local minimum\n- \\(W > 0\\) and \\(f_{xx} < 0\\): local maximum\n- \\(W < 0\\): saddle point (no extremum)\n- \\(W = 0\\): the test gives no answer (inconclusive); other methods are needed\n\nMemory trick: when \\(W > 0\\), \\(f_{xx}\\) works like \\(f''\\) for one variable - positive means 'smile' (minimum), negative means 'frown' (maximum).","example":{"task":"Classify the stationary points \\((1,1)\\) and \\((-1,1)\\) of \\(f(x,y) = x^3 - 3x + y^2 - 2y\\).","steps":["\\(f_{xx} = 6x\\), \\(f_{yy} = 2\\), \\(f_{xy} = 0\\). So \\(W = 6x\\cdot2 - 0^2 = 12x\\).","At \\((1,1)\\): \\(W = 12 > 0\\) and \\(f_{xx} = 6 > 0\\), so a local minimum. \\(f(1,1) = 1 - 3 + 1 - 2 = -3\\).","At \\((-1,1)\\): \\(W = -12 < 0\\), so a saddle point (no extremum)."],"answer":"Local minimum \\(f_{\\min} = f(1,1) = -3\\); \\((-1,1)\\) is a saddle point."},"tip":"If \\(W < 0\\), stop - it is a saddle no matter what the sign of \\(f_{xx}\\) is."},{"h":"A full example with a saddle point","body":"Let us go through a classic exam function from start to end. Notice how the system of equations is solved by substitution.","example":{"task":"Find and classify the local extrema of \\(f(x,y) = x^3 + y^3 - 3xy\\).","steps":["\\(f_x = 3x^2 - 3y = 0 \\Rightarrow y = x^2\\). \\(f_y = 3y^2 - 3x = 0 \\Rightarrow x = y^2\\).","Substitute: \\(x = (x^2)^2 = x^4 \\Rightarrow x(x^3 - 1) = 0 \\Rightarrow x = 0\\) or \\(x = 1\\). Points: \\((0,0)\\), \\((1,1)\\).","\\(f_{xx} = 6x\\), \\(f_{yy} = 6y\\), \\(f_{xy} = -3\\). \\(W = 36xy - 9\\).","At \\((0,0)\\): \\(W = -9 < 0\\): saddle point.","At \\((1,1)\\): \\(W = 36 - 9 = 27 > 0\\), \\(f_{xx} = 6 > 0\\): local minimum, \\(f(1,1) = 1 + 1 - 3 = -1\\)."],"answer":"Local minimum at \\((1,1)\\) with \\(f_{\\min} = -1\\); saddle point at \\((0,0)\\)."}},{"h":"Economics: profit of a firm producing two goods","body":"A firm produces quantities \\(x\\) and \\(y\\) of two goods. If it sells at fixed prices \\(p_1, p_2\\) and has cost \\(C(x,y)\\), its profit is\n\\[ \\Pi(x,y) = p_1x + p_2y - C(x,y). \\]\nWe maximise \\(\\Pi\\) with the same two steps. The conditions \\(\\Pi_x = 0\\), \\(\\Pi_y = 0\\) mean: for each good, marginal revenue equals marginal cost. Remember to check that the answer is a maximum (\\(W > 0\\), \\(\\Pi_{xx} < 0\\)) and that the quantities are positive.","example":{"task":"Prices are \\(p_1 = 40\\) and \\(p_2 = 50\\); cost is \\(C(x,y) = x^2 + xy + y^2\\). Find the profit-maximising output.","steps":["\\(\\Pi = 40x + 50y - x^2 - xy - y^2\\).","\\(\\Pi_x = 40 - 2x - y = 0\\), \\(\\Pi_y = 50 - x - 2y = 0\\). So \\(2x + y = 40\\) and \\(x + 2y = 50\\).","From the first: \\(y = 40 - 2x\\). Then \\(x + 80 - 4x = 50 \\Rightarrow x = 10\\), \\(y = 20\\).","\\(\\Pi_{xx} = -2\\), \\(\\Pi_{yy} = -2\\), \\(\\Pi_{xy} = -1\\). \\(W = 4 - 1 = 3 > 0\\) and \\(\\Pi_{xx} < 0\\): maximum.","\\(\\Pi(10,20) = 400 + 1000 - 100 - 200 - 400 = 700\\)."],"answer":"Produce \\(x = 10\\), \\(y = 20\\); maximum profit 700."},"tip":"Write the answer in economic words: 'the firm should produce 10 units of good 1 and 20 units of good 2; maximum profit is 700'."}],"formulas":["Stationary points: \\(f_x = 0,\\; f_y = 0\\) (i.e. \\(\\nabla f = (0,0)\\))","\\(W = f_{xx}f_{yy} - f_{xy}^2\\)","\\(W > 0,\\ f_{xx} > 0\\): local minimum","\\(W > 0,\\ f_{xx} < 0\\): local maximum","\\(W < 0\\): saddle point (no extremum)","\\(W = 0\\): test inconclusive","Profit of two goods: \\(\\Pi(x,y) = p_1x + p_2y - C(x,y)\\)"],"exercises":[{"task":"Find and classify the extrema of \\(f(x,y) = x^2 + y^2 - 2x - 4y\\).","hint":"\\(f_x = 2x - 2\\), \\(f_y = 2y - 4\\).","answer":"Stationary point \\((1,2)\\); \\(W = 4 > 0\\), \\(f_{xx} = 2 > 0\\): local minimum \\(f(1,2) = -5\\)."},{"task":"Show that \\(f(x,y) = x^2 - y^2 + 4x\\) has no local extremum.","hint":"Find the stationary point and compute W.","answer":"Only stationary point \\((-2,0)\\); \\(f_{xx} = 2\\), \\(f_{yy} = -2\\), \\(f_{xy} = 0\\), \\(W = -4 < 0\\): saddle point, so no extremum."},{"task":"Find and classify the extrema of \\(f(x,y) = -x^2 - 2y^2 + 2xy + 2y\\).","hint":"\\(f_x = -2x + 2y\\) gives \\(x = y\\).","answer":"Stationary point \\((1,1)\\); \\(f_{xx} = -2\\), \\(f_{yy} = -4\\), \\(f_{xy} = 2\\), \\(W = 8 - 4 = 4 > 0\\), \\(f_{xx} < 0\\): local maximum \\(f(1,1) = 1\\)."},{"task":"Find and classify the extrema of \\(f(x,y) = x^3 - 12x + y^2\\).","hint":"\\(3x^2 - 12 = 0\\) gives two values of \\(x\\).","answer":"Points \\((2,0)\\) and \\((-2,0)\\); \\(W = 6x\\cdot2 = 12x\\). At \\((2,0)\\): \\(W = 24 > 0\\), \\(f_{xx} = 12 > 0\\): local minimum \\(f = -16\\). At \\((-2,0)\\): \\(W = -24\\): saddle point."},{"task":"Find and classify the extrema of \\(f(x,y) = xy - x^2 - y^2 + 3y\\).","hint":"From \\(f_x = y - 2x = 0\\): \\(y = 2x\\).","answer":"Stationary point \\((1,2)\\); \\(f_{xx} = -2\\), \\(f_{yy} = -2\\), \\(f_{xy} = 1\\), \\(W = 3 > 0\\), \\(f_{xx} < 0\\): local maximum \\(f(1,2) = 3\\)."},{"task":"For \\(f(x,y) = x^4 + y^2\\), find the stationary point and say what the second-order test tells you.","hint":"Compute \\(f_{xx} = 12x^2\\) at the point.","answer":"Stationary point \\((0,0)\\); \\(f_{xx} = 0\\), \\(f_{yy} = 2\\), \\(f_{xy} = 0\\), so \\(W = 0\\): the test is inconclusive. (Looking directly, \\(f \\ge 0 = f(0,0)\\), so it is in fact a minimum.)"},{"task":"A firm's profit from producing \\(x\\) and \\(y\\) units of two goods is \\(\\Pi(x,y) = 60x + 80y - 2x^2 - 2xy - 3y^2\\). Find the output that maximises profit and the maximum profit.","hint":"Solve \\(60 - 4x - 2y = 0\\) and \\(80 - 2x - 6y = 0\\).","answer":"\\(x = 10\\), \\(y = 10\\); \\(W = (-4)(-6) - (-2)^2 = 20 > 0\\), \\(\\Pi_{xx} = -4 < 0\\): maximum. \\(\\Pi_{\\max} = 700\\)."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-12-constrained-extrema', $lekcja${"tldr":"In real life we rarely optimise freely: a consumer has a budget, a firm must produce a given output. A constrained (conditional) extremum is the largest or smallest value of \\(f(x,y)\\) among points that satisfy a condition \\(g(x,y) = c\\). We learn two methods: substitution (solve the constraint for one variable and get a one-variable problem) and the Lagrange multiplier method (build \\(L = f - \\lambda(g - c)\\) and set its partials to zero). A simple bordered Hessian tells us whether we found a maximum or a minimum. Economics uses: maximising utility with a budget constraint and minimising cost for a given output.","notes":[{"point":"A constrained extremum is the max/min of \\(f\\) only over points with \\(g(x,y) = c\\); it is usually different from the free extremum.","slide":null},{"point":"Substitution: solve the constraint for one variable, plug into f, and solve a one-variable problem.","slide":null},{"point":"Lagrange function: \\(L = f - \\lambda(g - c)\\); set \\(L_x = L_y = L_\\lambda = 0\\).","slide":null},{"point":"From \\(L_x = 0\\) and \\(L_y = 0\\): \\(f_x/g_x = f_y/g_y = \\lambda\\) - a quick way to link x and y.","slide":null},{"point":"Bordered Hessian (2 variables, 1 constraint): \\(\\det\\bar H > 0\\) means maximum, \\(\\det\\bar H < 0\\) means minimum.","slide":null},{"point":"\\(\\lambda\\) measures how much the optimal value changes when the constraint constant \\(c\\) increases by 1 (marginal utility of income, marginal cost).","slide":null},{"point":"Consumer optimum: \\(U_x/p_x = U_y/p_y\\) together with the budget line.","slide":null},{"point":"In cost minimisation, the cost is the objective function and the required output is the constraint.","slide":null}],"concepts":[{"term":"Constrained (conditional) extremum","definition":"A maximum or minimum of \\(f\\) among points that satisfy a constraint \\(g(x,y) = c\\).","pl":"ekstremum warunkowe","slide":null},{"term":"Constraint","definition":"An equation the variables must satisfy, e.g. a budget line.","pl":"warunek (ograniczenie)","slide":null},{"term":"Objective function","definition":"The function we want to maximise or minimise.","pl":"funkcja celu","slide":null},{"term":"Lagrange function","definition":"\\(L = f - \\lambda(g - c)\\); its stationary points are candidates for constrained extrema.","pl":"funkcja Lagrange'a","slide":null},{"term":"Lagrange multiplier","definition":"The extra variable \\(\\lambda\\); it shows how the optimal value reacts to a unit change of the constraint.","pl":"mnożnik Lagrange'a","slide":null},{"term":"Bordered Hessian","definition":"The Hessian of the Lagrange function bordered by the partial derivatives of the constraint; its determinant classifies the point.","pl":"hesjan obrzeżony","slide":null},{"term":"Substitution method","definition":"Solving the constraint for one variable and inserting it into the objective function.","pl":"metoda podstawiania (eliminacji)","slide":null},{"term":"Budget constraint","definition":"\\(p_xx + p_yy = I\\): spending equals income.","pl":"ograniczenie budżetowe","slide":null},{"term":"Cost minimisation","definition":"Choosing inputs to produce a required output at the lowest total cost.","pl":"minimalizacja kosztów","slide":null}],"flashcards":[{"q":"What is a constrained extremum?","a":"The max or min of \\(f(x,y)\\) only among points with \\(g(x,y) = c\\).","slide":null},{"q":"Steps of the substitution method?","a":"Solve the constraint for one variable, plug into f, find the one-variable extremum, compute the other variable.","slide":null},{"q":"Lagrange function?","a":"\\(L = f(x,y) - \\lambda(g(x,y) - c)\\)","slide":null},{"q":"Lagrange conditions?","a":"\\(f_x = \\lambda g_x\\), \\(f_y = \\lambda g_y\\), \\(g(x,y) = c\\).","slide":null},{"q":"Bordered Hessian: \\(\\det \\bar H > 0\\) means?","a":"Constrained maximum.","slide":null},{"q":"Bordered Hessian: \\(\\det \\bar H < 0\\) means?","a":"Constrained minimum.","slide":null},{"q":"Economic meaning of \\(\\lambda\\) in utility maximisation?","a":"Marginal utility of income: extra utility from one more unit of money.","slide":null},{"q":"Economic meaning of \\(\\lambda\\) in cost minimisation?","a":"Marginal cost: extra cost of one more unit of output.","slide":null},{"q":"Consumer optimum condition?","a":"\\(U_x/p_x = U_y/p_y\\) and \\(p_xx + p_yy = I\\).","slide":null},{"q":"Maximum of \\(xy\\) on \\(x + y = 10\\)?","a":"25, at \\((5,5)\\).","slide":null}],"quiz":[{"q":"Using substitution, the maximum of \\(f = xy\\) subject to \\(x + y = 10\\) is:","options":["\\(10\\)","\\(50\\)","\\(25\\)","\\(100\\)"],"correct":2,"explanation":"\\(h(x) = x(10 - x)\\), \\(h' = 0\\) at \\(x = 5\\), so \\(f = 5\\cdot5 = 25\\).","slide":null},{"q":"The Lagrange function for maximising \\(f(x,y)\\) subject to \\(g(x,y) = c\\) is:","options":["\\(L = f - \\lambda(g - c)\\)","\\(L = f\\cdot g - \\lambda c\\)","\\(L = \\lambda f - g\\)","\\(L = f + g + \\lambda\\)"],"correct":0,"explanation":"We subtract \\(\\lambda\\) times the constraint written as \\(g - c = 0\\); \\(f + \\lambda(c - g)\\) is the same thing.","slide":null},{"q":"For two variables and one constraint, \\(\\det\\bar H < 0\\) at a stationary point of \\(L\\) means:","options":["constrained maximum","saddle point","the test is inconclusive","constrained minimum"],"correct":3,"explanation":"With the bordered Hessian the rule is: \\(\\det\\bar H > 0\\) maximum, \\(\\det\\bar H < 0\\) minimum.","slide":null},{"q":"Minimise \\(f = x^2 + y^2\\) subject to \\(x + y = 4\\). The minimum value is:","options":["\\(16\\)","\\(8\\)","\\(4\\)","\\(2\\)"],"correct":1,"explanation":"By symmetry (or Lagrange: \\(2x = 2y = \\lambda\\)) \\(x = y = 2\\), so \\(f = 4 + 4 = 8\\).","slide":null},{"q":"\\(U = xy\\), \\(p_x = 2\\), \\(p_y = 4\\), income 80. The optimal bundle is:","options":["\\(x = 10,\\ y = 15\\)","\\(x = 20,\\ y = 10\\)","\\(x = 10,\\ y = 20\\)","\\(x = 40,\\ y = 0\\)"],"correct":1,"explanation":"Lagrange gives \\(x = 2y\\); \\(2(2y) + 4y = 80 \\Rightarrow y = 10\\), \\(x = 20\\). (10, 15) is affordable but gives only 150 < 200.","slide":null},{"q":"In utility maximisation the optimal \\(\\lambda = 5\\). This means:","options":["one more unit of income raises maximum utility by about 5","the consumer buys 5 units of each good","the price of good x is 5","utility is maximised at 5"],"correct":0,"explanation":"\\(\\lambda\\) is the marginal utility of income: the change in the optimal utility per extra unit of income.","slide":null},{"q":"In cost minimisation (produce Q0 at the lowest cost), the constraint is:","options":["\\(rK + wL = C\\)","\\(K = L\\)","\\(\\lambda = 0\\)","\\(Q(K,L) = Q_0\\)"],"correct":3,"explanation":"The cost rK + wL is the objective; the required output Q(K, L) = Q0 is the constraint.","slide":null},{"q":"True or false: a constrained maximum is always also a free (unconstrained) maximum of f.","options":["True","False"],"correct":1,"explanation":"False. \\(f = xy\\) has no free maximum, but on \\(x + y = 10\\) it has a constrained maximum of 25.","slide":null}],"lang":"en","lesson":{"intro":"You have 80 zł to spend on two goods. You cannot buy 'infinitely much' - your choice must stay on the budget line. Constrained optimisation finds the best point on such a line.","sections":[{"h":"What is a constrained extremum?","body":"We want to find the maximum or minimum of an objective function \\(f(x,y)\\), but only among points that satisfy a constraint\n\\[ g(x,y) = c. \\]\nThe constraint is a curve in the plane (often a straight line, like a budget line). We are looking for the highest or lowest point of the surface \\(z = f(x,y)\\) when we are only allowed to walk along this curve.\n\nImportant: a constrained extremum is usually NOT a free extremum. For example \\(f(x,y) = xy\\) has no free maximum at all, but on the line \\(x + y = 10\\) it does have a maximum.\n\nTwo methods:\n- substitution - quick when the constraint is easy to solve for \\(x\\) or \\(y\\)\n- Lagrange multipliers - works in general and gives the useful number \\(\\lambda\\)","tip":"Always read which constraint is given; it is easy to forget it and solve the free problem instead."},{"h":"Method 1: substitution","body":"Steps:\n- Solve the constraint for one variable, e.g. \\(y = \\dots\\)\n- Put it into \\(f\\). Now \\(f\\) depends on one variable only.\n- Find the extremum of this one-variable function with the usual derivative test (\\(h' = 0\\), then the sign of \\(h''\\)).\n- Compute the other variable from the constraint.","example":{"task":"Find the maximum of \\(f(x,y) = xy\\) subject to \\(x + y = 10\\).","steps":["From the constraint: \\(y = 10 - x\\).","Substitute: \\(h(x) = x(10 - x) = 10x - x^2\\).","\\(h'(x) = 10 - 2x = 0 \\Rightarrow x = 5\\). \\(h''(x) = -2 < 0\\), so a maximum.","\\(y = 10 - 5 = 5\\), \\(f(5,5) = 25\\)."],"answer":"Constrained maximum \\(f(5,5) = 25\\)."},"tip":"Do not forget the last step: compute the second variable and the value of f."},{"h":"Method 2: Lagrange multipliers","body":"Build the Lagrange function with a new variable \\(\\lambda\\) (lambda, the Lagrange multiplier):\n\\[ L(x,y,\\lambda) = f(x,y) - \\lambda\\,\\big(g(x,y) - c\\big). \\]\nSet all three partial derivatives to zero:\n\\[ \\begin{cases} L_x = f_x - \\lambda g_x = 0 \\\\ L_y = f_y - \\lambda g_y = 0 \\\\ L_\\lambda = -(g(x,y) - c) = 0 \\;\\Leftrightarrow\\; g(x,y) = c \\end{cases} \\]\nA useful trick: from the first two equations, \\(\\lambda = f_x/g_x = f_y/g_y\\). This gives a simple relation between \\(x\\) and \\(y\\); then use the constraint.\n\nMeaning of \\(\\lambda\\): it tells how much the optimal value of \\(f\\) changes when \\(c\\) increases by one unit. In a budget problem, \\(\\lambda\\) is the marginal utility of money.\n\n(Some books write \\(L = f + \\lambda(c - g)\\). It is the same function, so you get the same answer.)","example":{"task":"Use the Lagrange method: maximise \\(f(x,y) = xy\\) subject to \\(x + y = 10\\).","steps":["\\(L = xy - \\lambda(x + y - 10)\\).","\\(L_x = y - \\lambda = 0\\), \\(L_y = x - \\lambda = 0\\), so \\(x = y = \\lambda\\).","Constraint: \\(x + x = 10 \\Rightarrow x = 5\\), \\(y = 5\\), \\(\\lambda = 5\\).","\\(f(5,5) = 25\\). Interpretation: if the constraint became \\(x + y = 11\\), the maximum would grow by about \\(\\lambda = 5\\)."],"answer":"Stationary point \\((5,5)\\) with \\(\\lambda = 5\\); \\(f = 25\\) (it is a maximum, see next section)."},"tip":"Do not divide by a variable that could be zero without checking that case separately."},{"h":"Max or min? The bordered Hessian (kept simple)","body":"For two variables and one constraint we use the bordered Hessian: the Hessian of \\(L\\) with the derivatives of \\(g\\) added as a 'border':\n\\[ \\bar H = \\begin{bmatrix} 0 & g_x & g_y \\\\ g_x & L_{xx} & L_{xy} \\\\ g_y & L_{xy} & L_{yy} \\end{bmatrix}. \\]\nCompute its determinant at the stationary point (with the found \\(\\lambda\\)):\n- \\(\\det \\bar H > 0\\): constrained local maximum\n- \\(\\det \\bar H < 0\\): constrained local minimum\n\nNote the signs are the OPPOSITE of what many students expect - positive means maximum here.\n\nIf you used substitution, you do not need \\(\\bar H\\): the sign of \\(h''\\) already decides.","example":{"task":"Check the point \\((5,5)\\) for \\(f = xy\\), \\(g = x + y = 10\\).","steps":["\\(g_x = 1\\), \\(g_y = 1\\). \\(L_{xx} = 0\\), \\(L_{yy} = 0\\), \\(L_{xy} = 1\\).","\\(\\det\\begin{bmatrix} 0 & 1 & 1 \\\\ 1 & 0 & 1 \\\\ 1 & 1 & 0 \\end{bmatrix} = 0 - 1\\cdot(0 - 1) + 1\\cdot(1 - 0) = 2\\).","\\(\\det \\bar H = 2 > 0\\), so a constrained maximum."],"answer":"Constrained maximum at \\((5,5)\\), \\(f_{\\max} = 25\\)."},"tip":"Expand the 3x3 determinant along the first row - it has a zero, so only two terms remain."},{"h":"Economics: utility maximisation and cost minimisation","body":"Utility maximisation. A consumer with income \\(I\\) buys \\(x\\) and \\(y\\) at prices \\(p_x, p_y\\):\n\\[ \\max\\; U(x,y) \\quad \\text{subject to} \\quad p_xx + p_yy = I. \\]\nThe Lagrange conditions give \\(\\dfrac{U_x}{p_x} = \\dfrac{U_y}{p_y} = \\lambda\\): the last złoty spent on each good gives the same extra utility.\n\nCost minimisation. A firm wants output \\(Q(K,L) = Q_0\\) at the lowest cost:\n\\[ \\min\\; C = rK + wL \\quad \\text{subject to} \\quad Q(K,L) = Q_0. \\]\nHere \\(\\lambda\\) is the marginal cost: the extra cost of producing one more unit of output.","example":{"task":"Utility \\(U = xy\\), prices \\(p_x = 2\\), \\(p_y = 4\\), income 80. Find the optimal bundle.","steps":["\\(L = xy - \\lambda(2x + 4y - 80)\\).","\\(L_x = y - 2\\lambda = 0\\), \\(L_y = x - 4\\lambda = 0\\). So \\(y = 2\\lambda\\), \\(x = 4\\lambda\\), hence \\(x = 2y\\).","Budget: \\(2(2y) + 4y = 80 \\Rightarrow 8y = 80 \\Rightarrow y = 10\\), \\(x = 20\\), \\(\\lambda = 5\\).","Bordered Hessian: \\(\\det\\begin{bmatrix} 0 & 2 & 4 \\\\ 2 & 0 & 1 \\\\ 4 & 1 & 0 \\end{bmatrix} = 16 > 0\\): maximum.","\\(U(20,10) = 200\\). One extra złoty of income raises maximum utility by about \\(\\lambda = 5\\)."],"answer":"Buy \\(x = 20\\), \\(y = 10\\); \\(U_{\\max} = 200\\), \\(\\lambda = 5\\)."},"tip":"In cost minimisation the objective is the cost and the constraint is the output - students often swap them."}],"formulas":["Problem: extremum of \\(f(x,y)\\) subject to \\(g(x,y) = c\\)","Substitution: \\(y = y(x)\\) from the constraint, then \\(h(x) = f(x, y(x))\\), \\(h'(x) = 0\\)","Lagrange function: \\(L = f(x,y) - \\lambda\\,(g(x,y) - c)\\)","Conditions: \\(f_x = \\lambda g_x,\\; f_y = \\lambda g_y,\\; g(x,y) = c\\)","\\(\\bar H = \\begin{bmatrix} 0 & g_x & g_y \\\\ g_x & L_{xx} & L_{xy} \\\\ g_y & L_{xy} & L_{yy} \\end{bmatrix}\\): \\(\\det\\bar H > 0\\) max, \\(\\det\\bar H < 0\\) min","\\(\\lambda \\approx\\) change of the optimal value of \\(f\\) when \\(c\\) rises by 1","Consumer optimum: \\(\\dfrac{U_x}{p_x} = \\dfrac{U_y}{p_y}\\), \\(p_xx + p_yy = I\\)","Cost minimisation: \\(\\min\\, rK + wL\\) s.t. \\(Q(K,L) = Q_0\\)"],"exercises":[{"task":"Using substitution, find the maximum of \\(f(x,y) = xy\\) subject to \\(x + 2y = 20\\).","hint":"\\(x = 20 - 2y\\), so \\(h(y) = 20y - 2y^2\\).","answer":"\\(h'(y) = 20 - 4y = 0 \\Rightarrow y = 5\\), \\(x = 10\\); \\(h'' = -4 < 0\\): maximum \\(f(10,5) = 50\\)."},{"task":"Find the minimum of \\(f(x,y) = x^2 + y^2\\) subject to \\(x + y = 6\\).","hint":"Substitution \\(y = 6 - x\\) or Lagrange: \\(2x = \\lambda = 2y\\).","answer":"\\(x = y = 3\\), \\(f_{\\min} = 18\\) (\\(\\lambda = 6\\))."},{"task":"For the problem in exercise 2, compute the bordered Hessian determinant at \\((3,3)\\) and confirm the type of extremum.","hint":"\\(g_x = g_y = 1\\), \\(L_{xx} = L_{yy} = 2\\), \\(L_{xy} = 0\\).","answer":"\\(\\det\\begin{bmatrix} 0 & 1 & 1 \\\\ 1 & 2 & 0 \\\\ 1 & 0 & 2 \\end{bmatrix} = -4 < 0\\): constrained minimum."},{"task":"Use the Lagrange method to find the maximum of \\(f(x,y) = x^2y\\) subject to \\(x + y = 3\\), with \\(x, y > 0\\).","hint":"\\(2xy = \\lambda\\) and \\(x^2 = \\lambda\\); since \\(x > 0\\), divide to get \\(x = 2y\\).","answer":"\\(x = 2\\), \\(y = 1\\), \\(\\lambda = 4\\), \\(f_{\\max} = 4\\) (\\(\\det\\bar H = 6 > 0\\): maximum)."},{"task":"A consumer has utility \\(U = xy\\), prices \\(p_x = 5\\), \\(p_y = 10\\) and income 200. Find the optimal bundle, the maximum utility and \\(\\lambda\\). Interpret \\(\\lambda\\).","hint":"\\(y = 5\\lambda\\), \\(x = 10\\lambda\\), so \\(x = 2y\\).","answer":"\\(x = 20\\), \\(y = 10\\), \\(U_{\\max} = 200\\), \\(\\lambda = 2\\): one more złoty of income raises maximum utility by about 2."},{"task":"A firm's output is \\(Q = KL\\). The price of capital is 3 and the wage is 12. Find the cheapest way to produce \\(Q = 100\\) and the minimum cost.","hint":"\\(L = 3K + 12L - \\lambda(KL - 100)\\): \\(3 = \\lambda L\\), \\(12 = \\lambda K\\), so \\(K = 4L\\).","answer":"\\(4L^2 = 100 \\Rightarrow L = 5\\), \\(K = 20\\); \\(C_{\\min} = 60 + 60 = 120\\), \\(\\lambda = 0.6\\) (marginal cost of one more unit of output)."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-13-indefinite-integral', $lekcja${"tldr":"Integration is differentiation in reverse: we look for a function \\(F\\) whose derivative is the given \\(f\\). Such an \\(F\\) is called an antiderivative, and the set of all of them is the indefinite integral \\(\\int f(x)\\,dx = F(x)+C\\). The integral is linear, so you can split sums and pull out constants, and a short table of basic integrals covers most simple tasks. You can always check your answer by differentiating it. In economics, integrating marginal cost gives total cost, and the constant \\(C\\) is exactly the fixed cost.","notes":[{"point":"\\(F\\) is an antiderivative of \\(f\\) when \\(F'=f\\). Two antiderivatives of the same function differ only by a constant.","slide":null},{"point":"The indefinite integral is the whole family \\(F(x)+C\\); always write the \\(+C\\).","slide":null},{"point":"Power rule: \\(\\int x^n dx=\\frac{x^{n+1}}{n+1}+C\\) for \\(n\\ne-1\\); the case \\(n=-1\\) gives \\(\\ln|x|+C\\).","slide":null},{"point":"Turn roots and fractions into powers before integrating: \\(\\sqrt[3]{x}=x^{1/3}\\), \\(\\frac{1}{x^4}=x^{-4}\\).","slide":null},{"point":"The integral is linear: integrate sums term by term and move constant factors outside.","slide":null},{"point":"There is no product or quotient rule for integrals; expand or simplify first.","slide":null},{"point":"Check any indefinite integral by differentiating it: you must get the integrand back.","slide":null},{"point":"An initial condition such as F(1) = 6 fixes the value of the constant C.","slide":null},{"point":"\\(TC(q)=\\int MC(q)\\,dq\\), and the constant of integration equals the fixed cost \\(TC(0)\\).","slide":null}],"concepts":[{"term":"Antiderivative (primitive function)","definition":"A function \\(F\\) whose derivative equals the given function: \\(F'(x)=f(x)\\).","pl":"funkcja pierwotna","slide":null},{"term":"Indefinite integral","definition":"The set of all antiderivatives of \\(f\\), written \\(\\int f(x)\\,dx=F(x)+C\\).","pl":"całka nieoznaczona","slide":null},{"term":"Integrand","definition":"The function under the integral sign, \\(f(x)\\) in \\(\\int f(x)\\,dx\\).","pl":"funkcja podcałkowa","slide":null},{"term":"Constant of integration","definition":"The arbitrary constant \\(C\\) added to an antiderivative, because constants vanish when differentiated.","pl":"stała całkowania","slide":null},{"term":"Linearity of the integral","definition":"The integral of a sum is the sum of integrals, and constant factors can be moved outside the integral.","pl":"liniowość całki","slide":null},{"term":"Initial condition","definition":"A known value of the function, such as \\(F(x_0)=y_0\\), used to find the constant \\(C\\).","pl":"warunek początkowy","slide":null},{"term":"Marginal cost","definition":"The derivative of total cost; integrating it gives total cost up to the fixed cost.","pl":"koszt krańcowy","slide":null},{"term":"Fixed cost","definition":"The cost that does not depend on output; it equals TC(0) and plays the role of C.","pl":"koszt stały","slide":null}],"flashcards":[{"q":"What does it mean that \\(F\\) is an antiderivative of \\(f\\)?","a":"\\(F'(x)=f(x)\\).","slide":null},{"q":"\\(\\int x^n\\,dx\\) for \\(n\\neq-1\\)?","a":"\\(\\frac{x^{n+1}}{n+1}+C\\)","slide":null},{"q":"\\(\\int \\frac{1}{x}\\,dx\\)?","a":"\\(\\ln|x|+C\\)","slide":null},{"q":"\\(\\int e^x\\,dx\\)?","a":"\\(e^x+C\\)","slide":null},{"q":"\\(\\int a^x\\,dx\\)?","a":"\\(\\frac{a^x}{\\ln a}+C\\)","slide":null},{"q":"\\(\\int \\sin x\\,dx\\)?","a":"\\(-\\cos x+C\\)","slide":null},{"q":"\\(\\int \\frac{1}{1+x^2}\\,dx\\)?","a":"\\(\\arctan x+C\\)","slide":null},{"q":"How do you check an indefinite integral?","a":"Differentiate the result; you must get the integrand.","slide":null},{"q":"In TC = ∫MC dq, what is the constant?","a":"The fixed cost, TC(0).","slide":null},{"q":"\\(\\int \\sqrt{x}\\,dx\\)?","a":"\\(\\frac{2}{3}x^{3/2}+C\\)","slide":null}],"quiz":[{"q":"\\(\\int x^5\\,dx=\\)","options":["\\(\\frac{x^6}{6}+C\\)","\\(5x^4+C\\)","\\(x^6+C\\)","\\(\\frac{x^5}{5}+C\\)"],"correct":0,"explanation":"Add 1 to the power and divide by the new power. 5x^4 is the derivative, not the integral.","slide":null},{"q":"\\(\\int \\frac{1}{x}\\,dx=\\)","options":["\\(-\\frac{1}{x^2}+C\\)","\\(\\ln|x|+C\\)","\\(\\frac{1}{2x^2}+C\\)","\\(e^x+C\\)"],"correct":1,"explanation":"The power rule fails for \\(n=-1\\); the antiderivative of \\(\\frac1x\\) is \\(\\ln|x|\\).","slide":null},{"q":"Which function is an antiderivative of \\(f(x)=e^x+2x\\)?","options":["\\(e^x+2\\)","\\(xe^{x-1}+x^2\\)","\\(e^x+x^2+7\\)","\\(e^x+2x^2\\)"],"correct":2,"explanation":"\\((e^x+x^2+7)'=e^x+2x\\). Any constant may be added.","slide":null},{"q":"Marginal cost is \\(MC(q)=4q+10\\) and fixed cost is 100. Total cost is:","options":["\\(2q^2+10q\\)","\\(4q^2+10q+100\\)","\\(2q^2+10q+100q\\)","\\(2q^2+10q+100\\)"],"correct":3,"explanation":"Integrate: \\(2q^2+10q+C\\); the constant equals the fixed cost, 100.","slide":null},{"q":"True or false: \\(\\int f(x)g(x)\\,dx=\\int f(x)\\,dx\\cdot\\int g(x)\\,dx\\).","options":["True","False"],"correct":1,"explanation":"There is no product rule like this. For example \\(\\int x\\cdot x\\,dx=\\frac{x^3}{3}+C\\), but \\(\\frac{x^2}{2}\\cdot\\frac{x^2}{2}=\\frac{x^4}{4}\\).","slide":null},{"q":"\\(\\int \\cos x\\,dx=\\)","options":["\\(-\\sin x+C\\)","\\(\\sin x+C\\)","\\(\\cos x+C\\)","\\(-\\cos x+C\\)"],"correct":1,"explanation":"\\((\\sin x)'=\\cos x\\), so the answer is \\(\\sin x+C\\).","slide":null},{"q":"\\(F'(x)=2x\\) and \\(F(2)=10\\). Then \\(F(x)=\\)","options":["\\(x^2+10\\)","\\(x^2+8\\)","\\(x^2+6\\)","\\(x^2-6\\)"],"correct":2,"explanation":"\\(F(x)=x^2+C\\) and \\(4+C=10\\), so \\(C=6\\).","slide":null},{"q":"\\(\\int \\frac{3}{x^2}\\,dx=\\)","options":["\\(\\frac{3}{x}+C\\)","\\(3\\ln x^2+C\\)","\\(-\\frac{6}{x^3}+C\\)","\\(-\\frac{3}{x}+C\\)"],"correct":3,"explanation":"\\(3\\int x^{-2}dx=3\\cdot\\frac{x^{-1}}{-1}=-\\frac{3}{x}\\). The option \\(-\\frac{6}{x^3}\\) is the derivative.","slide":null}],"lang":"en","lesson":{"intro":"So far you have been given a function and asked for its derivative. Now we go the other way: we know the derivative (for example marginal cost) and we want the original function (total cost). This reverse process is called integration.","sections":[{"h":"Antiderivative: going backwards","body":"A function \\(F\\) is an antiderivative (primitive function) of \\(f\\) on an interval if\n\\[F'(x)=f(x)\\]\nfor every \\(x\\) in that interval.\n\nFor example, \\(F(x)=x^3\\) is an antiderivative of \\(f(x)=3x^2\\), because \\((x^3)'=3x^2\\). But \\(x^3+5\\) and \\(x^3-100\\) also work, because the derivative of a constant is zero. So one function has infinitely many antiderivatives, and they differ only by a constant.","example":{"task":"Find all antiderivatives of \\(f(x)=4x^3\\).","steps":["Ask: which function gives \\(4x^3\\) after differentiating?","We know \\((x^4)'=4x^3\\), so \\(F(x)=x^4\\) is one antiderivative.","Any constant can be added: \\(x^4+C\\)."],"answer":"\\(F(x)=x^4+C\\), where \\(C\\) is any real number."},"tip":"Never forget the \\(+C\\). On exams a missing constant usually costs points."},{"h":"The indefinite integral and the basic table","body":"The set of all antiderivatives of \\(f\\) is called the indefinite integral:\n\\[\\int f(x)\\,dx = F(x)+C.\\]\nHere \\(f(x)\\) is the integrand, \\(dx\\) shows the variable, and \\(C\\) is the constant of integration.\n\nEvery derivative rule you know gives an integral rule. The most important ones:\n- \\(\\int x^n\\,dx=\\frac{x^{n+1}}{n+1}+C\\) for \\(n\\neq -1\\) (power rule: add 1 to the power, divide by the new power)\n- \\(\\int \\frac{1}{x}\\,dx=\\ln|x|+C\\)\n- \\(\\int e^x\\,dx=e^x+C\\)\n- \\(\\int a^x\\,dx=\\frac{a^x}{\\ln a}+C\\) for \\(a>0,\\ a\\neq 1\\)\n- \\(\\int \\sin x\\,dx=-\\cos x+C\\), \\(\\int \\cos x\\,dx=\\sin x+C\\)\n- \\(\\int \\frac{1}{\\cos^2 x}\\,dx=\\tan x+C\\)\n- \\(\\int \\frac{1}{1+x^2}\\,dx=\\arctan x+C\\)\n- \\(\\int k\\,dx = kx+C\\) for a constant \\(k\\)","example":{"task":"Compute \\(\\int \\sqrt{x}\\,dx\\) and \\(\\int \\frac{1}{x^3}\\,dx\\).","steps":["Write roots and fractions as powers: \\(\\sqrt{x}=x^{1/2}\\), \\(\\frac{1}{x^3}=x^{-3}\\).","\\(\\int x^{1/2}\\,dx=\\frac{x^{3/2}}{3/2}+C=\\frac{2}{3}x^{3/2}+C\\).","\\(\\int x^{-3}\\,dx=\\frac{x^{-2}}{-2}+C=-\\frac{1}{2x^2}+C\\)."],"answer":"\\(\\frac{2}{3}x^{3/2}+C\\) and \\(-\\frac{1}{2x^2}+C\\)."},"tip":"The power rule does not work for \\(n=-1\\) (you would divide by zero). For \\(\\frac{1}{x}\\) use \\(\\ln|x|\\)."},{"h":"Linearity: split sums, pull out constants","body":"The integral behaves nicely with sums and constant factors:\n\\[\\int \\big(f(x)\\pm g(x)\\big)\\,dx=\\int f(x)\\,dx\\pm\\int g(x)\\,dx,\\qquad \\int k\\,f(x)\\,dx = k\\int f(x)\\,dx.\\]\nSo you can integrate a polynomial term by term. You only need to write one \\(+C\\) at the end.","example":{"task":"Compute \\(\\int \\left(\\frac{3}{x}+2e^x-5\\sqrt{x}\\right)dx\\).","steps":["Split: \\(3\\int\\frac{1}{x}dx+2\\int e^x dx-5\\int x^{1/2}dx\\).","Use the table: \\(3\\ln|x|+2e^x-5\\cdot\\frac{2}{3}x^{3/2}\\).","Simplify and add one constant."],"answer":"\\(3\\ln|x|+2e^x-\\frac{10}{3}x^{3/2}+C\\)"},"tip":"There is NO product rule for integrals: \\(\\int f g\\,dx\\) is not \\(\\int f\\,dx\\cdot\\int g\\,dx\\). Multiply out first, or use methods from the next lesson."},{"h":"Rewrite before you integrate","body":"Many integrals look hard only because of their form. Before integrating:\n- multiply out brackets,\n- split a fraction with a single term in the denominator,\n- turn roots into powers.\nThen use the table.","example":{"task":"Compute \\(\\int \\frac{x^2+1}{x}\\,dx\\) and \\(\\int (x+1)^2\\,dx\\).","steps":["Split the fraction: \\(\\frac{x^2+1}{x}=x+\\frac{1}{x}\\). So the first integral is \\(\\frac{x^2}{2}+\\ln|x|+C\\).","Expand: \\((x+1)^2=x^2+2x+1\\).","Integrate term by term: \\(\\frac{x^3}{3}+x^2+x+C\\)."],"answer":"\\(\\frac{x^2}{2}+\\ln|x|+C\\) and \\(\\frac{x^3}{3}+x^2+x+C\\)."}},{"h":"Checking your answer and finding C","body":"Integration has a built-in check: differentiate your answer. If you get the integrand back, you are right.\n\nSometimes extra information fixes the constant. If you know one value \\(F(x_0)=y_0\\) (an initial condition), substitute it and solve for \\(C\\).","example":{"task":"Find \\(F\\) such that \\(F'(x)=2x+3\\) and \\(F(1)=6\\).","steps":["Integrate: \\(F(x)=\\int(2x+3)\\,dx=x^2+3x+C\\).","Use the condition: \\(F(1)=1+3+C=6\\), so \\(C=2\\).","Check: \\((x^2+3x+2)'=2x+3\\) and \\(F(1)=6\\). Correct."],"answer":"\\(F(x)=x^2+3x+2\\)"}},{"h":"Economics: total cost from marginal cost","body":"Marginal cost is the derivative of total cost: \\(MC(q)=TC'(q)\\). So total cost is an antiderivative of marginal cost:\n\\[TC(q)=\\int MC(q)\\,dq = VC(q)+C.\\]\nWhat is the constant? Put \\(q=0\\): nothing is produced, so the only cost left is the fixed cost. Therefore \\(C=TC(0)=FC\\).\n\nThe same idea works for revenue: \\(R(q)=\\int MR(q)\\,dq\\), and usually \\(R(0)=0\\) (no sales, no revenue), so the constant is 0.","example":{"task":"Marginal cost is \\(MC(q)=3q^2-12q+20\\) and fixed cost is 50. Find total cost and \\(TC(10)\\).","steps":["Integrate: \\(TC(q)=q^3-6q^2+20q+C\\).","Fixed cost: \\(TC(0)=C=50\\).","So \\(TC(q)=q^3-6q^2+20q+50\\).","\\(TC(10)=1000-600+200+50=650\\)."],"answer":"\\(TC(q)=q^3-6q^2+20q+50\\), \\(TC(10)=650\\)."},"tip":"In cost problems the constant is never just \\(C\\) at the end: always replace it by the fixed cost."}],"formulas":["\\(\\int f(x)\\,dx=F(x)+C \\iff F'(x)=f(x)\\)","\\(\\int x^n\\,dx=\\frac{x^{n+1}}{n+1}+C,\\ n\\neq-1\\)","\\(\\int \\frac{1}{x}\\,dx=\\ln|x|+C\\)","\\(\\int e^x\\,dx=e^x+C,\\quad \\int a^x\\,dx=\\frac{a^x}{\\ln a}+C\\)","\\(\\int \\sin x\\,dx=-\\cos x+C,\\quad \\int\\cos x\\,dx=\\sin x+C\\)","\\(\\int \\frac{1}{1+x^2}\\,dx=\\arctan x+C,\\quad \\int\\frac{1}{\\cos^2x}\\,dx=\\tan x+C\\)","\\(\\int (af+bg)\\,dx=a\\int f\\,dx+b\\int g\\,dx\\)","\\(TC(q)=\\int MC(q)\\,dq,\\quad TC(0)=FC\\)"],"exercises":[{"task":"Compute \\(\\int (5x^4-2x)\\,dx\\).","hint":"Power rule term by term.","answer":"\\(x^5-x^2+C\\)"},{"task":"Compute \\(\\int \\left(\\frac{1}{x^2}+3\\right)dx\\).","hint":"Write \\(\\frac{1}{x^2}=x^{-2}\\).","answer":"\\(-\\frac{1}{x}+3x+C\\)"},{"task":"Compute \\(\\int \\left(4e^x-\\frac{2}{x}\\right)dx\\).","hint":"Table: e^x and 1/x.","answer":"\\(4e^x-2\\ln|x|+C\\)"},{"task":"Compute \\(\\int \\left(2\\sqrt{x}+\\frac{1}{\\sqrt{x}}\\right)dx\\).","hint":"\\(\\sqrt{x}=x^{1/2}\\), \\(\\frac{1}{\\sqrt x}=x^{-1/2}\\).","answer":"\\(\\frac{4}{3}x^{3/2}+2\\sqrt{x}+C\\)"},{"task":"Compute \\(\\int \\frac{x^3-2x}{x}\\,dx\\).","hint":"Divide each term by x first.","answer":"\\(\\frac{x^3}{3}-2x+C\\)"},{"task":"Compute \\(\\int 2^x\\,dx\\).","hint":"Use \\(\\int a^x dx=\\frac{a^x}{\\ln a}+C\\).","answer":"\\(\\frac{2^x}{\\ln 2}+C\\)"},{"task":"Find \\(F\\) with \\(F'(x)=6x^2-4\\) and \\(F(1)=5\\).","hint":"Integrate, then substitute x = 1 to find C.","answer":"\\(F(x)=2x^3-4x+7\\) (since \\(2-4+C=5\\), so \\(C=7\\))."},{"task":"A firm has marginal cost \\(MC(q)=0.3q^2-2q+15\\) and fixed cost 200. Find \\(TC(q)\\), compute \\(TC(10)\\), and find how much total cost rises when output goes from 10 to 20.","hint":"Integrate MC; the constant equals the fixed cost.","answer":"\\(TC(q)=0.1q^3-q^2+15q+200\\); \\(TC(10)=350\\); \\(TC(20)=900\\), so cost rises by 550."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-14-substitution-parts', $lekcja${"tldr":"The basic table is not enough for integrals like \\(\\int x e^{x^2}dx\\) or \\(\\int x\\ln x\\,dx\\). Two methods handle most of them. Substitution reverses the chain rule: you replace an inner function by a new variable \\(t\\) when its derivative is also present. Integration by parts reverses the product rule: \\(\\int u\\,dv=uv-\\int v\\,du\\), and the LIATE order tells you which factor to call \\(u\\). In economics these methods let you recover total revenue or cost from marginal functions that contain logarithms, exponentials or fractions.","notes":[{"point":"Substitution works when the integrand contains an inner function and (up to a constant) its derivative.","slide":null},{"point":"After substitution the integral must contain only \\(t\\); then integrate and return to \\(x\\).","slide":null},{"point":"Linear inside: \\(\\int f(ax+b)dx=\\frac1aF(ax+b)+C\\), e.g. \\(\\int e^{3x}dx=\\frac13e^{3x}+C\\).","slide":null},{"point":"If the numerator is the derivative of the denominator, the answer is \\(\\ln|\\text{denominator}|+C\\).","slide":null},{"point":"Integration by parts: \\(\\int u\\,dv=uv-\\int v\\,du\\); it reverses the product rule.","slide":null},{"point":"Choose u by LIATE: logarithms first, exponentials last. The new integral must be easier.","slide":null},{"point":"\\(\\int\\ln x\\,dx\\) is done by parts with \\(u=\\ln x\\), \\(dv=dx\\): result \\(x\\ln x-x+C\\).","slide":null},{"point":"\\(x^n e^x\\) needs integration by parts \\(n\\) times; watch the signs.","slide":null}],"concepts":[{"term":"Integration by substitution","definition":"A method that replaces an inner function by a new variable \\(t\\) so the integral becomes a basic one.","pl":"całkowanie przez podstawienie","slide":null},{"term":"Integration by parts","definition":"A method based on \\(\\int u\\,dv=uv-\\int v\\,du\\), used for products of different kinds of functions.","pl":"całkowanie przez części","slide":null},{"term":"Inner function","definition":"The function inside another one, e.g. \\(x^2+1\\) in \\((x^2+1)^5\\); it is usually the substitution \\(t\\).","pl":"funkcja wewnętrzna","slide":null},{"term":"Differential","definition":"The expression \\(dt=g'(x)\\,dx\\) that tells you how \\(dx\\) changes after substitution.","pl":"różniczka","slide":null},{"term":"LIATE rule","definition":"A memory aid for choosing u in integration by parts: Logarithmic, Inverse trigonometric, Algebraic, Trigonometric, Exponential.","pl":"reguła LIATE (wybór funkcji u)","slide":null},{"term":"Marginal revenue","definition":"The derivative of total revenue; integrating it (with R(0) = 0) gives total revenue.","pl":"przychód krańcowy","slide":null}],"flashcards":[{"q":"Substitution reverses which differentiation rule?","a":"The chain rule.","slide":null},{"q":"Integration by parts reverses which rule?","a":"The product rule.","slide":null},{"q":"Integration by parts formula?","a":"\\(\\int u\\,dv=uv-\\int v\\,du\\)","slide":null},{"q":"\\(\\int \\frac{f'(x)}{f(x)}dx\\)?","a":"\\(\\ln|f(x)|+C\\)","slide":null},{"q":"\\(\\int e^{ax}dx\\)?","a":"\\(\\frac1ae^{ax}+C\\)","slide":null},{"q":"What does LIATE stand for?","a":"Logarithmic, Inverse trig, Algebraic, Trigonometric, Exponential (choose u in this order).","slide":null},{"q":"\\(\\int\\ln x\\,dx\\)?","a":"\\(x\\ln x-x+C\\)","slide":null},{"q":"Best substitution for \\(\\int x(x^2+3)^7dx\\)?","a":"\\(t=x^2+3\\)","slide":null},{"q":"How many times do you use parts for \\(\\int x^2e^xdx\\)?","a":"Twice.","slide":null},{"q":"\\(\\int xe^x\\,dx\\)?","a":"\\((x-1)e^x+C\\)","slide":null}],"quiz":[{"q":"What is the best first step for \\(\\int 2x\\cos(x^2)\\,dx\\)?","options":["Substitute \\(t=x^2\\)","Substitute \\(t=\\cos(x^2)\\)","Parts with \\(u=2x\\)","Substitute \\(t=2x\\)"],"correct":0,"explanation":"\\(x^2\\) is the inner function and its derivative \\(2x\\) is present. The answer is \\(\\sin(x^2)+C\\).","slide":null},{"q":"\\(\\int e^{5x}\\,dx=\\)","options":["\\(5e^{5x}+C\\)","\\(e^{5x}+C\\)","\\(\\frac15e^{5x}+C\\)","\\(\\frac{e^{6x}}{6}+C\\)"],"correct":2,"explanation":"Linear inside with \\(a=5\\): divide by 5. \\(5e^{5x}\\) is the derivative.","slide":null},{"q":"Which formula is integration by parts?","options":["\\(\\int u\\,dv=uv+\\int v\\,du\\)","\\(\\int u\\,dv=uv-\\int v\\,du\\)","\\(\\int u\\,dv=u'v-\\int uv'\\,dx\\)","\\(\\int uv\\,dx=\\int u\\,dx\\cdot\\int v\\,dx\\)"],"correct":1,"explanation":"From \\((uv)'=u'v+uv'\\): \\(\\int u\\,dv=uv-\\int v\\,du\\). The sign is minus.","slide":null},{"q":"For \\(\\int x\\ln x\\,dx\\), the best choice is:","options":["\\(u=x,\\ dv=\\ln x\\,dx\\)","substitution \\(t=x\\)","\\(u=x\\ln x,\\ dv=dx\\)","\\(u=\\ln x,\\ dv=x\\,dx\\)"],"correct":3,"explanation":"LIATE: logarithm before algebraic, so \\(u=\\ln x\\). Then \\(du=\\frac1xdx\\) cancels the power nicely.","slide":null},{"q":"\\(\\int xe^x\\,dx=\\)","options":["\\(xe^x+C\\)","\\(\\frac{x^2}{2}e^x+C\\)","\\((x+1)e^x+C\\)","\\((x-1)e^x+C\\)"],"correct":3,"explanation":"Parts with \\(u=x\\): \\(xe^x-\\int e^xdx=xe^x-e^x+C\\).","slide":null},{"q":"\\(\\int \\frac{1}{2x+1}\\,dx=\\)","options":["\\(\\ln|2x+1|+C\\)","\\(\\frac12\\ln|2x+1|+C\\)","\\(2\\ln|2x+1|+C\\)","\\(-\\frac{2}{(2x+1)^2}+C\\)"],"correct":1,"explanation":"Linear inside with \\(a=2\\), so divide \\(\\ln|2x+1|\\) by 2.","slide":null},{"q":"How many times must you integrate by parts to compute \\(\\int x^3e^x\\,dx\\)?","options":["1","2","3","4"],"correct":2,"explanation":"Each step lowers the power of x by one: x³ → x² → x → constant.","slide":null},{"q":"True or false: \\(\\int\\frac{f'(x)}{f(x)}\\,dx=\\ln|f(x)|+C\\).","options":["True","False"],"correct":0,"explanation":"Substitute \\(t=f(x)\\), \\(dt=f'(x)dx\\): \\(\\int\\frac{dt}{t}=\\ln|t|+C\\).","slide":null}],"lang":"en","lesson":{"intro":"Differentiation has the chain rule and the product rule. Integration has a 'reverse' version of each: substitution and integration by parts. Learning when to use which is the main skill of this lesson.","sections":[{"h":"Substitution: the chain rule backwards","body":"If the integrand has the form 'function of an inner part \\(\\times\\) derivative of that inner part', substitute \\(t=g(x)\\). Then \\(dt=g'(x)\\,dx\\) and\n\\[\\int f\\big(g(x)\\big)\\,g'(x)\\,dx=\\int f(t)\\,dt.\\]\nSteps:\n- choose \\(t\\) = the inner function,\n- compute \\(dt\\),\n- rewrite the whole integral in \\(t\\) (no \\(x\\) may remain),\n- integrate, then go back to \\(x\\).","example":{"task":"Compute \\(\\int 2x(x^2+1)^5\\,dx\\).","steps":["Inner function: \\(t=x^2+1\\), so \\(dt=2x\\,dx\\).","The integral becomes \\(\\int t^5\\,dt=\\frac{t^6}{6}+C\\).","Back to \\(x\\): \\(\\frac{(x^2+1)^6}{6}+C\\)."],"answer":"\\(\\frac{(x^2+1)^6}{6}+C\\)"},"tip":"After substituting, check that no \\(x\\) is left. If an \\(x\\) remains, the substitution was not a good choice."},{"h":"Fixing a missing constant, and two useful shortcuts","body":"Often the derivative of the inner part is there only up to a constant factor. That is fine: constants can be moved in and out of the integral.\n\nTwo shortcuts that come from substitution:\n\\[\\int f(ax+b)\\,dx=\\frac{1}{a}F(ax+b)+C,\\qquad \\int\\frac{f'(x)}{f(x)}\\,dx=\\ln|f(x)|+C.\\]\nFor example \\(\\int e^{3x}dx=\\frac13e^{3x}+C\\) and \\(\\int\\frac{2x}{x^2+4}dx=\\ln(x^2+4)+C\\).","example":{"task":"Compute \\(\\int x e^{x^2}\\,dx\\) and \\(\\int (2x+1)^4\\,dx\\).","steps":["First: \\(t=x^2\\), \\(dt=2x\\,dx\\), so \\(x\\,dx=\\frac12dt\\).","\\(\\int e^t\\cdot\\frac12dt=\\frac12e^t+C=\\frac12e^{x^2}+C\\).","Second: linear inside, \\(a=2\\): \\(\\int(2x+1)^4dx=\\frac12\\cdot\\frac{(2x+1)^5}{5}+C\\)."],"answer":"\\(\\frac12e^{x^2}+C\\) and \\(\\frac{(2x+1)^5}{10}+C\\)."},"tip":"You may fix a missing constant factor, but never a missing \\(x\\). \\(\\int e^{x^2}dx\\) cannot be done this way because there is no \\(x\\) next to it."},{"h":"Integration by parts: the product rule backwards","body":"From \\((uv)'=u'v+uv'\\) we get the formula\n\\[\\int u\\,dv=uv-\\int v\\,du.\\]\nYou split the integrand into two parts: \\(u\\) (which you will differentiate) and \\(dv\\) (which you will integrate). The goal is that the new integral \\(\\int v\\,du\\) is easier than the old one.","example":{"task":"Compute \\(\\int x e^x\\,dx\\).","steps":["Choose \\(u=x\\), \\(dv=e^x dx\\).","Then \\(du=dx\\), \\(v=e^x\\).","\\(\\int xe^x dx=xe^x-\\int e^x dx=xe^x-e^x+C\\)."],"answer":"\\((x-1)e^x+C\\)"}},{"h":"How to choose u: the LIATE idea","body":"Pick \\(u\\) as the factor that comes FIRST in this list (it becomes simpler when differentiated):\n- L: logarithms (\\(\\ln x\\))\n- I: inverse trigonometric (\\(\\arctan x\\))\n- A: algebraic, i.e. powers and polynomials (\\(x\\), \\(x^2\\))\n- T: trigonometric (\\(\\sin x\\), \\(\\cos x\\))\n- E: exponential (\\(e^x\\))\nEverything else goes into \\(dv\\). Example: in \\(\\int x\\ln x\\,dx\\), \\(\\ln x\\) (L) beats \\(x\\) (A), so \\(u=\\ln x\\).\n\nA special trick: \\(\\int\\ln x\\,dx\\) has only one factor. Write it as \\(\\int \\ln x\\cdot 1\\,dx\\) with \\(u=\\ln x\\), \\(dv=dx\\).","example":{"task":"Compute \\(\\int x\\ln x\\,dx\\).","steps":["\\(u=\\ln x\\), \\(dv=x\\,dx\\); so \\(du=\\frac1x dx\\), \\(v=\\frac{x^2}{2}\\).","\\(\\int x\\ln x\\,dx=\\frac{x^2}{2}\\ln x-\\int\\frac{x^2}{2}\\cdot\\frac1x\\,dx\\).","\\(=\\frac{x^2}{2}\\ln x-\\int\\frac{x}{2}dx=\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}+C\\)."],"answer":"\\(\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}+C\\)"},"tip":"If you choose \\(u=x\\) and \\(dv=\\ln x\\,dx\\), you need \\(\\int\\ln x\\,dx\\) just to find \\(v\\), so the problem gets harder. That is a sign to swap."},{"h":"Repeated integration by parts","body":"With \\(x^n\\) times \\(e^x\\), \\(\\sin x\\) or \\(\\cos x\\), each use of parts lowers the power of \\(x\\) by one. So \\(x^2e^x\\) needs parts twice, \\(x^3e^x\\) three times. Keep the same type of choice every time (\\(u\\) = the power of \\(x\\)).","example":{"task":"Compute \\(\\int x^2e^x\\,dx\\).","steps":["\\(u=x^2\\), \\(dv=e^xdx\\): \\(\\int x^2e^xdx=x^2e^x-\\int 2xe^xdx\\).","Parts again for \\(\\int 2xe^xdx\\) (\\(u=2x\\)): \\(2xe^x-\\int 2e^xdx=2xe^x-2e^x\\).","Combine: \\(x^2e^x-2xe^x+2e^x+C\\)."],"answer":"\\((x^2-2x+2)e^x+C\\)"},"tip":"Watch the signs: the minus in front of the second integral changes every sign inside it. Check the result by differentiating."}],"formulas":["\\(\\int f(g(x))g'(x)\\,dx=\\int f(t)\\,dt,\\quad t=g(x)\\)","\\(\\int f(ax+b)\\,dx=\\frac1aF(ax+b)+C\\)","\\(\\int \\frac{f'(x)}{f(x)}\\,dx=\\ln|f(x)|+C\\)","\\(\\int e^{ax}\\,dx=\\frac1ae^{ax}+C\\)","\\(\\int u\\,dv=uv-\\int v\\,du\\)","LIATE: choose \\(u\\) in the order Log, Inverse trig, Algebraic, Trig, Exponential","\\(\\int \\ln x\\,dx=x\\ln x-x+C\\)","\\(\\int xe^x\\,dx=(x-1)e^x+C\\)"],"exercises":[{"task":"Compute \\(\\int (3x-2)^5\\,dx\\).","hint":"Linear inside: use \\(\\frac1a F(ax+b)\\).","answer":"\\(\\frac{(3x-2)^6}{18}+C\\)"},{"task":"Compute \\(\\int x^2e^{x^3}\\,dx\\).","hint":"\\(t=x^3\\), \\(dt=3x^2dx\\).","answer":"\\(\\frac13e^{x^3}+C\\)"},{"task":"Compute \\(\\int \\frac{6x+2}{3x^2+2x+5}\\,dx\\).","hint":"Is the numerator the derivative of the denominator?","answer":"\\(\\ln(3x^2+2x+5)+C\\) (the denominator is always positive)."},{"task":"Compute \\(\\int \\frac{\\ln x}{x}\\,dx\\).","hint":"\\(t=\\ln x\\), \\(dt=\\frac1xdx\\).","answer":"\\(\\frac{(\\ln x)^2}{2}+C\\)"},{"task":"Compute \\(\\int x\\cos x\\,dx\\).","hint":"\\(u=x\\), \\(dv=\\cos x\\,dx\\).","answer":"\\(x\\sin x+\\cos x+C\\)"},{"task":"Compute \\(\\int x^3\\ln x\\,dx\\).","hint":"LIATE: \\(u=\\ln x\\).","answer":"\\(\\frac{x^4}{4}\\ln x-\\frac{x^4}{16}+C\\)"},{"task":"Compute \\(\\int x^2e^{-x}\\,dx\\).","hint":"Parts twice, \\(u=x^2\\) then \\(u=x\\). Careful: \\(\\int e^{-x}dx=-e^{-x}\\).","answer":"\\(-(x^2+2x+2)e^{-x}+C\\)"},{"task":"A firm's marginal revenue is \\(MR(q)=\\frac{60}{2q+3}\\). Find total revenue \\(R(q)\\) if \\(R(0)=0\\), and compute \\(R(6)\\).","hint":"\\(t=2q+3\\); then use \\(R(0)=0\\) to find \\(C\\).","answer":"\\(R(q)=30\\ln(2q+3)-30\\ln 3=30\\ln\\frac{2q+3}{3}\\); \\(R(6)=30\\ln5\\approx48.28\\)."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-15-rational-functions', $lekcja${"tldr":"A rational function is a fraction of two polynomials, like \\(\\frac{x+5}{(x-1)(x+2)}\\). There is a fixed recipe to integrate any of them. First, if the top has degree at least as high as the bottom, divide the polynomials. Then factor the denominator and split the fraction into simple partial fractions: distinct linear factors, repeated linear factors and irreducible quadratics each have their own form. Each piece integrates to a logarithm, a power or an arctangent (after completing the square). In economics, marginal cost or revenue functions with fractions are integrated in exactly this way.","notes":[{"point":"A rational function is proper when the degree of the numerator is smaller than the degree of the denominator.","slide":null},{"point":"If the fraction is improper, do polynomial long division before anything else.","slide":null},{"point":"Each distinct linear factor \\((x-a)\\) gives a term \\(\\frac{A}{x-a}\\), which integrates to \\(A\\ln|x-a|\\).","slide":null},{"point":"A repeated factor \\((x-a)^2\\) gives two terms: \\(\\frac{A}{x-a}+\\frac{B}{(x-a)^2}\\).","slide":null},{"point":"Cover-up method: multiply by the denominator and substitute the roots to find the constants quickly.","slide":null},{"point":"A quadratic with \\(\\Delta<0\\) cannot be factored; complete the square and use arctan.","slide":null},{"point":"\\(\\int\\frac{1}{x^2+b^2}dx=\\frac1b\\arctan\\frac xb+C\\); do not forget the factor \\(\\frac1b\\).","slide":null},{"point":"With x in the numerator over an irreducible quadratic, first split off a multiple of the denominator's derivative (gives ln).","slide":null}],"concepts":[{"term":"Rational function","definition":"A quotient of two polynomials, \\(\\frac{P(x)}{Q(x)}\\).","pl":"funkcja wymierna","slide":null},{"term":"Proper rational function","definition":"A rational function whose numerator has lower degree than its denominator.","pl":"funkcja wymierna właściwa","slide":null},{"term":"Polynomial long division","definition":"Dividing one polynomial by another to get a polynomial part and a proper remainder fraction.","pl":"dzielenie wielomianów","slide":null},{"term":"Partial fractions","definition":"Simple fractions whose sum equals a given proper rational function.","pl":"ułamki proste","slide":null},{"term":"Partial fraction decomposition","definition":"Writing a proper rational function as a sum of partial fractions so each piece is easy to integrate.","pl":"rozkład na ułamki proste","slide":null},{"term":"Irreducible quadratic","definition":"A quadratic \\(x^2+px+q\\) with negative discriminant; it has no real roots and cannot be factored.","pl":"trójmian kwadratowy nierozkładalny","slide":null},{"term":"Completing the square","definition":"Rewriting \\(x^2+px+q\\) as \\(\\left(x+\\frac p2\\right)^2+\\text{constant}\\).","pl":"sprowadzanie do postaci kanonicznej","slide":null}],"flashcards":[{"q":"When must you divide polynomials first?","a":"When deg(numerator) ≥ deg(denominator).","slide":null},{"q":"\\(\\int\\frac{A}{x-a}dx\\)?","a":"\\(A\\ln|x-a|+C\\)","slide":null},{"q":"Partial fraction form of \\(\\frac{P}{(x-a)(x-b)}\\)?","a":"\\(\\frac{A}{x-a}+\\frac{B}{x-b}\\)","slide":null},{"q":"Partial fraction form of \\(\\frac{P}{(x-a)^2}\\) (proper)?","a":"\\(\\frac{A}{x-a}+\\frac{B}{(x-a)^2}\\)","slide":null},{"q":"\\(\\int\\frac{dx}{x^2+b^2}\\)?","a":"\\(\\frac1b\\arctan\\frac xb+C\\)","slide":null},{"q":"How do you know a quadratic is irreducible?","a":"Its discriminant is negative, \\(\\Delta<0\\).","slide":null},{"q":"Complete the square: \\(x^2+4x+13\\)","a":"\\((x+2)^2+9\\)","slide":null},{"q":"\\(\\int\\frac{1}{(x-a)^2}dx\\)?","a":"\\(-\\frac{1}{x-a}+C\\)","slide":null},{"q":"What is the cover-up method?","a":"Multiply by the denominator and substitute each root to find each constant.","slide":null}],"quiz":[{"q":"Which of these needs polynomial division before partial fractions?","options":["\\(\\frac{x+1}{x^2+1}\\)","\\(\\frac{x^3+1}{x^2+1}\\)","\\(\\frac{3}{x-2}\\)","\\(\\frac{2x}{x^2+4}\\)"],"correct":1,"explanation":"Degree 3 over degree 2 is improper, so divide first.","slide":null},{"q":"The correct partial fraction form of \\(\\frac{1}{(x-1)(x+3)}\\) is:","options":["\\(\\frac{A}{x-1}+\\frac{B}{x+3}\\)","\\(\\frac{Ax+B}{(x-1)(x+3)}\\)","\\(\\frac{A}{x-1}\\cdot\\frac{B}{x+3}\\)","\\(\\frac{A}{(x-1)^2}+\\frac{B}{x+3}\\)"],"correct":0,"explanation":"Two distinct linear factors give two simple fractions with constant numerators.","slide":null},{"q":"The correct form for \\(\\frac{x+2}{(x-1)^2(x+4)}\\) is:","options":["\\(\\frac{A}{(x-1)^2}+\\frac{B}{x+4}\\)","\\(\\frac{A}{x-1}+\\frac{B}{x+4}\\)","\\(\\frac{Ax+B}{(x-1)^2}\\)","\\(\\frac{A}{x-1}+\\frac{B}{(x-1)^2}+\\frac{C}{x+4}\\)"],"correct":3,"explanation":"The repeated factor \\((x-1)^2\\) needs one term for each power, plus one for \\(x+4\\).","slide":null},{"q":"\\(\\int\\frac{1}{x^2+9}\\,dx=\\)","options":["\\(\\arctan\\frac x3+C\\)","\\(\\frac13\\arctan\\frac x3+C\\)","\\(\\ln(x^2+9)+C\\)","\\(\\frac19\\arctan\\frac x9+C\\)"],"correct":1,"explanation":"With \\(b=3\\): \\(\\frac1b\\arctan\\frac xb\\). Forgetting the \\(\\frac13\\) is the typical mistake.","slide":null},{"q":"Completing the square, \\(x^2+6x+13=\\)","options":["\\((x+3)^2+13\\)","\\((x+6)^2-23\\)","\\((x+3)^2+4\\)","\\((x-3)^2+4\\)"],"correct":2,"explanation":"\\((x+3)^2=x^2+6x+9\\), and \\(13-9=4\\).","slide":null},{"q":"In \\(\\frac{1}{(x-2)(x+2)}=\\frac{A}{x-2}+\\frac{B}{x+2}\\), the value of \\(A\\) is:","options":["\\(\\frac14\\)","\\(-\\frac14\\)","\\(\\frac12\\)","\\(1\\)"],"correct":0,"explanation":"\\(1=A(x+2)+B(x-2)\\); put \\(x=2\\): \\(1=4A\\).","slide":null},{"q":"\\(\\int\\frac{3}{(x-2)^2}\\,dx=\\)","options":["\\(3\\ln(x-2)^2+C\\)","\\(\\frac{3}{x-2}+C\\)","\\(-\\frac{6}{(x-2)^3}+C\\)","\\(-\\frac{3}{x-2}+C\\)"],"correct":3,"explanation":"Power rule with \\((x-2)^{-2}\\): \\(3\\cdot\\frac{(x-2)^{-1}}{-1}\\). It is not a logarithm.","slide":null},{"q":"True or false: \\(x^2+4x+5\\) can be written as a product of two real linear factors.","options":["True","False"],"correct":1,"explanation":"\\(\\Delta=16-20=-4<0\\), so it is irreducible: \\((x+2)^2+1\\).","slide":null}],"lang":"en","lesson":{"intro":"Fractions of polynomials look scary, but integrating them is a step-by-step recipe. Learn the recipe once and you can do every exam task of this type.","sections":[{"h":"Step 1: proper or improper? Divide if needed","body":"A rational function \\(\\frac{P(x)}{Q(x)}\\) is proper if \\(\\deg P<\\deg Q\\). If \\(\\deg P\\ge\\deg Q\\), it is improper: first do polynomial long division to write\n\\[\\frac{P(x)}{Q(x)}=W(x)+\\frac{R(x)}{Q(x)},\\]\nwhere \\(W\\) is a polynomial (easy to integrate) and \\(\\frac{R}{Q}\\) is proper.","example":{"task":"Compute \\(\\int \\frac{x^2+3x+5}{x+1}\\,dx\\).","steps":["Degree 2 over degree 1: improper, so divide.","\\(x^2+3x+5=(x+1)(x+2)+3\\), so \\(\\frac{x^2+3x+5}{x+1}=x+2+\\frac{3}{x+1}\\).","Integrate: \\(\\frac{x^2}{2}+2x+3\\ln|x+1|+C\\)."],"answer":"\\(\\frac{x^2}{2}+2x+3\\ln|x+1|+C\\)"},"tip":"Always compare degrees first. Partial fractions only work for proper fractions."},{"h":"The building blocks","body":"After splitting, every piece is one of these simple types:\n\\[\\int\\frac{A}{x-a}\\,dx=A\\ln|x-a|+C\\]\n\\[\\int\\frac{A}{(x-a)^k}\\,dx=-\\frac{A}{(k-1)(x-a)^{k-1}}+C\\quad(k\\ge2)\\]\n\\[\\int\\frac{1}{(x+p)^2+b^2}\\,dx=\\frac1b\\arctan\\frac{x+p}{b}+C\\]\nThe last one is used for quadratics that cannot be factored (negative discriminant).","example":{"task":"Compute \\(\\int\\frac{3}{(x-2)^2}\\,dx\\) and \\(\\int\\frac{1}{x^2+9}\\,dx\\).","steps":["First: \\(3\\int(x-2)^{-2}dx=3\\cdot\\frac{(x-2)^{-1}}{-1}=-\\frac{3}{x-2}+C\\).","Second: \\(x^2+9=x^2+3^2\\), so \\(b=3\\), \\(p=0\\).","\\(\\int\\frac{1}{x^2+9}dx=\\frac13\\arctan\\frac{x}{3}+C\\)."],"answer":"\\(-\\frac{3}{x-2}+C\\) and \\(\\frac13\\arctan\\frac x3+C\\)."}},{"h":"Partial fractions: distinct linear factors","body":"If the denominator factors into different linear factors, write\n\\[\\frac{P(x)}{(x-a)(x-b)}=\\frac{A}{x-a}+\\frac{B}{x-b}.\\]\nTo find \\(A\\) and \\(B\\): multiply both sides by the denominator, then put \\(x=a\\) and \\(x=b\\) (each choice kills one term). This is the quick 'cover-up' method.","example":{"task":"Compute \\(\\int\\frac{x+5}{(x-1)(x+2)}\\,dx\\).","steps":["Write \\(\\frac{x+5}{(x-1)(x+2)}=\\frac{A}{x-1}+\\frac{B}{x+2}\\), so \\(x+5=A(x+2)+B(x-1)\\).","\\(x=1\\): \\(6=3A\\), so \\(A=2\\). \\(x=-2\\): \\(3=-3B\\), so \\(B=-1\\).","\\(\\int\\left(\\frac{2}{x-1}-\\frac{1}{x+2}\\right)dx=2\\ln|x-1|-\\ln|x+2|+C\\)."],"answer":"\\(2\\ln|x-1|-\\ln|x+2|+C\\)"},"tip":"If the denominator is not factored yet, factor it first, e.g. \\(x^2+3x+2=(x+1)(x+2)\\)."},{"h":"Repeated linear factor","body":"A factor \\((x-a)^2\\) needs TWO fractions, one for each power:\n\\[\\frac{P(x)}{(x-a)^2(x-b)}=\\frac{A}{x-a}+\\frac{B}{(x-a)^2}+\\frac{C}{x-b}.\\]\nThe cover-up trick gives \\(B\\) and \\(C\\). For the remaining constant, compare the coefficients of the highest power of \\(x\\) (or put in any other easy value such as \\(x=0\\)).","example":{"task":"Compute \\(\\int\\frac{x+3}{x(x+1)^2}\\,dx\\).","steps":["\\(\\frac{x+3}{x(x+1)^2}=\\frac{A}{x}+\\frac{B}{x+1}+\\frac{D}{(x+1)^2}\\), so \\(x+3=A(x+1)^2+Bx(x+1)+Dx\\).","\\(x=0\\): \\(3=A\\). \\(x=-1\\): \\(2=-D\\), so \\(D=-2\\).","Coefficient of \\(x^2\\): \\(0=A+B\\), so \\(B=-3\\).","Integrate: \\(3\\ln|x|-3\\ln|x+1|+\\frac{2}{x+1}+C\\)."],"answer":"\\(3\\ln|x|-3\\ln|x+1|+\\frac{2}{x+1}+C\\)"},"tip":"A common mistake is writing only \\(\\frac{B}{(x+1)^2}\\) and forgetting \\(\\frac{A}{x+1}\\). Each power up to the highest needs its own term."},{"h":"Irreducible quadratic: complete the square","body":"If \\(x^2+px+q\\) has \\(\\Delta<0\\), it cannot be factored. Then:\n- if the numerator contains \\(x\\), first split off a multiple of the derivative \\(2x+p\\) of the denominator; that part gives \\(\\ln(x^2+px+q)\\),\n- complete the square in the rest: \\(x^2+px+q=\\left(x+\\frac p2\\right)^2+b^2\\),\n- use the arctan building block.","example":{"task":"Compute \\(\\int\\frac{2x+7}{x^2+4x+13}\\,dx\\).","steps":["Derivative of the denominator: \\(2x+4\\). So \\(2x+7=(2x+4)+3\\).","\\(\\int\\frac{2x+4}{x^2+4x+13}dx=\\ln(x^2+4x+13)\\) (the denominator is always positive).","Complete the square: \\(x^2+4x+13=(x+2)^2+9\\), so \\(\\int\\frac{3}{(x+2)^2+3^2}dx=3\\cdot\\frac13\\arctan\\frac{x+2}{3}\\).","Add the parts and one constant."],"answer":"\\(\\ln(x^2+4x+13)+\\arctan\\frac{x+2}{3}+C\\)"},"tip":"Check \\(\\Delta=p^2-4q\\) first. If \\(\\Delta\\ge0\\), factor the quadratic and use linear partial fractions instead."}],"formulas":["\\(\\frac{P}{Q}=W+\\frac{R}{Q}\\) when \\(\\deg P\\ge\\deg Q\\)","\\(\\int\\frac{A}{x-a}dx=A\\ln|x-a|+C\\)","\\(\\int\\frac{A}{(x-a)^k}dx=-\\frac{A}{(k-1)(x-a)^{k-1}}+C,\\ k\\ge2\\)","\\(\\frac{P(x)}{(x-a)(x-b)}=\\frac{A}{x-a}+\\frac{B}{x-b}\\)","\\(\\frac{P(x)}{(x-a)^2(x-b)}=\\frac{A}{x-a}+\\frac{B}{(x-a)^2}+\\frac{C}{x-b}\\)","\\(x^2+px+q=\\left(x+\\frac p2\\right)^2+\\left(q-\\frac{p^2}{4}\\right)\\)","\\(\\int\\frac{dx}{(x+p)^2+b^2}=\\frac1b\\arctan\\frac{x+p}{b}+C\\)","\\(\\int\\frac{2x+p}{x^2+px+q}dx=\\ln|x^2+px+q|+C\\)"],"exercises":[{"task":"Compute \\(\\int\\frac{x^2+1}{x-1}\\,dx\\).","hint":"Divide: \\(x^2+1=(x-1)(x+1)+2\\).","answer":"\\(\\frac{x^2}{2}+x+2\\ln|x-1|+C\\)"},{"task":"Compute \\(\\int\\frac{1}{x^2-4}\\,dx\\).","hint":"\\(x^2-4=(x-2)(x+2)\\).","answer":"\\(\\frac14\\ln\\left|\\frac{x-2}{x+2}\\right|+C\\) (from \\(A=\\frac14\\), \\(B=-\\frac14\\))."},{"task":"Compute \\(\\int\\frac{3x+5}{x^2+3x+2}\\,dx\\).","hint":"Factor the denominator: \\((x+1)(x+2)\\).","answer":"\\(2\\ln|x+1|+\\ln|x+2|+C\\)"},{"task":"Compute \\(\\int\\frac{2x+3}{(x+1)^2}\\,dx\\).","hint":"Write \\(2x+3=2(x+1)+1\\).","answer":"\\(2\\ln|x+1|-\\frac{1}{x+1}+C\\)"},{"task":"Compute \\(\\int\\frac{1}{x^2+2x+5}\\,dx\\).","hint":"\\(x^2+2x+5=(x+1)^2+4\\).","answer":"\\(\\frac12\\arctan\\frac{x+1}{2}+C\\)"},{"task":"Compute \\(\\int\\frac{x+5}{x^2+2x+5}\\,dx\\).","hint":"\\(x+5=\\frac12(2x+2)+4\\).","answer":"\\(\\frac12\\ln(x^2+2x+5)+2\\arctan\\frac{x+1}{2}+C\\)"},{"task":"Compute \\(\\int\\frac{x^3}{x^2+1}\\,dx\\).","hint":"Divide: \\(\\frac{x^3}{x^2+1}=x-\\frac{x}{x^2+1}\\).","answer":"\\(\\frac{x^2}{2}-\\frac12\\ln(x^2+1)+C\\)"},{"task":"A firm has marginal cost \\(MC(q)=10+\\frac{8}{(q+1)(q+3)}\\) and fixed cost 100. Find \\(TC(q)\\) and \\(TC(9)\\).","hint":"\\(\\frac{8}{(q+1)(q+3)}=\\frac{4}{q+1}-\\frac{4}{q+3}\\); then use \\(TC(0)=100\\).","answer":"\\(TC(q)=10q+4\\ln\\frac{3(q+1)}{q+3}+100\\); \\(TC(9)=190+4\\ln2.5\\approx193.67\\)."}]}}$lekcja$::jsonb)
