insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-16-definite-integral', $lekcja${"tldr":"The definite integral \\(\\int_a^b f(x)\\,dx\\) is a number, not a family of functions. The Newton–Leibniz formula computes it from any antiderivative: \\(F(b)-F(a)\\). For a non-negative function it equals the area under the graph; parts below the x-axis count as negative, so for true area you split at the zeros. The area between two curves is the integral of (top minus bottom). In economics, definite integrals give consumer surplus and producer surplus, which measure the gains from trade at the market equilibrium.","notes":[{"point":"A definite integral is a number: \\(\\int_a^b f\\,dx=F(b)-F(a)\\) for any antiderivative \\(F\\).","slide":null},{"point":"The constant C cancels in a definite integral, so you do not write it.","slide":null},{"point":"Swapping the limits changes the sign; equal limits give zero; the interval can be split at any point.","slide":null},{"point":"With substitution in a definite integral, change the limits to the new variable.","slide":null},{"point":"The integral counts area below the x-axis as negative. For geometric area, split at the zeros and add absolute values.","slide":null},{"point":"Area between curves = integral of (top minus bottom) between the intersection points.","slide":null},{"point":"Consumer surplus: \\(CS=\\int_0^{q_0}D(q)\\,dq-p_0q_0\\) (area between demand and the price line).","slide":null},{"point":"Producer surplus: \\(PS=p_0q_0-\\int_0^{q_0}S(q)\\,dq\\) (area between the price line and supply).","slide":null},{"point":"With linear demand and supply, CS and PS are triangles; you can check your integrals with ½ · base · height.","slide":null}],"concepts":[{"term":"Definite integral","definition":"The number \\(\\int_a^b f(x)\\,dx\\), the limit of sums of rectangle areas under the graph on \\([a,b]\\).","pl":"całka oznaczona","slide":null},{"term":"Limits of integration","definition":"The endpoints \\(a\\) (lower) and \\(b\\) (upper) of the interval of integration.","pl":"granice całkowania","slide":null},{"term":"Newton–Leibniz formula","definition":"\\(\\int_a^b f(x)\\,dx=F(b)-F(a)\\), where \\(F\\) is an antiderivative of \\(f\\).","pl":"wzór Newtona–Leibniza","slide":null},{"term":"Area under a curve","definition":"The area between the graph of \\(f\\) and the x-axis; equal to \\(\\int_a^b|f(x)|\\,dx\\).","pl":"pole pod wykresem funkcji","slide":null},{"term":"Area between curves","definition":"\\(\\int_a^b(f-g)\\,dx\\) when \\(f\\ge g\\) on \\([a,b]\\).","pl":"pole obszaru między krzywymi","slide":null},{"term":"Market equilibrium","definition":"The quantity and price where demand equals supply.","pl":"równowaga rynkowa","slide":null},{"term":"Consumer surplus","definition":"The total gain of buyers who would have paid more than the market price.","pl":"nadwyżka konsumenta","slide":null},{"term":"Producer surplus","definition":"The total gain of sellers who would have accepted less than the market price.","pl":"nadwyżka producenta","slide":null}],"flashcards":[{"q":"Newton–Leibniz formula?","a":"\\(\\int_a^b f\\,dx=F(b)-F(a)\\)","slide":null},{"q":"\\(\\int_b^a f\\,dx\\) in terms of \\(\\int_a^b f\\,dx\\)?","a":"\\(-\\int_a^b f\\,dx\\)","slide":null},{"q":"\\(\\int_a^a f\\,dx\\)?","a":"0","slide":null},{"q":"What happens to the limits when you substitute t = g(x)?","a":"They become g(a) and g(b).","slide":null},{"q":"How do you get geometric area when f changes sign?","a":"Split at the zeros and add absolute values of each piece.","slide":null},{"q":"Area between two curves?","a":"\\(\\int_a^b(\\text{top}-\\text{bottom})\\,dx\\)","slide":null},{"q":"Consumer surplus formula?","a":"\\(\\int_0^{q_0}D(q)\\,dq-p_0q_0\\)","slide":null},{"q":"Producer surplus formula?","a":"\\(p_0q_0-\\int_0^{q_0}S(q)\\,dq\\)","slide":null},{"q":"\\(\\int_0^1x^2\\,dx\\)?","a":"\\(\\frac13\\)","slide":null},{"q":"How do you find the limits for the area between two curves?","a":"Solve f(x) = g(x).","slide":null}],"quiz":[{"q":"\\(\\int_0^1x^2\\,dx=\\)","options":["\\(\\frac12\\)","\\(\\frac13\\)","\\(1\\)","\\(2\\)"],"correct":1,"explanation":"\\(\\Big[\\frac{x^3}{3}\\Big]_0^1=\\frac13\\).","slide":null},{"q":"If \\(\\int_3^1 f(x)\\,dx=5\\), then \\(\\int_1^3 f(x)\\,dx=\\)","options":["\\(5\\)","\\(\\frac15\\)","\\(-5\\)","\\(0\\)"],"correct":2,"explanation":"Swapping the limits changes the sign.","slide":null},{"q":"\\(\\int_{-1}^0f\\,dx=3\\) and \\(\\int_0^2f\\,dx=-1\\). Then \\(\\int_{-1}^2f\\,dx=\\)","options":["\\(2\\)","\\(4\\)","\\(-3\\)","\\(-4\\)"],"correct":0,"explanation":"Additivity: \\(3+(-1)=2\\).","slide":null},{"q":"In \\(\\int_0^2 x(x^2+1)^4\\,dx\\) you substitute \\(t=x^2+1\\). The new limits are:","options":["from 0 to 2","from 0 to 4","from 1 to 4","from 1 to 5"],"correct":3,"explanation":"\\(x=0\\Rightarrow t=1\\); \\(x=2\\Rightarrow t=5\\).","slide":null},{"q":"The area between \\(y=x\\) and \\(y=x^2\\) for \\(0\\le x\\le1\\) is:","options":["\\(\\frac12\\)","\\(\\frac13\\)","\\(\\frac16\\)","\\(\\frac56\\)"],"correct":2,"explanation":"\\(\\int_0^1(x-x^2)\\,dx=\\frac12-\\frac13=\\frac16\\). On \\([0,1]\\) the line is above the parabola.","slide":null},{"q":"True or false: \\(\\int_a^b f(x)\\,dx\\) always equals the area between the graph of \\(f\\) and the x-axis.","options":["True","False"],"correct":1,"explanation":"Parts below the axis count as negative. For example \\(\\int_{-1}^1x^3\\,dx=0\\), but the area is \\(\\frac12\\).","slide":null},{"q":"Consumer surplus at equilibrium \\((q_0,p_0)\\) with demand \\(D(q)\\) equals:","options":["\\(p_0q_0-\\int_0^{q_0}D(q)\\,dq\\)","\\(\\int_0^{q_0}D(q)\\,dq\\)","\\(\\int_0^{p_0}D(q)\\,dq-q_0\\)","\\(\\int_0^{q_0}D(q)\\,dq-p_0q_0\\)"],"correct":3,"explanation":"It is the area under the demand curve minus the amount actually paid (rectangle p₀q₀).","slide":null},{"q":"Demand is \\(D(q)=20-q\\) and the equilibrium is \\(q_0=8,\\ p_0=12\\). Consumer surplus is:","options":["\\(32\\)","\\(64\\)","\\(96\\)","\\(128\\)"],"correct":0,"explanation":"\\(\\int_0^8(20-q)\\,dq-96=128-96=32\\) (a triangle \\(\\frac12\\cdot8\\cdot8\\)).","slide":null}],"lang":"en","lesson":{"intro":"The indefinite integral gave us a formula. The definite integral gives us a number: a total amount, such as an area, a total cost between two output levels, or the extra benefit consumers get from a market.","sections":[{"h":"Newton–Leibniz formula","body":"The definite integral of \\(f\\) from \\(a\\) to \\(b\\) can be thought of as the limit of sums of thin rectangles under the graph. You never need to compute those sums in practice, because of the Newton–Leibniz formula (the fundamental theorem of calculus): if \\(F'=f\\) and \\(f\\) is continuous on \\([a,b]\\), then\n\\[\\int_a^b f(x)\\,dx=\\Big[F(x)\\Big]_a^b=F(b)-F(a).\\]\nThe numbers \\(a\\) and \\(b\\) are the lower and upper limits of integration. The constant \\(C\\) cancels, so you can leave it out.","example":{"task":"Compute \\(\\int_1^3(2x+1)\\,dx\\).","steps":["Antiderivative: \\(F(x)=x^2+x\\).","\\(F(3)=9+3=12\\), \\(F(1)=1+1=2\\).","\\(\\int_1^3(2x+1)\\,dx=12-2=10\\)."],"answer":"\\(10\\)"},"tip":"Always write the bracket \\(\\big[F(x)\\big]_a^b\\) and then compute \\(F(b)-F(a)\\) in brackets: the minus sign applies to every term of \\(F(a)\\)."},{"h":"Properties of the definite integral","body":"Useful rules (for continuous \\(f,g\\)):\n- \\(\\int_a^a f(x)\\,dx=0\\)\n- \\(\\int_b^a f(x)\\,dx=-\\int_a^b f(x)\\,dx\\) (swapping limits changes the sign)\n- \\(\\int_a^b f\\,dx=\\int_a^c f\\,dx+\\int_c^b f\\,dx\\) (you can split the interval)\n- \\(\\int_a^b(\\alpha f+\\beta g)\\,dx=\\alpha\\int_a^b f\\,dx+\\beta\\int_a^b g\\,dx\\)\n- if \\(f(x)\\ge0\\) on \\([a,b]\\), then \\(\\int_a^b f\\,dx\\ge0\\)\nSplitting the interval is very useful for absolute values and piecewise functions.","example":{"task":"Compute \\(\\int_0^2|x-1|\\,dx\\).","steps":["\\(|x-1|=1-x\\) for \\(x\\le1\\) and \\(x-1\\) for \\(x\\ge1\\). Split at 1.","\\(\\int_0^1(1-x)\\,dx=\\Big[x-\\frac{x^2}{2}\\Big]_0^1=\\frac12\\).","\\(\\int_1^2(x-1)\\,dx=\\Big[\\frac{x^2}{2}-x\\Big]_1^2=0-\\left(-\\frac12\\right)=\\frac12\\).","Sum: \\(\\frac12+\\frac12\\)."],"answer":"\\(1\\)"}},{"h":"Substitution and parts in definite integrals","body":"With substitution \\(t=g(x)\\), change the limits too: \\(x=a\\) becomes \\(t=g(a)\\) and \\(x=b\\) becomes \\(t=g(b)\\). Then you never need to go back to \\(x\\):\n\\[\\int_a^b f\\big(g(x)\\big)g'(x)\\,dx=\\int_{g(a)}^{g(b)}f(t)\\,dt.\\]\nFor integration by parts: \\(\\int_a^b u\\,dv=\\Big[uv\\Big]_a^b-\\int_a^b v\\,du\\).","example":{"task":"Compute \\(\\int_0^1 2x(x^2+1)^3\\,dx\\) and \\(\\int_0^1 xe^x\\,dx\\).","steps":["First: \\(t=x^2+1\\), \\(dt=2x\\,dx\\). New limits: \\(x=0\\Rightarrow t=1\\), \\(x=1\\Rightarrow t=2\\).","\\(\\int_1^2t^3\\,dt=\\Big[\\frac{t^4}{4}\\Big]_1^2=4-\\frac14=\\frac{15}{4}\\).","Second: by parts \\(\\int xe^xdx=(x-1)e^x\\), so \\(\\Big[(x-1)e^x\\Big]_0^1=0-(-1)=1\\)."],"answer":"\\(\\frac{15}{4}\\) and \\(1\\)."},"tip":"If you change the variable, change the limits. Mixing new variable \\(t\\) with old limits for \\(x\\) is a very common error."},{"h":"Area under a curve","body":"If \\(f(x)\\ge0\\) on \\([a,b]\\), then \\(\\int_a^b f(x)\\,dx\\) is the area between the graph and the x-axis.\n\nIf \\(f\\) is below the axis, the integral is negative. To get the area (always positive):\n- find the zeros of \\(f\\) in \\([a,b]\\),\n- integrate separately on each piece,\n- add the absolute values.\n\\[\\text{Area}=\\int_a^b|f(x)|\\,dx\\]","example":{"task":"Find the area between \\(y=x^2-4\\) and the x-axis for \\(0\\le x\\le3\\).","steps":["Zero in the interval: \\(x=2\\). For \\(0<x<2\\) the function is negative, for \\(2<x<3\\) positive.","\\(\\int_0^2(x^2-4)\\,dx=\\frac83-8=-\\frac{16}{3}\\), so that piece has area \\(\\frac{16}{3}\\).","\\(\\int_2^3(x^2-4)\\,dx=(9-12)-\\left(\\frac83-8\\right)=\\frac73\\).","Area \\(=\\frac{16}{3}+\\frac73=\\frac{23}{3}\\). (Compare: \\(\\int_0^3(x^2-4)\\,dx=-3\\), not an area.)"],"answer":"\\(\\frac{23}{3}\\approx7.67\\)"}},{"h":"Area between two curves","body":"If \\(f(x)\\ge g(x)\\) on \\([a,b]\\), the area between the graphs is\n\\[\\int_a^b\\big(f(x)-g(x)\\big)\\,dx\\quad(\\text{top minus bottom}).\\]\nIf the limits are not given, find them by solving \\(f(x)=g(x)\\). To see which curve is on top, test one point between the intersections.","example":{"task":"Find the area between \\(y=4x-x^2\\) and \\(y=x\\).","steps":["Intersections: \\(4x-x^2=x\\iff x^2-3x=0\\iff x=0\\) or \\(x=3\\).","Test \\(x=1\\): \\(4-1=3>1\\), so the parabola is on top.","\\(\\int_0^3\\big((4x-x^2)-x\\big)\\,dx=\\int_0^3(3x-x^2)\\,dx=\\Big[\\frac{3x^2}{2}-\\frac{x^3}{3}\\Big]_0^3=\\frac{27}{2}-9\\)."],"answer":"\\(\\frac92\\)"}},{"h":"Economics: consumer and producer surplus","body":"Let \\(p=D(q)\\) be the demand curve and \\(p=S(q)\\) the supply curve. At the equilibrium \\((q_0,p_0)\\) we have \\(D(q_0)=S(q_0)=p_0\\).\n- Consumer surplus: buyers who were willing to pay more than \\(p_0\\) gain. It is the area between the demand curve and the line \\(p=p_0\\):\n\\[CS=\\int_0^{q_0}D(q)\\,dq-p_0q_0.\\]\n- Producer surplus: sellers who would accept less than \\(p_0\\) gain. It is the area between \\(p=p_0\\) and the supply curve:\n\\[PS=p_0q_0-\\int_0^{q_0}S(q)\\,dq.\\]","example":{"task":"Demand: \\(D(q)=100-q^2\\), supply: \\(S(q)=20+2q\\). Find the equilibrium, CS and PS.","steps":["Equilibrium: \\(100-q^2=20+2q\\iff q^2+2q-80=0\\iff q=8\\) (the root \\(-10\\) makes no sense). Then \\(p_0=36\\), and \\(p_0q_0=288\\).","\\(\\int_0^8(100-q^2)\\,dq=800-\\frac{512}{3}\\), so \\(CS=800-\\frac{512}{3}-288=\\frac{1024}{3}\\approx341.33\\).","\\(\\int_0^8(20+2q)\\,dq=160+64=224\\), so \\(PS=288-224=64\\)."],"answer":"\\(q_0=8,\\ p_0=36,\\ CS=\\frac{1024}{3}\\approx341.33,\\ PS=64\\)."},"tip":"Both surpluses are always positive. If you get a negative number, you probably swapped the order of subtraction."}],"formulas":["\\(\\int_a^b f(x)\\,dx=F(b)-F(a)\\)","\\(\\int_b^a f\\,dx=-\\int_a^b f\\,dx,\\quad \\int_a^a f\\,dx=0\\)","\\(\\int_a^b f\\,dx=\\int_a^c f\\,dx+\\int_c^b f\\,dx\\)","\\(\\int_a^b f(g(x))g'(x)\\,dx=\\int_{g(a)}^{g(b)}f(t)\\,dt\\)","\\(\\int_a^b u\\,dv=\\big[uv\\big]_a^b-\\int_a^b v\\,du\\)","\\(\\text{Area}=\\int_a^b|f(x)|\\,dx\\)","\\(\\text{Area between curves}=\\int_a^b\\big(f(x)-g(x)\\big)\\,dx,\\ f\\ge g\\)","\\(CS=\\int_0^{q_0}D(q)\\,dq-p_0q_0\\)","\\(PS=p_0q_0-\\int_0^{q_0}S(q)\\,dq\\)"],"exercises":[{"task":"Compute \\(\\int_0^2(3x^2-2x+1)\\,dx\\).","hint":"Antiderivative \\(x^3-x^2+x\\).","answer":"\\(6\\)"},{"task":"Compute \\(\\int_1^e\\frac1x\\,dx\\).","hint":"\\(\\ln e=1\\), \\(\\ln1=0\\).","answer":"\\(1\\)"},{"task":"Compute \\(\\int_0^1e^{2x}\\,dx\\).","hint":"Antiderivative \\(\\frac12e^{2x}\\).","answer":"\\(\\frac{e^2-1}{2}\\approx3.19\\)"},{"task":"Compute \\(\\int_0^3x\\sqrt{x^2+16}\\,dx\\).","hint":"\\(t=x^2+16\\); limits become 16 and 25.","answer":"\\(\\frac12\\int_{16}^{25}t^{1/2}dt=\\frac13(125-64)=\\frac{61}{3}\\)"},{"task":"Compute \\(\\int_1^e\\ln x\\,dx\\).","hint":"By parts: \\(\\int\\ln x\\,dx=x\\ln x-x\\).","answer":"\\((e-e)-(0-1)=1\\)"},{"task":"Find the area between \\(y=x^2\\) and \\(y=2x\\).","hint":"They meet at \\(x=0\\) and \\(x=2\\); the line is on top.","answer":"\\(\\int_0^2(2x-x^2)\\,dx=\\frac43\\)"},{"task":"Find the area between \\(y=x^2-1\\) and the x-axis for \\(0\\le x\\le2\\).","hint":"Split at \\(x=1\\), where the function changes sign.","answer":"\\(\\frac23+\\frac43=2\\)"},{"task":"Demand \\(D(q)=50-2q\\), supply \\(S(q)=10+3q\\). Find the equilibrium, consumer surplus and producer surplus.","hint":"Solve D(q) = S(q) first.","answer":"\\(q_0=8,\\ p_0=34\\); \\(CS=336-272=64\\); \\(PS=272-176=96\\)."}]}}$lekcja$::jsonb)
