insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-17-improper-integrals', $lekcja${"tldr":"An improper integral has an infinite limit, like \\(\\int_1^\\infty\\frac{1}{x^2}dx\\), or an integrand that becomes infinite, like \\(\\int_0^1\\frac{1}{\\sqrt x}dx\\). We compute it as a limit of ordinary definite integrals. If the limit is a finite number, the integral converges; otherwise it diverges. The p-test tells you at once when \\(\\int\\frac{1}{x^p}dx\\) converges. In economics, the present value of an income stream that lasts forever is \\(\\int_0^\\infty Re^{-rt}dt=\\frac{R}{r}\\), a finite amount.","notes":[{"point":"An improper integral is computed as a limit of ordinary definite integrals.","slide":null},{"point":"Converges = the limit is a finite number. Diverges = the limit is infinite or does not exist.","slide":null},{"point":"\\(\\int_1^\\infty\\frac{dx}{x^p}\\) converges only for \\(p>1\\); \\(\\int_0^1\\frac{dx}{x^p}\\) converges only for \\(p<1\\); \\(p=1\\) always diverges.","slide":null},{"point":"\\(\\int_{-\\infty}^{\\infty}\\) must be split into two parts; if either part diverges, the whole integral diverges.","slide":null},{"point":"If the integrand is unbounded at a point inside the interval, split there; Newton–Leibniz cannot be used across that point.","slide":null},{"point":"f(x) → 0 at infinity does not guarantee convergence (example: 1/x).","slide":null},{"point":"\\(\\int_0^\\infty e^{-ax}dx=\\frac1a\\) for \\(a>0\\).","slide":null},{"point":"Present value of a perpetual income stream: \\(\\int_0^\\infty Re^{-rt}dt=\\frac Rr\\); with growth rate \\(g<r\\) it is \\(\\frac{R}{r-g}\\).","slide":null}],"concepts":[{"term":"Improper integral","definition":"A definite integral with an infinite limit or an unbounded integrand, defined as a limit.","pl":"całka niewłaściwa","slide":null},{"term":"Convergent integral","definition":"An improper integral whose defining limit exists and is finite.","pl":"całka zbieżna","slide":null},{"term":"Divergent integral","definition":"An improper integral whose defining limit is infinite or does not exist.","pl":"całka rozbieżna","slide":null},{"term":"Unbounded integrand","definition":"A function that tends to infinity near some point of the interval of integration.","pl":"funkcja podcałkowa nieograniczona","slide":null},{"term":"p-test","definition":"The rule saying when \\(\\int\\frac{dx}{x^p}\\) converges: on \\([1,\\infty)\\) for \\(p>1\\), on \\((0,1]\\) for \\(p<1\\).","pl":"kryterium dla całek z 1/x^p","slide":null},{"term":"Present value","definition":"The value today of money received in the future, found by discounting.","pl":"wartość bieżąca (obecna)","slide":null},{"term":"Perpetuity","definition":"A stream of payments that continues forever.","pl":"renta wieczysta","slide":null},{"term":"Continuous discounting","definition":"Discounting with the factor \\(e^{-rt}\\), where \\(r\\) is the continuous interest rate.","pl":"dyskontowanie ciągłe","slide":null}],"flashcards":[{"q":"Definition of \\(\\int_a^\\infty f\\,dx\\)?","a":"\\(\\lim_{b\\to\\infty}\\int_a^b f\\,dx\\)","slide":null},{"q":"When does an improper integral converge?","a":"When its defining limit is a finite number.","slide":null},{"q":"For which \\(p\\) does \\(\\int_1^\\infty\\frac{dx}{x^p}\\) converge?","a":"\\(p>1\\) (value \\(\\frac{1}{p-1}\\)).","slide":null},{"q":"For which \\(p\\) does \\(\\int_0^1\\frac{dx}{x^p}\\) converge?","a":"\\(p<1\\) (value \\(\\frac{1}{1-p}\\)).","slide":null},{"q":"\\(\\int_1^\\infty\\frac1x\\,dx\\)?","a":"Diverges (ln b → ∞).","slide":null},{"q":"\\(\\int_0^\\infty e^{-ax}\\,dx\\) for \\(a>0\\)?","a":"\\(\\frac1a\\)","slide":null},{"q":"\\(\\int_{-1}^1\\frac{dx}{x^2}\\)?","a":"Diverges (unbounded at 0).","slide":null},{"q":"Present value of a perpetual stream R at rate r?","a":"\\(\\frac Rr\\)","slide":null},{"q":"\\(\\int_{-\\infty}^\\infty\\frac{dx}{1+x^2}\\)?","a":"\\(\\pi\\)","slide":null}],"quiz":[{"q":"\\(\\int_1^\\infty\\frac{1}{x^2}\\,dx=\\)","options":["it diverges","\\(1\\)","\\(\\frac12\\)","\\(2\\)"],"correct":1,"explanation":"\\(\\lim_{b\\to\\infty}\\left(1-\\frac1b\\right)=1\\). This is the p-test with \\(p=2\\): \\(\\frac{1}{2-1}\\).","slide":null},{"q":"Which integral converges?","options":["\\(\\int_1^\\infty\\frac1x\\,dx\\)","\\(\\int_1^\\infty\\frac{1}{\\sqrt x}\\,dx\\)","\\(\\int_1^\\infty x^{-1.5}\\,dx\\)","\\(\\int_1^\\infty x\\,dx\\)"],"correct":2,"explanation":"Only \\(p=1.5>1\\) passes the p-test; it equals 2.","slide":null},{"q":"\\(\\int_0^1\\frac{1}{x^p}\\,dx\\) converges exactly when:","options":["\\(p>1\\)","\\(p=1\\)","for all \\(p>0\\)","\\(p<1\\)"],"correct":3,"explanation":"Near 0 the function must not grow too fast: \\(p<1\\). Students often mix this up with the \\([1,\\infty)\\) case.","slide":null},{"q":"Income of 2000 PLN per year forever, \\(r=5\\%\\). Present value:","options":["40 000 PLN","100 PLN","2 000 PLN","4 000 PLN"],"correct":0,"explanation":"\\(PV=\\frac Rr=\\frac{2000}{0.05}=40\\,000\\).","slide":null},{"q":"\\(\\int_{-1}^1\\frac{1}{x^2}\\,dx=\\)","options":["\\(-2\\)","\\(2\\)","\\(0\\)","it diverges"],"correct":3,"explanation":"The integrand is unbounded at \\(x=0\\), inside the interval; \\(\\int_0^1\\frac{dx}{x^2}\\) diverges. The answer \\(-2\\) comes from wrongly using Newton–Leibniz.","slide":null},{"q":"\\(\\int_0^\\infty e^{-x}\\,dx=\\)","options":["\\(0\\)","\\(\\infty\\)","\\(1\\)","\\(e\\)"],"correct":2,"explanation":"\\(\\lim_{b\\to\\infty}(1-e^{-b})=1\\).","slide":null},{"q":"True or false: if \\(f(x)\\to0\\) as \\(x\\to\\infty\\), then \\(\\int_1^\\infty f(x)\\,dx\\) converges.","options":["True","False"],"correct":1,"explanation":"Counterexample: \\(\\frac1x\\to0\\), but \\(\\int_1^\\infty\\frac{dx}{x}\\) diverges.","slide":null},{"q":"\\(\\int_0^\\infty Re^{-rt}\\,dt\\) (with \\(R,r>0\\)) equals:","options":["\\(Rr\\)","\\(\\frac Rr\\)","\\(\\frac rR\\)","\\(Re^{-r}\\)"],"correct":1,"explanation":"\\(\\lim_{T\\to\\infty}\\frac Rr(1-e^{-rT})=\\frac Rr\\).","slide":null}],"lang":"en","lesson":{"intro":"Can an infinitely long region have a finite area? Surprisingly, yes. Improper integrals answer this question, and they also tell an investor what a payment that never stops is worth today.","sections":[{"h":"Infinite limits of integration","body":"The Newton–Leibniz formula needs a finite interval. For an infinite one, we integrate up to a number \\(b\\) and then let \\(b\\to\\infty\\):\n\\[\\int_a^\\infty f(x)\\,dx=\\lim_{b\\to\\infty}\\int_a^b f(x)\\,dx.\\]\nIf the limit exists and is finite, the integral converges. If the limit is \\(\\pm\\infty\\) or does not exist, the integral diverges. In the same way \\(\\int_{-\\infty}^b f\\,dx=\\lim_{a\\to-\\infty}\\int_a^b f\\,dx\\).","example":{"task":"Compute \\(\\int_1^\\infty\\frac{1}{x^2}\\,dx\\).","steps":["\\(\\int_1^b x^{-2}\\,dx=\\Big[-\\frac1x\\Big]_1^b=-\\frac1b+1\\).","\\(\\lim_{b\\to\\infty}\\left(1-\\frac1b\\right)=1\\)."],"answer":"The integral converges and equals \\(1\\)."},"tip":"Write the limit explicitly. Writing \\(\\frac{1}{\\infty}\\) on an exam is usually marked as incorrect notation."},{"h":"Convergence and divergence","body":"Not every infinite region has finite area. Compare:\n- \\(\\int_1^\\infty\\frac1x\\,dx=\\lim_{b\\to\\infty}\\ln b=\\infty\\): diverges.\n- \\(\\int_0^\\infty e^{-2x}\\,dx=\\lim_{b\\to\\infty}\\Big[-\\frac12e^{-2x}\\Big]_0^b=\\lim_{b\\to\\infty}\\left(\\frac12-\\frac12e^{-2b}\\right)=\\frac12\\): converges.\n\nWhen both limits are infinite, split at any point (for example 0) and compute two separate improper integrals. The whole integral converges only if BOTH parts converge.","example":{"task":"Compute \\(\\int_{-\\infty}^{\\infty}\\frac{1}{1+x^2}\\,dx\\).","steps":["Split at 0: \\(\\int_{-\\infty}^0+\\int_0^\\infty\\).","\\(\\int_0^\\infty\\frac{dx}{1+x^2}=\\lim_{b\\to\\infty}\\arctan b=\\frac\\pi2\\).","By symmetry \\(\\int_{-\\infty}^0\\frac{dx}{1+x^2}=\\frac\\pi2\\) too.","Sum: \\(\\pi\\)."],"answer":"\\(\\pi\\)"},"tip":"\\(f(x)\\to0\\) as \\(x\\to\\infty\\) is NOT enough for convergence: \\(\\frac1x\\to0\\), yet \\(\\int_1^\\infty\\frac1x\\,dx\\) diverges."},{"h":"Unbounded integrands","body":"If \\(f\\) goes to infinity at an endpoint, say at \\(a\\), we stop a little before it and take a limit:\n\\[\\int_a^b f(x)\\,dx=\\lim_{\\varepsilon\\to0^+}\\int_{a+\\varepsilon}^b f(x)\\,dx.\\]\nIf the problem point \\(c\\) lies INSIDE \\([a,b]\\), split the integral at \\(c\\); both parts must converge.","example":{"task":"Compute \\(\\int_0^1\\frac{1}{\\sqrt x}\\,dx\\) and decide about \\(\\int_{-1}^{1}\\frac{1}{x^2}\\,dx\\).","steps":["\\(\\int_\\varepsilon^1x^{-1/2}dx=\\Big[2\\sqrt x\\Big]_\\varepsilon^1=2-2\\sqrt\\varepsilon\\to2\\). Converges to 2.","In the second integral, \\(\\frac1{x^2}\\) is unbounded at \\(x=0\\), which is inside \\([-1,1]\\). Split: \\(\\int_{-1}^0+\\int_0^1\\).","\\(\\int_\\varepsilon^1x^{-2}dx=\\Big[-\\frac1x\\Big]_\\varepsilon^1=-1+\\frac1\\varepsilon\\to\\infty\\). This part diverges, so the whole integral diverges."],"answer":"\\(\\int_0^1\\frac{dx}{\\sqrt x}=2\\); \\(\\int_{-1}^1\\frac{dx}{x^2}\\) diverges."},"tip":"Careless use of Newton–Leibniz gives \\(\\Big[-\\frac1x\\Big]_{-1}^1=-2\\), a negative 'area' of a positive function. Always check for points where the integrand is undefined."},{"h":"The p-test for \\(1/x^p\\)","body":"These two results are worth memorising, because many tasks reduce to them:\n\\[\\int_1^\\infty\\frac{dx}{x^p}\\ \\text{converges}\\iff p>1\\quad\\left(\\text{value }\\frac{1}{p-1}\\right)\\]\n\\[\\int_0^1\\frac{dx}{x^p}\\ \\text{converges}\\iff p<1\\quad\\left(\\text{value }\\frac{1}{1-p}\\right)\\]\nFor \\(p=1\\) both diverge (logarithm). Intuition: at infinity the function must fall fast (\\(p>1\\)); near zero it must not blow up too fast (\\(p<1\\)).","example":{"task":"Decide convergence and give the value: \\(\\int_1^\\infty x^{-3/2}\\,dx\\), \\(\\int_1^\\infty\\frac{dx}{\\sqrt x}\\), \\(\\int_0^1\\frac{dx}{\\sqrt[3]{x}}\\).","steps":["\\(p=\\frac32>1\\): converges to \\(\\frac{1}{3/2-1}=2\\).","\\(p=\\frac12\\le1\\) on \\([1,\\infty)\\): diverges.","\\(p=\\frac13<1\\) on \\((0,1]\\): converges to \\(\\frac{1}{1-1/3}=\\frac32\\)."],"answer":"\\(2\\); diverges; \\(\\frac32\\)."}},{"h":"Economics: present value of a perpetual income stream","body":"If money arrives continuously at a rate of \\(R\\) per year and the interest rate (continuous compounding) is \\(r\\), then income received at time \\(t\\) is worth \\(Re^{-rt}\\) today. Over \\(T\\) years the present value is\n\\[PV_T=\\int_0^TRe^{-rt}\\,dt=\\frac Rr\\left(1-e^{-rT}\\right).\\]\nFor a stream that never ends (a perpetuity, e.g. rent from land or a perpetual bond):\n\\[PV=\\int_0^\\infty Re^{-rt}\\,dt=\\lim_{T\\to\\infty}\\frac Rr\\left(1-e^{-rT}\\right)=\\frac Rr.\\]\nIf the income grows at rate \\(g<r\\), i.e. \\(R e^{gt}\\), then \\(PV=\\frac{R}{r-g}\\).","example":{"task":"A plot of land gives rent of 12 000 PLN per year forever. The interest rate is \\(r=6\\%\\). What is its present value? Compare with 20 years of rent.","steps":["Perpetuity: \\(PV=\\frac{12\\,000}{0.06}=200\\,000\\) PLN.","20 years: \\(PV_{20}=200\\,000\\left(1-e^{-1.2}\\right)\\approx200\\,000\\cdot0.6988\\approx139\\,761\\) PLN.","So the payments after year 20 are worth only about 60 000 PLN today."],"answer":"\\(PV=200\\,000\\) PLN (about \\(139\\,761\\) PLN for 20 years only)."},"tip":"Use \\(r\\) as a decimal: 6% means \\(r=0.06\\), not 6."}],"formulas":["\\(\\int_a^\\infty f\\,dx=\\lim_{b\\to\\infty}\\int_a^b f\\,dx\\)","\\(\\int_{-\\infty}^{\\infty}f\\,dx=\\int_{-\\infty}^0f\\,dx+\\int_0^\\infty f\\,dx\\) (both must converge)","\\(\\int_a^b f\\,dx=\\lim_{\\varepsilon\\to0^+}\\int_{a+\\varepsilon}^b f\\,dx\\) (f unbounded at a)","\\(\\int_1^\\infty\\frac{dx}{x^p}=\\frac{1}{p-1}\\) for \\(p>1\\); diverges for \\(p\\le1\\)","\\(\\int_0^1\\frac{dx}{x^p}=\\frac{1}{1-p}\\) for \\(p<1\\); diverges for \\(p\\ge1\\)","\\(\\int_0^\\infty e^{-ax}\\,dx=\\frac1a,\\ a>0\\)","\\(PV=\\int_0^\\infty Re^{-rt}\\,dt=\\frac Rr\\)","\\(PV_T=\\frac Rr\\left(1-e^{-rT}\\right)\\)"],"exercises":[{"task":"Compute \\(\\int_1^\\infty\\frac{1}{x^3}\\,dx\\).","hint":"p-test with \\(p=3\\), or integrate to \\(b\\).","answer":"\\(\\frac12\\)"},{"task":"Compute \\(\\int_0^\\infty e^{-3x}\\,dx\\).","hint":"Antiderivative \\(-\\frac13e^{-3x}\\); \\(e^{-3b}\\to0\\).","answer":"\\(\\frac13\\)"},{"task":"Does \\(\\int_1^\\infty\\frac{1}{\\sqrt x}\\,dx\\) converge?","hint":"\\(p=\\frac12\\).","answer":"No: \\(\\Big[2\\sqrt x\\Big]_1^b=2\\sqrt b-2\\to\\infty\\). It diverges."},{"task":"Compute \\(\\int_0^4\\frac{1}{\\sqrt x}\\,dx\\).","hint":"Unbounded at 0; integrate from \\(\\varepsilon\\).","answer":"\\(\\lim_{\\varepsilon\\to0^+}(4-2\\sqrt\\varepsilon)=4\\)"},{"task":"Compute \\(\\int_{-\\infty}^0e^{x}\\,dx\\).","hint":"\\(e^a\\to0\\) as \\(a\\to-\\infty\\).","answer":"\\(1\\)"},{"task":"Compute \\(\\int_0^\\infty xe^{-x}\\,dx\\).","hint":"By parts: \\(\\int xe^{-x}dx=-(x+1)e^{-x}\\); use \\(be^{-b}\\to0\\).","answer":"\\(1\\)"},{"task":"Does \\(\\int_0^2\\frac{1}{(x-1)^2}\\,dx\\) converge?","hint":"Where is the integrand undefined?","answer":"No. At \\(x=1\\) (inside the interval) it is unbounded; \\(\\int_1^2\\frac{dx}{(x-1)^2}\\) already diverges."},{"task":"A perpetual bond pays 5000 PLN per year continuously, and \\(r=4\\%\\). Find its present value. What if the payments grow at 2% per year, i.e. \\(5000e^{0.02t}\\)?","hint":"\\(PV=\\frac Rr\\), and for growth \\(\\frac{R}{r-g}\\).","answer":"\\(\\frac{5000}{0.04}=125\\,000\\) PLN; with growth \\(\\frac{5000}{0.02}=250\\,000\\) PLN."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-18-marginal-elasticity', $lekcja${"tldr":"Economists use the derivative in two main ways. The marginal value (marginal cost, revenue, profit) tells you roughly how much the total changes when output grows by one unit. Elasticity tells you by how many percent a function changes when \\(x\\) grows by 1%. A firm maximises profit where marginal revenue equals marginal cost (MR = MC). Price elasticity of demand tells a shop whether raising the price will bring in more or less revenue.","notes":[{"point":"Marginal value = derivative of the total function: MC = C'(x), MR = R'(x), M\\(\\pi\\) = \\(\\pi'(x)\\).","slide":null},{"point":"\\(C'(x_0)\\) approximates the cost of producing one extra unit after \\(x_0\\) units; always state units in the interpretation.","slide":null},{"point":"Average cost \\(AC = C(x)/x\\) is minimal where \\(MC = AC\\).","slide":null},{"point":"Profit is maximal where MR = MC and \\(\\pi''(x) < 0\\); maximum revenue (MR = 0) is a different point.","slide":null},{"point":"Elasticity \\(E_f(x) = x f'(x)/f(x)\\): the approximate % change of \\(f\\) when \\(x\\) rises by 1%.","slide":null},{"point":"For a power function \\(a x^{\\alpha}\\) the elasticity is constant and equals \\(\\alpha\\).","slide":null},{"point":"Demand is elastic if \\(|E| > 1\\), inelastic if \\(|E| < 1\\), unit elastic if \\(|E| = 1\\).","slide":null},{"point":"With inelastic demand a price rise increases revenue; with elastic demand it decreases revenue; revenue peaks at \\(E = -1\\).","slide":null}],"concepts":[{"term":"Marginal cost","definition":"The derivative of total cost, \\(C'(x)\\); approximately the cost of one more unit.","pl":"koszt krańcowy","slide":null},{"term":"Marginal revenue","definition":"The derivative of total revenue, \\(R'(x)\\); approximately the extra revenue from one more unit sold.","pl":"przychód krańcowy (utarg krańcowy)","slide":null},{"term":"Marginal profit","definition":"The derivative of profit, \\(\\pi'(x) = R'(x) - C'(x)\\).","pl":"zysk krańcowy","slide":null},{"term":"Average cost","definition":"Total cost divided by the number of units, \\(C(x)/x\\).","pl":"koszt przeciętny (średni)","slide":null},{"term":"Elasticity of a function","definition":"\\(E_f(x) = x f'(x)/f(x)\\); the approximate percentage change of \\(f\\) when \\(x\\) rises by 1%.","pl":"elastyczność funkcji","slide":null},{"term":"Price elasticity of demand","definition":"The elasticity of demand with respect to price; shows how strongly buyers react to price changes.","pl":"cenowa elastyczność popytu","slide":null},{"term":"Elastic / inelastic demand","definition":"Elastic: \\(|E| > 1\\), strong reaction; inelastic: \\(|E| < 1\\), weak reaction.","pl":"popyt elastyczny / nieelastyczny","slide":null},{"term":"Unit elastic demand","definition":"Demand with \\(|E| = 1\\); revenue is at its maximum there.","pl":"popyt o elastyczności jednostkowej","slide":null}],"flashcards":[{"q":"What is marginal cost mathematically?","a":"The derivative of total cost, \\(C'(x)\\).","slide":null},{"q":"How do you interpret \\(MC(50) = 12\\)?","a":"Producing the 51st unit costs about 12 extra.","slide":null},{"q":"Condition for maximum profit?","a":"MR = MC and \\(\\pi''(x) < 0\\).","slide":null},{"q":"Where is average cost minimal?","a":"Where MC = AC.","slide":null},{"q":"Formula for elasticity of f at x?","a":"\\(E_f(x) = \\frac{x f'(x)}{f(x)}\\)","slide":null},{"q":"Elasticity of \\(f(x) = 7x^{-3}\\)?","a":"\\(-3\\) (the exponent).","slide":null},{"q":"What does \\(E = -2\\) mean for demand?","a":"1% price rise lowers demand by about 2%; demand is elastic.","slide":null},{"q":"Demand is inelastic. Price goes up. Revenue?","a":"Revenue increases.","slide":null},{"q":"At which elasticity is revenue maximal?","a":"\\(E = -1\\) (unit elasticity).","slide":null},{"q":"Does elasticity have units?","a":"No, it is a pure number (percent per percent).","slide":null}],"quiz":[{"q":"Marginal cost is:","options":["Total cost divided by output","The derivative of total cost \\(C'(x)\\)","The fixed cost","The integral of total cost"],"correct":1,"explanation":"Marginal means derivative, so MC = C'(x). Total cost divided by output is the average cost.","slide":null},{"q":"\\(E_f(x_0) = 2\\). If \\(x\\) increases by 1% from \\(x_0\\), then \\(f\\):","options":["increases by about 2 units","decreases by about 2%","increases by about 2%","increases by about 0.5%"],"correct":2,"explanation":"Elasticity works in percent: 1% more x gives about E% change in f.","slide":null},{"q":"The elasticity of \\(f(x) = 5x^3\\) is:","options":["\\(3\\)","\\(15\\)","\\(15x^2\\)","\\(5\\)"],"correct":0,"explanation":"For \\(a x^{\\alpha}\\) the elasticity equals \\(\\alpha = 3\\); the coefficient 5 cancels.","slide":null},{"q":"Demand with \\(|E| < 1\\) is called:","options":["elastic","unit elastic","perfectly elastic","inelastic"],"correct":3,"explanation":"When the absolute value is below 1, buyers react weakly: inelastic demand.","slide":null},{"q":"A firm maximises profit where:","options":["MR = 0","MR = MC","AC = 0","MC is minimal"],"correct":1,"explanation":"\\(\\pi'(x) = R'(x) - C'(x) = 0\\) gives MR = MC. MR = 0 gives maximum revenue, not profit.","slide":null},{"q":"Demand for a good is inelastic. The shop raises the price slightly. Revenue will:","options":["fall","stay exactly the same","rise","fall to zero"],"correct":2,"explanation":"\\(R'(p) = D(p)(1+E)\\) is positive when \\(-1 < E < 0\\), so revenue rises.","slide":null},{"q":"At the output that minimises average cost, marginal cost equals average cost.","options":["True","False"],"correct":0,"explanation":"Setting \\(AC'(x) = 0\\) gives \\(C'(x) = C(x)/x\\), i.e. MC = AC.","slide":null},{"q":"Demand \\(q = 120 - 3p\\). The price elasticity at \\(p = 30\\) is:","options":["\\(-\\frac{1}{3}\\)","\\(-1\\)","\\(-90\\)","\\(-3\\)"],"correct":3,"explanation":"\\(E = \\frac{30\\cdot(-3)}{120 - 90} = -\\frac{90}{30} = -3\\).","slide":null}],"lang":"en","lesson":{"intro":"Should a bakery bake one more loaf? Should a cinema raise ticket prices? Derivatives answer exactly these questions: marginal values work in units, elasticity works in percent.","sections":[{"h":"Marginal cost, revenue and profit","body":"In economics the word **marginal** means \"the derivative of\". If \\(C(x)\\) is the total cost of producing \\(x\\) units, then the marginal cost is\n\\[ MC(x) = C'(x). \\]\nIn the same way, marginal revenue is \\(MR(x) = R'(x)\\) and marginal profit is \\(M\\pi(x) = \\pi'(x)\\), where \\(\\pi(x) = R(x) - C(x)\\).\n\n**Interpretation:** \\(C'(x_0)\\) is approximately the extra cost of producing one more unit, i.e. of going from \\(x_0\\) to \\(x_0+1\\) units:\n\\[ C(x_0+1) - C(x_0) \\approx C'(x_0). \\]\n- It is an approximation, not an exact value.\n- The units are \"money per unit of product\" (e.g. PLN per item).","example":{"task":"Total cost is \\(C(x) = 0.5x^2 + 10x + 200\\) (PLN). Find the marginal cost at \\(x = 20\\) and interpret it.","steps":["\\(C'(x) = x + 10\\).","\\(C'(20) = 20 + 10 = 30\\).","Check with the exact difference: \\(C(21) - C(20) = 30.5\\), very close to 30."],"answer":"\\(MC(20) = 30\\) PLN: producing the 21st unit costs about 30 PLN extra."},"tip":"In the exam always write the interpretation in words with units. 'MC(20) = 30' alone often does not get full points."},{"h":"Average versus marginal","body":"The **average cost** is the cost per unit:\n\\[ AC(x) = \\frac{C(x)}{x}. \\]\nAverage and marginal are different things. Average cost spreads the whole cost (including fixed cost) over all units. Marginal cost looks only at the next unit.\n\nA useful fact: **at the minimum of average cost, marginal cost equals average cost**, \\(MC = AC\\).\n- If \\(MC < AC\\), producing more pulls the average down.\n- If \\(MC > AC\\), producing more pushes the average up.","example":{"task":"For \\(C(x) = 0.5x^2 + 10x + 200\\), find the output that minimises average cost.","steps":["\\(AC(x) = 0.5x + 10 + \\frac{200}{x}\\).","\\(AC'(x) = 0.5 - \\frac{200}{x^2} = 0 \\Rightarrow x^2 = 400 \\Rightarrow x = 20\\).","\\(AC''(x) = \\frac{400}{x^3} > 0\\), so it is a minimum.","\\(AC(20) = 10 + 10 + 10 = 30\\), and \\(MC(20) = 30\\) too."],"answer":"\\(x = 20\\) units, minimum average cost 30 PLN per unit (equal to MC)."}},{"h":"Optimal output: MR = MC","body":"Profit is \\(\\pi(x) = R(x) - C(x)\\). At a maximum, \\(\\pi'(x) = 0\\), so\n\\[ R'(x) = C'(x) \\quad\\text{i.e.}\\quad MR = MC. \\]\nThen check the second-order condition \\(\\pi''(x) < 0\\).\n\nIntuition: while one more unit brings more revenue than it costs (\\(MR > MC\\)), keep producing. Stop when they are equal.\n\nIf the price depends on quantity (demand \\(p = p(x)\\)), revenue is \\(R(x) = p(x)\\cdot x\\).","example":{"task":"Demand: \\(p = 100 - 2x\\). Cost: \\(C(x) = x^2 + 10x + 100\\). Find the profit-maximising output, price and profit.","steps":["\\(R(x) = (100-2x)x = 100x - 2x^2\\), so \\(MR = 100 - 4x\\).","\\(MC = 2x + 10\\).","\\(100 - 4x = 2x + 10 \\Rightarrow x = 15\\).","\\(\\pi''(x) = -4 - 2 = -6 < 0\\): maximum.","\\(p = 100 - 30 = 70\\); \\(\\pi(15) = 1050 - 475 = 575\\)."],"answer":"\\(x = 15\\), \\(p = 70\\), maximum profit 575."},"tip":"Do not set \\(R'(x) = 0\\) when you want maximum profit. That gives maximum revenue, which is a different point."},{"h":"Elasticity of a function","body":"Elasticity measures relative (percentage) change. The elasticity of \\(f\\) at \\(x\\) is\n\\[ E_f(x) = \\frac{x\\, f'(x)}{f(x)}. \\]\n**Interpretation:** if \\(x\\) increases by 1%, then \\(f(x)\\) changes by approximately \\(E_f(x)\\)%.\n- \\(E = 2\\): \\(f\\) grows about 2% when \\(x\\) grows 1%.\n- \\(E = -0.5\\): \\(f\\) falls about 0.5% when \\(x\\) grows 1%.\n\nElasticity has no units, so we can compare goods measured in kilograms, litres or pieces.\n\n**Power function:** for \\(f(x) = a x^{\\alpha}\\),\n\\[ E_f(x) = \\frac{x \\cdot a\\alpha x^{\\alpha-1}}{a x^{\\alpha}} = \\alpha. \\]\nThe elasticity is constant and equals the exponent.","example":{"task":"Find the elasticity of \\(f(x) = x^2 + 3x\\) at \\(x = 2\\) and interpret it.","steps":["\\(f'(x) = 2x + 3\\).","\\(E_f(x) = \\frac{x(2x+3)}{x^2+3x} = \\frac{2x+3}{x+3}\\).","\\(E_f(2) = \\frac{7}{5} = 1.4\\)."],"answer":"\\(E_f(2) = 1.4\\): if \\(x\\) rises from 2 by 1%, \\(f\\) rises by about 1.4%."}},{"h":"Price elasticity of demand and revenue","body":"Let demand be \\(q = D(p)\\). The price elasticity of demand is\n\\[ E_D(p) = \\frac{p\\, D'(p)}{D(p)}. \\]\nIt is usually negative (higher price, lower demand). We classify by the absolute value:\n- \\(|E| > 1\\): **elastic** demand (buyers react strongly).\n- \\(|E| < 1\\): **inelastic** demand (buyers react weakly).\n- \\(|E| = 1\\): **unit elastic** demand.\n\n**Link to revenue** \\(R(p) = p\\cdot D(p)\\):\n\\[ R'(p) = D(p)\\,\\bigl(1 + E_D(p)\\bigr). \\]\n- Inelastic demand: raising the price **increases** revenue.\n- Elastic demand: raising the price **decreases** revenue.\n- Revenue is largest where \\(E_D(p) = -1\\).","example":{"task":"Demand is \\(q = 120 - 3p\\). Find the elasticity at \\(p = 10, 20, 30\\) and the revenue-maximising price.","steps":["\\(E(p) = \\frac{p\\cdot(-3)}{120 - 3p}\\).","\\(E(10) = -\\frac{30}{90} = -\\frac13\\) (inelastic).","\\(E(20) = -\\frac{60}{60} = -1\\) (unit elastic).","\\(E(30) = -\\frac{90}{30} = -3\\) (elastic).","\\(R(p) = 120p - 3p^2\\), \\(R'(p) = 120 - 6p = 0 \\Rightarrow p = 20\\)."],"answer":"Inelastic at 10, unit elastic at 20, elastic at 30; revenue is maximal at \\(p = 20\\), exactly where \\(E = -1\\)."},"tip":"Do not forget the minus sign. Classify with \\(|E|\\), but report the elasticity value with its sign."}],"formulas":["\\(MC(x) = C'(x),\\; MR(x) = R'(x),\\; M\\pi(x) = \\pi'(x)\\)","\\(C(x_0+1) - C(x_0) \\approx C'(x_0)\\)","\\(AC(x) = \\frac{C(x)}{x}\\); at minimum AC: \\(MC = AC\\)","Max profit: \\(MR = MC\\) and \\(\\pi''(x) < 0\\)","\\(E_f(x) = \\frac{x f'(x)}{f(x)}\\)","\\(f(x) = a x^{\\alpha} \\Rightarrow E_f(x) = \\alpha\\)","\\(|E| > 1\\) elastic, \\(|E| < 1\\) inelastic, \\(|E| = 1\\) unit elastic","\\(R'(p) = D(p)\\,(1 + E_D(p))\\); max revenue at \\(E_D = -1\\)"],"exercises":[{"task":"\\(C(x) = 2x^2 + 5x + 80\\). Find \\(MC(10)\\) and interpret it.","hint":"Differentiate, then substitute \\(x = 10\\).","answer":"\\(C'(x) = 4x + 5\\), \\(MC(10) = 45\\): the 11th unit costs about 45 extra."},{"task":"Find the elasticity of \\(f(x) = 3x^4\\).","hint":"Power function rule.","answer":"\\(E_f(x) = 4\\) for every \\(x > 0\\)."},{"task":"Find the elasticity of \\(f(x) = e^{2x}\\) at \\(x = 3\\).","hint":"\\(f'(x) = 2e^{2x}\\).","answer":"\\(E_f(x) = \\frac{x\\cdot 2e^{2x}}{e^{2x}} = 2x\\), so \\(E_f(3) = 6\\)."},{"task":"\\(C(x) = 2x^2 + 5x + 50\\). Find the output with the lowest average cost and check that \\(MC = AC\\) there.","hint":"\\(AC(x) = 2x + 5 + \\frac{50}{x}\\).","answer":"\\(AC'(x) = 2 - \\frac{50}{x^2} = 0 \\Rightarrow x = 5\\); \\(AC(5) = 25 = MC(5)\\)."},{"task":"Demand \\(q = 50 - 2p\\). Find the price elasticity at \\(p = 10\\). Is demand elastic? What happens to revenue if the price goes up a little?","hint":"\\(E = \\frac{p\\cdot(-2)}{50-2p}\\).","answer":"\\(E(10) = -\\frac{2}{3}\\): inelastic, so a small price rise increases revenue (q falls only about 0.67% per 1% price rise)."},{"task":"Demand is \\(q = 100\\,p^{-0.5}\\). The price rises by 4%. By about how many percent does demand change?","hint":"Power function: elasticity equals the exponent.","answer":"\\(E = -0.5\\), so demand falls by about \\(0.5 \\cdot 4 = 2\\%\\)."},{"task":"Price \\(p = 60 - x\\), cost \\(C(x) = x^2 + 12x + 20\\). Find the profit-maximising output, price and profit.","hint":"\\(MR = 60 - 2x\\), \\(MC = 2x + 12\\).","answer":"\\(x = 12\\), \\(p = 48\\), \\(\\pi = 576 - 308 = 268\\) (\\(\\pi'' = -4 < 0\\))."},{"task":"Demand \\(q = 80 - 4p\\). For which price is demand unit elastic? What is the revenue at that price?","hint":"Solve \\(\\frac{-4p}{80-4p} = -1\\).","answer":"\\(p = 10\\), \\(q = 40\\), revenue \\(R = 400\\) (the maximum revenue)."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
insert into public.nauka_docs (kolekcja, id, data) values ('materialContent', 'an-19-integrals-in-economics', $lekcja${"tldr":"Integration is the reverse of differentiation, so it takes us from marginal functions back to totals. From marginal cost and fixed cost we rebuild total cost; from marginal revenue we rebuild revenue. A definite integral of a marginal function gives the change of the total over an interval. Integrals also measure consumer and producer surplus at market equilibrium, the average value of a quantity over time, and the present value of a continuous income stream.","notes":[{"point":"Total cost is the integral of marginal cost; the integration constant is the fixed cost \\(C(0)\\).","slide":null},{"point":"Revenue is the integral of marginal revenue with \\(R(0) = 0\\); the price function is \\(p = R(x)/x\\).","slide":null},{"point":"\\(\\int_a^b MC(x)\\,dx\\) is the change in total cost from \\(a\\) to \\(b\\) units; fixed cost is not needed.","slide":null},{"point":"Market equilibrium is where demand price equals supply price: \\(D(q_0) = S(q_0) = p_0\\).","slide":null},{"point":"Consumer surplus \\(= \\int_0^{q_0}(D(q) - p_0)\\,dq\\): area between the demand curve and the price line.","slide":null},{"point":"Producer surplus \\(= \\int_0^{q_0}(p_0 - S(q))\\,dq\\): area between the price line and the supply curve.","slide":null},{"point":"Average value on \\([a,b]\\): \\(\\frac{1}{b-a}\\int_a^b f(t)\\,dt\\).","slide":null},{"point":"Present value of a continuous stream: \\(\\int_0^T f(t)e^{-rt}\\,dt\\); for constant \\(c\\) it equals \\(\\frac{c}{r}(1 - e^{-rT})\\).","slide":null}],"concepts":[{"term":"Fixed cost","definition":"The cost that does not depend on output, \\(C(0)\\); it is the integration constant when rebuilding \\(C(x)\\).","pl":"koszt stały","slide":null},{"term":"Total cost","definition":"The whole cost of producing \\(x\\) units; the antiderivative of marginal cost.","pl":"koszt całkowity","slide":null},{"term":"Market equilibrium","definition":"The quantity and price at which demand equals supply.","pl":"równowaga rynkowa","slide":null},{"term":"Consumer surplus","definition":"The total benefit buyers get from paying the market price instead of the higher price they were willing to pay.","pl":"nadwyżka konsumenta","slide":null},{"term":"Producer surplus","definition":"The total benefit sellers get from receiving the market price instead of the lower price they would accept.","pl":"nadwyżka producenta","slide":null},{"term":"Average value of a function","definition":"\\(\\frac{1}{b-a}\\int_a^b f(t)\\,dt\\); the constant level with the same total over \\([a,b]\\).","pl":"wartość średnia funkcji","slide":null},{"term":"Present value","definition":"Today's value of future money, after discounting at the interest rate.","pl":"wartość bieżąca (obecna)","slide":null},{"term":"Continuous income stream","definition":"Income that flows all the time at a rate \\(f(t)\\) per unit of time, not in single payments.","pl":"ciągły strumień dochodu","slide":null}],"flashcards":[{"q":"How do you get total cost from marginal cost?","a":"Integrate MC and set the constant equal to the fixed cost \\(C(0)\\).","slide":null},{"q":"What is \\(R(0)\\) usually equal to?","a":"0 (no sales, no revenue).","slide":null},{"q":"What does \\(\\int_a^b MC(x)\\,dx\\) measure?","a":"The increase in total cost when output goes from \\(a\\) to \\(b\\).","slide":null},{"q":"How do you find market equilibrium?","a":"Solve \\(D(q) = S(q)\\); then \\(p_0 = D(q_0)\\).","slide":null},{"q":"Formula for consumer surplus?","a":"\\(\\int_0^{q_0}(D(q) - p_0)\\,dq\\)","slide":null},{"q":"Formula for producer surplus?","a":"\\(\\int_0^{q_0}(p_0 - S(q))\\,dq\\)","slide":null},{"q":"Average value of \\(f\\) on \\([a,b]\\)?","a":"\\(\\frac{1}{b-a}\\int_a^b f(t)\\,dt\\)","slide":null},{"q":"Present value of a constant stream c over T years at rate r?","a":"\\(\\frac{c}{r}(1 - e^{-rT})\\)","slide":null},{"q":"Is present value bigger or smaller than the undiscounted total?","a":"Smaller (for r > 0).","slide":null},{"q":"How do you get the price function from \\(R(x)\\)?","a":"\\(p(x) = R(x)/x\\)","slide":null}],"quiz":[{"q":"Marginal cost \\(MC(x)\\) and fixed cost \\(FC\\) are known. Total cost is:","options":["\\(\\int MC(x)\\,dx\\) with constant equal to \\(FC\\)","\\(MC'(x) + FC\\)","\\(MC(x) \\cdot x\\)","\\(\\int MC(x)\\,dx\\) with constant equal to 0"],"correct":0,"explanation":"Integration reverses differentiation; the constant is \\(C(0)\\), the fixed cost.","slide":null},{"q":"The increase in total cost when output rises from \\(a\\) to \\(b\\) equals:","options":["\\(MC(b) - MC(a)\\)","\\(\\int_a^b C(x)\\,dx\\)","\\(\\int_a^b MC(x)\\,dx\\)","\\(MC(b)\\cdot(b - a)\\)"],"correct":2,"explanation":"Newton–Leibniz: \\(C(b) - C(a) = \\int_a^b C'(x)\\,dx\\).","slide":null},{"q":"Consumer surplus at equilibrium \\((q_0, p_0)\\) with demand \\(p = D(q)\\) is:","options":["\\(\\int_0^{q_0}(p_0 - D(q))\\,dq\\)","\\(\\int_0^{q_0}(D(q) - p_0)\\,dq\\)","\\(\\int_0^{p_0} D(q)\\,dq\\)","\\(p_0 \\cdot q_0\\)"],"correct":1,"explanation":"CS is the area between the demand curve (above) and the price line (below).","slide":null},{"q":"Demand \\(p = 100 - 2q\\), supply \\(p = 10 + q\\). The equilibrium is:","options":["\\(q_0 = 45,\\ p_0 = 10\\)","\\(q_0 = 40,\\ p_0 = 20\\)","\\(q_0 = 20,\\ p_0 = 60\\)","\\(q_0 = 30,\\ p_0 = 40\\)"],"correct":3,"explanation":"\\(100 - 2q = 10 + q \\Rightarrow 3q = 90 \\Rightarrow q_0 = 30\\), \\(p_0 = 40\\).","slide":null},{"q":"The average value of \\(f\\) on \\([a, b]\\) is:","options":["\\(\\frac{1}{b-a}\\int_a^b f(t)\\,dt\\)","\\(\\frac{f(a) + f(b)}{2}\\)","\\(\\int_a^b f(t)\\,dt\\)","\\(\\frac{f(b) - f(a)}{b - a}\\)"],"correct":0,"explanation":"Divide the total (the integral) by the length of the interval. \\(\\frac{f(b)-f(a)}{b-a}\\) is the average rate of change, not the average value.","slide":null},{"q":"Present value of a constant stream \\(c\\) per year for \\(T\\) years at continuous rate \\(r\\):","options":["\\(c\\,T\\,e^{-rT}\\)","\\(c\\,e^{rT}\\)","\\(\\frac{c}{r}(1 - e^{-rT})\\)","\\(\\frac{c}{r}e^{-rT}\\)"],"correct":2,"explanation":"\\(\\int_0^T c\\,e^{-rt}\\,dt = \\frac{c}{r}(1 - e^{-rT})\\).","slide":null},{"q":"With a positive interest rate, the present value of an income stream is larger than the total undiscounted income.","options":["True","False"],"correct":1,"explanation":"Discounting makes every future payment worth less today, since \\(e^{-rt} < 1\\) for \\(t > 0\\).","slide":null},{"q":"\\(MR(x) = 50 - 2x\\) and \\(R(0) = 0\\). The revenue function is:","options":["\\(R(x) = -2\\)","\\(R(x) = 50 - x^2\\)","\\(R(x) = 50x - 2x^2\\)","\\(R(x) = 50x - x^2\\)"],"correct":3,"explanation":"\\(\\int(50 - 2x)\\,dx = 50x - x^2 + K\\) and \\(R(0) = 0\\) gives \\(K = 0\\).","slide":null}],"lang":"en","lesson":{"intro":"In the last lesson we went from total to marginal by differentiating. Now we go back: if you know how fast something changes, the integral tells you how much it adds up to.","sections":[{"h":"From marginal back to total","body":"If \\(C'(x) = MC(x)\\), then total cost is an antiderivative of marginal cost:\n\\[ C(x) = \\int MC(x)\\,dx = F(x) + K. \\]\nThe constant \\(K\\) is found from extra information. Usually it is the **fixed cost** \\(FC = C(0)\\).\n\nFor revenue the extra information is usually \\(R(0) = 0\\) (no sales, no revenue). Once you have \\(R(x)\\), the demand (price) function is \\(p(x) = \\frac{R(x)}{x}\\).","example":{"task":"Marginal cost is \\(MC(x) = 4x + 20\\) and fixed cost is 100. Find \\(C(x)\\).","steps":["\\(\\int (4x + 20)\\,dx = 2x^2 + 20x + K\\).","\\(C(0) = K = 100\\)."],"answer":"\\(C(x) = 2x^2 + 20x + 100\\)."},"tip":"Never drop the constant. In cost problems the constant is the fixed cost and the exam checks it."},{"h":"Change of a total over an interval","body":"By the Newton–Leibniz formula,\n\\[ C(b) - C(a) = \\int_a^b MC(x)\\,dx. \\]\nThis is the extra cost of raising production from \\(a\\) to \\(b\\) units. You do **not** need the fixed cost here, because it cancels.\n\nThe same works for revenue, profit, or any quantity given by its rate of change.","example":{"task":"\\(MC(x) = 4x + 20\\). How much does total cost increase when output goes from 10 to 20 units?","steps":["\\(\\int_{10}^{20} (4x + 20)\\,dx = \\bigl[2x^2 + 20x\\bigr]_{10}^{20}\\).","\\(= (800 + 400) - (200 + 200) = 1200 - 400\\)."],"answer":"Cost increases by 800."}},{"h":"Consumer and producer surplus","body":"Let \\(p = D(q)\\) be the demand curve (falling) and \\(p = S(q)\\) the supply curve (rising). Market **equilibrium** \\((q_0, p_0)\\) is where \\(D(q_0) = S(q_0) = p_0\\).\n\n**Consumer surplus** (CS): buyers who were ready to pay more than \\(p_0\\) save money.\n\\[ CS = \\int_0^{q_0} \\bigl(D(q) - p_0\\bigr)\\,dq \\]\n**Producer surplus** (PS): sellers who would accept less than \\(p_0\\) gain.\n\\[ PS = \\int_0^{q_0} \\bigl(p_0 - S(q)\\bigr)\\,dq \\]\nGeometrically: CS is the area between the demand curve and the line \\(p = p_0\\); PS is the area between that line and the supply curve.","example":{"task":"Demand \\(p = 100 - 2q\\), supply \\(p = 10 + q\\). Find the equilibrium, CS and PS.","steps":["\\(100 - 2q = 10 + q \\Rightarrow q_0 = 30\\), \\(p_0 = 40\\).","\\(CS = \\int_0^{30} (100 - 2q - 40)\\,dq = \\int_0^{30}(60 - 2q)\\,dq = 1800 - 900 = 900\\).","\\(PS = \\int_0^{30} (40 - 10 - q)\\,dq = \\int_0^{30}(30 - q)\\,dq = 900 - 450 = 450\\)."],"answer":"Equilibrium \\(q_0 = 30\\), \\(p_0 = 40\\); \\(CS = 900\\), \\(PS = 450\\)."},"tip":"Integrate over quantity from 0 to \\(q_0\\), not over price. For straight lines you can check with the triangle area \\(\\frac12 \\cdot\\) base \\(\\cdot\\) height."},{"h":"Average value over time","body":"The average value of \\(f\\) on \\([a, b]\\) is\n\\[ \\bar f = \\frac{1}{b - a}\\int_a^b f(t)\\,dt. \\]\nUse it for average sales per month, average price over a year, average stock level, etc. It is the constant level that would give the same total as \\(f\\) over the interval.","example":{"task":"Monthly sales (thousand units) are \\(S(t) = 3t^2 + 2\\), \\(t\\) in months. Find the average sales level over the first 4 months.","steps":["\\(\\int_0^4 (3t^2 + 2)\\,dt = \\bigl[t^3 + 2t\\bigr]_0^4 = 64 + 8 = 72\\).","\\(\\bar S = \\frac{72}{4} = 18\\)."],"answer":"Average sales level: 18 thousand units per month."}},{"h":"Present value of a continuous income stream","body":"Money received in the future is worth less today. With continuous compounding at rate \\(r\\), 1 PLN received at time \\(t\\) is worth \\(e^{-rt}\\) PLN today.\n\nIf income flows continuously at rate \\(f(t)\\) (PLN per year) for \\(T\\) years, its **present value** is\n\\[ PV = \\int_0^T f(t)\\,e^{-rt}\\,dt. \\]\nFor a constant stream \\(f(t) = c\\):\n\\[ PV = \\frac{c}{r}\\bigl(1 - e^{-rT}\\bigr). \\]\nThe present value is always smaller than the plain total \\(cT\\), because of discounting.","example":{"task":"An investment pays 1000 PLN per year continuously for 10 years. The interest rate is 5% (continuous). Find the present value.","steps":["\\(PV = \\int_0^{10} 1000\\,e^{-0.05t}\\,dt\\).","\\(= \\frac{1000}{0.05}\\bigl(1 - e^{-0.5}\\bigr) = 20000\\,(1 - e^{-0.5})\\).","\\(e^{-0.5} \\approx 0.6065\\), so \\(PV \\approx 20000 \\cdot 0.3935\\)."],"answer":"\\(PV \\approx 7869.39\\) PLN (compared with 10 000 PLN without discounting)."},"tip":"Write the rate as a decimal: 5% is \\(r = 0.05\\), not 5."}],"formulas":["\\(C(x) = \\int MC(x)\\,dx\\), constant \\(= FC = C(0)\\)","\\(R(x) = \\int MR(x)\\,dx\\), with \\(R(0) = 0\\); \\(p(x) = R(x)/x\\)","\\(C(b) - C(a) = \\int_a^b MC(x)\\,dx\\)","Equilibrium: \\(D(q_0) = S(q_0) = p_0\\)","\\(CS = \\int_0^{q_0} (D(q) - p_0)\\,dq\\)","\\(PS = \\int_0^{q_0} (p_0 - S(q))\\,dq\\)","\\(\\bar f = \\frac{1}{b-a}\\int_a^b f(t)\\,dt\\)","\\(PV = \\int_0^T f(t)e^{-rt}\\,dt\\); constant \\(c\\): \\(PV = \\frac{c}{r}(1 - e^{-rT})\\)"],"exercises":[{"task":"\\(MC(x) = 6x + 10\\), fixed cost 40. Find \\(C(x)\\) and \\(C(5)\\).","hint":"Integrate and use C(0) = 40.","answer":"\\(C(x) = 3x^2 + 10x + 40\\), \\(C(5) = 165\\)."},{"task":"\\(MR(x) = 120 - 6x\\). Find the revenue function and the demand (price) function.","hint":"\\(R(0) = 0\\), then \\(p = R/x\\).","answer":"\\(R(x) = 120x - 3x^2\\), \\(p(x) = 120 - 3x\\)."},{"task":"With \\(MR(x) = 120 - 6x\\), how much does revenue change when sales go from 10 to 15 units?","hint":"\\(\\int_{10}^{15} MR(x)\\,dx\\).","answer":"\\(\\bigl[120x - 3x^2\\bigr]_{10}^{15} = 1125 - 900 = 225\\)."},{"task":"The price is \\(P(t) = 10 + 2t\\) (PLN), \\(t\\) in months. Find the average price over the first 6 months.","hint":"Divide the integral by \\(6 - 0\\).","answer":"\\(\\frac{1}{6}\\int_0^6 (10 + 2t)\\,dt = \\frac{96}{6} = 16\\) PLN."},{"task":"Demand \\(p = 35 - 2q\\), supply \\(p = 5 + q\\). Find the equilibrium, consumer surplus and producer surplus.","hint":"Set demand equal to supply first.","answer":"\\(q_0 = 10\\), \\(p_0 = 15\\); \\(CS = \\int_0^{10}(20 - 2q)\\,dq = 100\\), \\(PS = \\int_0^{10}(10 - q)\\,dq = 50\\)."},{"task":"Demand \\(p = 64 - q^2\\). The market price is 48. Find the consumer surplus.","hint":"First find \\(q_0\\) from \\(64 - q^2 = 48\\).","answer":"\\(q_0 = 4\\); \\(CS = \\int_0^4 (16 - q^2)\\,dq = 64 - \\frac{64}{3} = \\frac{128}{3} \\approx 42.67\\)."},{"task":"Find the present value of an income stream of 2000 PLN per year for 5 years at a continuous rate of 4%.","hint":"\\(PV = \\frac{c}{r}(1 - e^{-rT})\\).","answer":"\\(PV = 50000(1 - e^{-0.2}) \\approx 9063.46\\) PLN."},{"task":"\\(MC(x) = 3x^2 - 12x + 20\\), fixed cost 50. Find \\(C(x)\\) and the cost of raising output from 2 to 4 units.","hint":"Integrate; for the change, the fixed cost cancels.","answer":"\\(C(x) = x^3 - 6x^2 + 20x + 50\\); \\(C(4) - C(2) = 98 - 74 = 24\\)."}]}}$lekcja$::jsonb)
  on conflict (kolekcja, id) do update set data = excluded.data;
